poetry_data = [
    {"title": "寥落古行宫，宫花寂寞红。", "content": "白头宫女在，闲坐说玄宗。"},
    {"title": "白日依山尽，黄河入海流。", "content": "欲穷千里目，更上一层楼。"},
    {"title": "三日入厨下，洗手作羹汤。", "content": "未谙姑食性，先遣小姑尝。"},
    {"title": "红豆生南国，春来发几枝。", "content": "愿君多采撷，此物最相思。"},
    {"title": "君自故乡来，应知故乡事。", "content": "来日绮窗前，寒梅著花未？"},
    {"title": "空山不见人，但闻人语响。", "content": "返景入深林，复照青苔上。"},
    {"title": "独坐幽篁里，弹琴复长啸。", "content": "深林人不知，明月来相照。"},
    {"title": "山中相送罢，日暮掩柴扉。", "content": "春草明年绿，王孙归不归？(明年 一作：年年)"},
    {"title": "绿蚁新醅酒，红泥小火炉。", "content": "晚来天欲雪，能饮一杯无？"},
    {"title": "北斗七星高，哥舒夜带刀。", "content": "至今窥牧马，不敢过临洮。"},
    {"title": "床前明月光，疑是地上霜。", "content": "举头望明月，低头思故乡。"},
    {"title": "美人卷珠帘，深坐蹙蛾眉。", "content": "(蹙 一作：颦)但见泪痕湿，不知心恨谁。"},
    {"title": "向晚意不适，驱车登古原。", "content": "夕阳无限好，只是近黄昏。"},
    {"title": "鸣筝金粟柱，素手玉房前。", "content": "欲得周郎顾，时时误拂弦。"},
    {"title": "岭外音书断，经冬复历春。", "content": "近乡情更怯，不敢问来人。"},
    {"title": "功盖三分国，名成八阵图。", "content": "（名成 一作：名高）江流石不转，遗恨失吞吴。"},
    {"title": "移舟泊烟渚，日暮客愁新。", "content": "野旷天低树，江清月近人。"},
    {"title": "春眠不觉晓，处处闻啼鸟。", "content": "夜来风雨声，花落知多少。"},
    {"title": "打起黄莺儿，莫教枝上啼。", "content": "啼时惊妾梦，不得到辽西。"},
    {"title": "千山鸟飞绝，万径人踪灭。", "content": "孤舟蓑笠翁，独钓寒江雪。"},
    {"title": "怀君属秋夜，散步咏凉天。", "content": "空山松子落，幽人应未眠。(空山 一作：山空)"},
    {"title": "终南阴岭秀，积雪浮云端。", "content": "林表明霁色，城中增暮寒。"},
    {"title": "故国三千里，深宫二十年。", "content": "一声何满子，双泪落君前。"},
    {"title": "松下问童子，言师采药去。", "content": "只在此山中，云深不知处。"},
    {"title": "归山深浅去，须尽丘壑美。", "content": "莫学武陵人，暂游桃源里。"},
    {"title": "苍苍竹林寺，杳杳钟声晚。", "content": "荷笠带斜阳，青山独归远。(斜阳 一作：夕阳)"},
    {"title": "泠泠七弦上，静听松风寒。", "content": "(七弦 一作：七丝)古调虽自爱，今人多不弹。"},
    {"title": "孤云将野鹤，岂向人间住。", "content": "莫买沃洲山，时人已知处。"},
    {"title": "昨夜裙带解，今朝蟢子飞。", "content": "铅华不可弃，莫是藁砧归。"},
    {"title": "寒雨连江夜入吴，平明送客楚山孤。", "content": "洛阳亲友如相问，一片冰心在玉壶。"},
    {"title": "闺中不知愁，春日凝妆上翠楼。", "content": "(不知 一作：不曾)忽见陌头杨柳色，悔教夫婿觅封侯。"},
    {"title": "昨夜风开露井桃，未央前殿月轮高。", "content": " 平阳歌舞新承宠，帘外春寒赐锦袍。"},
    {"title": "独在异乡为异客，每逢佳节倍思亲。", "content": "遥知兄弟登高处，遍插茱萸少一人。"},
    {"title": "葡萄美酒夜光杯，欲饮琵琶马上催。", "content": "醉卧沙场君莫笑，古来征战几人回？"},
    {"title": "泪湿罗巾梦不成，夜深前殿按歌声。", "content": "(湿 一作：尽)红颜未老恩先断，斜倚薰笼坐到明。"},
    {"title": "寂寂花时闭院门，美人相并立琼轩。", "content": " 含情欲说宫中事，鹦鹉前头不敢言。"},
    {"title": "洞房昨夜停红烛，待晓堂前拜舅姑。", "content": " 妆罢低声问夫婿，画眉深浅入时无。"},
    {"title": "故园东望路漫漫，双袖龙钟泪不干。", "content": " 马上相逢无纸笔，凭君传语报平安。"},
    {"title": "故人西辞黄鹤楼，烟花三月下扬州。", "content": "孤帆远影碧空尽，唯见长江天际流。 (唯 通：惟)"},
    {"title": "朝辞白帝彩云间，千里江陵一日还。", "content": "两岸猿声啼不住，轻舟已过万重山。"},
    {"title": "回乐烽前沙似雪，受降城外月如霜。", "content": "(回乐烽 一作：回乐峰)不知何处吹芦管，一夜征人尽望乡。"},
    {"title": "宣室求贤访逐臣，贾生才调更无伦。", "content": "可怜夜半虚前席，不问苍生问鬼神。"},
    {"title": "乘兴南游不戒严，九重谁省谏书函。", "content": " 春风举国裁宫锦，半作障泥半作帆。"},
    {"title": "瑶池阿母绮窗开，黄竹歌声动地哀。", "content": " 八骏日行三万里，穆王何事不重来。"},
    {"title": "云母屏风烛影深，长河渐落晓星沉。", "content": "嫦娥应悔偷灵药，碧海青天夜夜心。"},
    {"title": "君问归期未有期，巴山夜雨涨秋池。", "content": " 何当共剪西窗烛，却话巴山夜雨时。"},
    {"title": "嵩云秦树久离居，双鲤迢迢一纸书。", "content": " 休问梁园旧宾客，茂陵秋雨病相如。"},
    {"title": "为有云屏无限娇，凤城寒尽怕春宵。", "content": " 无端嫁得金龟婿，辜负香衾事早朝。"},
    {"title": "岐王宅里寻常见，崔九堂前几度闻。", "content": "正是江南好风景，落花时节又逢君。"},
    {"title": "娉娉袅袅十三余，豆蔻梢头二月初。", "content": "春风十里扬州路，卷上珠帘总不如。"},
    {"title": "多情却似总无情，唯觉尊前笑不成。", "content": "(尊 一作：樽)蜡烛有心还惜别，替人垂泪到天明。"},
    {"title": "繁华事散逐香尘，流水无情草自春。", "content": "日暮东风怨啼鸟，落花犹似坠楼人。"},
    {"title": "青山隐隐水迢迢，秋尽江南草未凋。", "content": "二十四桥明月夜，玉人何处教吹箫？"},
    {"title": "落魄江湖载酒行，楚腰纤细掌中轻。", "content": "(江湖 一作：江南；纤细 一作：肠断)十年一觉扬州梦，赢得青青薄幸名。"},
    {"title": "银烛秋光冷画屏，轻罗小扇扑流萤。", "content": "天阶夜色凉如水，卧看牵牛织女星。(天阶 一作：天街；卧看 一作：坐看)"},
    {"title": "清时有味是无能，闲爱孤云静爱僧。", "content": " 欲把一麾江海去，乐游原上望昭陵。"},
    {"title": "折戟沉沙铁未销，自将磨洗认前朝。", "content": "东风不与周郎便，铜雀春深锁二乔。"},
    {"title": "烟笼寒水月笼沙，夜泊秦淮近酒家。", "content": "商女不知亡国恨，隔江犹唱后庭花。"},
    {"title": "岁岁金河复玉关，朝朝马策与刀环。", "content": " 三春白雪归青冢，万里黄河绕黑山。"},
    {"title": "谁谓伤心画不成，画人心逐世人情。", "content": " 君看六幅南朝事，老木寒云满故城。"},
    {"title": "独怜幽草涧边生，上有黄鹂深树鸣。", "content": " 春潮带雨晚来急，野渡无人舟自横。"},
    {"title": "隐隐飞桥隔野烟，石矶西畔问渔船。", "content": " 桃花尽日随流水，洞在清溪何处边。"},
    {"title": "别梦依依到谢家，小廊回合曲阑斜。", "content": "多情只有春庭月，犹为离人照落花。"},
    {"title": "金陵津渡小山楼，一宿行人自可愁。", "content": " 潮落夜江斜月里，两三星火是瓜洲。"},
    {"title": "禁门宫树月痕过，媚眼惟看宿鹭窠。", "content": "斜拔玉钗灯影畔，剔开红焰救飞蛾。"},
    {"title": "日光斜照集灵台，红树花迎晓露开。", "content": " 昨夜上皇新授箓，太真含笑入帘来。"},
    {"title": "虢国夫人承主恩，平明骑马入宫门。", "content": "却嫌脂粉污颜色，淡扫蛾眉朝至尊。"},
    {"title": "月落乌啼霜满天，江枫渔火对愁眠。", "content": "姑苏城外寒山寺，夜半钟声到客船。"},
    {"title": "誓扫匈奴不顾身，五千貂锦丧胡尘。", "content": "可怜无定河边骨，犹是春闺梦里人！(春闺 一作：深闺)"},
    {"title": "近寒食雨草萋萋，著麦苗风柳映堤。", "content": "等是有家归未得，杜鹃休向耳边啼。(等 一作：早)"},
    {"title": "少小离家老大回，乡音无改鬓毛衰。", "content": "儿童相见不相识，笑问客从何处来。"},
    {"title": "冰簟银床梦不成，碧天如水夜云轻。", "content": " 雁声远过潇湘去，十二楼中月自明。"},
    {"title": "更深月色半人家，北斗阑干南斗斜。", "content": " 今夜偏知春气暖，虫声新透绿窗纱。"},
    {"title": "纱窗日落渐黄昏，金屋无人见泪痕。", "content": " 寂寞空庭春欲晚，梨花满地不开门。"},
    {"title": "朱雀桥边野草花，乌衣巷口夕阳斜。", "content": " 旧时王谢堂前燕，飞入寻常百姓家。"},
    {"title": "新妆宜面下朱楼，深锁春光一院愁。", "content": " 行到中庭数花朵，蜻蜓飞上玉搔头。"},
    {"title": "玄宗回马杨妃死，云雨难忘日月新。", "content": "(难忘 一作：虽忘)终是圣明天子事，景阳宫井又何人。"},
    {"title": "春城无处不飞花，寒食东风御柳斜。", "content": " 日暮汉宫传蜡烛，轻烟散入五侯家。"},
    {"title": "碧阑干外绣帘垂，猩色屏风画折枝。", "content": "(猩色 一作：猩血)八尺龙须方锦褥，已凉天气未寒时。"},
    {"title": "长乐宫连上苑春，玉楼金殿艳歌新。", "content": " 君门一入无由出，唯有宫莺得见人。"},
    {"title": "城阙辅三秦，风烟望五津。", "content": "与君离别意，同是宦游人。海内存知己，天涯若比邻。无为在歧路，儿女共沾巾。"},
    {"title": "万壑树参天，千山响杜鹃。", "content": "山中一夜雨，树杪百重泉。汉女输橦布，巴人讼芋田。文翁翻教授，不敢倚先贤。"},
    {"title": "楚塞三湘接，荆门九派通。", "content": "江流天地外，山色有无中。郡邑浮前浦，波澜动远空。襄阳好风日，留醉与山翁。"},
    {"title": "中岁颇好道，晚家南山陲。", "content": "兴来每独往，胜事空自知。行到水穷处，坐看云起时。偶然值林叟，谈笑无还期。"},
    {"title": "太乙近天都，连山接海隅。", "content": "(接 一作：到)白云回望合，青霭入看无。分野中峰变，阴晴众壑殊。欲投人处宿，隔水问樵夫。"},
    {"title": "晚年唯好静，万事不关心。", "content": "(唯 一作：惟)自顾无长策，空知返旧林。松风吹解带，山月照弹琴。君问穷通理，渔歌入浦深。"},
    {"title": "不知香积寺，数里入云峰。", "content": "古木无人径，深山何处钟。泉声咽危石，日色冷青松。薄暮空潭曲，安禅制毒龙。"},
    {"title": "寒山转苍翠，秋水日潺湲。", "content": "倚杖柴门外，临风听暮蝉。渡头馀落日，墟里上孤烟。(馀 一作：余)复值接舆醉，狂歌五柳前。"},
    {"title": "空山新雨后，天气晚来秋。", "content": "明月松间照，清泉石上流。竹喧归浣女，莲动下渔舟。随意春芳歇，王孙自可留。"},
    {"title": "清川带长薄，车马去闲闲。", "content": "流水如有意，暮禽相与还。荒城临古渡，落日满秋山。迢递嵩高下，归来且闭关。"},
    {"title": "客路青山外，行舟绿水前。", "content": "潮平两岸阔，风正一帆悬。海日生残夜，江春入旧年。乡书何处达？归雁洛阳边。"},
    {"title": "故人江海别，几度隔山川。", "content": "乍见翻疑梦，相悲各问年。孤灯寒照雨，深竹暗浮烟。(深竹 一作：湿竹)更有明朝恨，离杯惜共传。"},
    {"title": "静夜四无邻，荒居旧业贫。", "content": "雨中黄叶树，灯下白头人。以我独沉久，愧君相见频。平生自有分，况是蔡家亲。"},
    {"title": "世乱同南去，时清独北还。", "content": "他乡生白发，旧国见青山。 晓月过残垒，繁星宿故关。寒禽与衰草，处处伴愁颜。"},
    {"title": "离离原上草，一岁一枯荣。", "content": "野火烧不尽，春风吹又生。远芳侵古道，晴翠接荒城。又送王孙去，萋萋满别情。"},
    {"title": "阳月南飞雁，传闻至此回。", "content": "我行殊未已，何日复归来。江静潮初落，林昏瘴不开。明朝望乡处，应见陇头梅。"},
    {"title": "联步趋丹陛，分曹限紫微。", "content": "晓随天仗入，暮惹御香归。白发悲花落，青云羡鸟飞。圣朝无阙事，自觉谏书稀。"},
    {"title": "蜀僧抱绿绮，西下峨眉峰。", "content": "为我一挥手，如听万壑松。 客心洗流水，馀响入霜钟。不觉碧山暮，秋云暗几重。"},
    {"title": "牛渚西江夜，青天无片云。", "content": "登舟望秋月，空忆谢将军。余亦能高咏，斯人不可闻。明朝挂帆席，枫叶落纷纷。(席 一作：去)"},
    {"title": "吾爱孟夫子，风流天下闻。", "content": "红颜弃轩冕，白首卧松云。 醉月频中圣，迷花不事君。高山安可仰，徒此揖清芬。"},
    {"title": "渡远荆门外，来从楚国游。", "content": "山随平野尽，江入大荒流。月下飞天镜，云生结海楼。仍怜故乡水，万里送行舟。"},
    {"title": "青山横北郭，白水绕东城。", "content": "此地一为别，孤蓬万里征。浮云游子意，落日故人情。挥手自兹去，萧萧班马鸣。"},
    {"title": "十年离乱后，长大一相逢。", "content": "问姓惊初见，称名忆旧容。别来沧海事，语罢暮天钟。明日巴陵道，秋山又几重。"},
    {"title": "客去波平槛，蝉休露满枝。", "content": "永怀当此节，倚立自移时。北斗兼春远，南陵寓使迟。天涯占梦数，疑误有新知。"},
    {"title": "残阳西入崦，茅屋访孤僧。", "content": "落叶人何在，寒云路几层。 独敲初夜磬，闲倚一枝藤。世界微尘里，吾宁爱与憎。"},
    {"title": "本以高难饱，徒劳恨费声。", "content": "五更疏欲断，一树碧无情。薄宦梗犹泛，故园芜已平。烦君最相警，我亦举家清。"},
    {"title": "凄凉宝剑篇，羁泊欲穷年。", "content": "黄叶仍风雨，青青自管弦。新知遭薄俗，旧好隔良缘。心断新丰酒，销愁斗几千。"},
    {"title": "高阁客竟去，小园花乱飞。", "content": "参差连曲陌，迢递送斜晖。肠断未忍扫，眼穿仍欲归。芳心向春尽，所得是沾衣。"},
    {"title": "昔闻洞庭水，今上岳阳楼。", "content": "吴楚东南坼，乾坤日夜浮。亲朋无一字，老病有孤舟。戎马关山北，凭轩涕泗流。"},
    {"title": "远送从此别，青山空复情。", "content": "几时杯重把，昨夜月同行。列郡讴歌惜，三朝出入荣。江村独归处，寂寞养残生。"},
    {"title": "他乡复行役，驻马别孤坟。", "content": "近泪无干土，低空有断云。对棋陪谢傅，把剑觅徐君。唯见林花落，莺啼送客闻。"},
    {"title": "细草微风岸，危樯独夜舟。", "content": "星垂平野阔，月涌大江流。名岂文章著，官应老病休。飘飘何所似，天地一沙鸥。"},
    {"title": "此道昔归顺，西郊胡正繁。", "content": "至今残破胆，应有未招魂。近侍归京邑，移官岂至尊。无才日衰老，驻马望千门。"},
    {"title": "戍鼓断人行，边秋一雁声。", "content": "(边秋 一作:秋边)露从今夜白，月是故乡明。有弟皆分散，无家问死生。寄书长不达，况乃未休兵。"},
    {"title": "凉风起天末，君子意如何。", "content": "鸿雁几时到，江湖秋水多。文章憎命达，魑魅喜人过。应共冤魂语，投诗赠汨罗。"},
    {"title": "今夜鄜州月，闺中只独看。", "content": "遥怜小儿女，未解忆长安。香雾云鬟湿，清辉玉臂寒。何时倚虚幌，双照泪痕干。"},
    {"title": "国破山河在，城春草木深。", "content": "感时花溅泪，恨别鸟惊心。烽火连三月，家书抵万金。白头搔更短，浑欲不胜簪。"},
    {"title": "花隐掖垣暮，啾啾栖鸟过。", "content": "星临万户动，月傍九霄多。 不寝听金钥，因风想玉珂。明朝有封事，数问夜如何。"},
    {"title": "旅馆无良伴，凝情自悄然。", "content": "寒灯思旧事，断雁警愁眠。远梦归侵晓，家书到隔年。沧江好烟月，门系钓鱼船。"},
    {"title": "早被婵娟误，欲妆临镜慵。", "content": "承恩不在貌，教妾若为容。 风暖鸟声碎，日高花影重。年年越溪女，相忆采芙蓉。"},
    {"title": "独有宦游人，偏惊物候新。", "content": "云霞出海曙，梅柳渡江春。淑气催黄鸟，晴光转绿蘋。忽闻歌古调，归思欲沾巾。(巾 一作：襟)"},
    {"title": "闻道黄龙戍，频年不解兵。", "content": "可怜闺里月，长在汉家营。得我今春意，良人昨夜情。谁能将旗鼓，一为取龙城。"},
    {"title": "山暝听猿愁，沧江急夜流。", "content": "风鸣两岸叶，月照一孤舟。建德非吾土，维扬忆旧游。还将两行泪，遥寄海西头。"},
    {"title": "寂寂竟何待，朝朝空自归。", "content": "欲寻芳草去，惜与故人违。当路谁相假，知音世所稀。只应守寂寞，还掩故园扉。(寂 一作：索)"},
    {"title": "木落雁南度，北风江上寒。", "content": "我家襄水曲，遥隔楚云端。乡泪客中尽，孤帆天际看。(孤帆 一作：归帆)迷津欲有问，平海夕漫漫。"},
    {"title": "北阙休上书，南山归敝庐。", "content": "不才明主弃，多病故人疏。白发催年老，青阳逼岁除。永怀愁不寐，松月夜窗虚。"},
    {"title": "故人具鸡黍，邀我至田家。", "content": "绿树村边合，青山郭外斜。开轩面场圃，把酒话桑麻。待到重阳日，还来就菊花。"},
    {"title": "一丘常欲卧，三径苦无资。", "content": "北土非吾愿，东林怀我师。黄金燃桂尽，壮志逐年衰。日夕凉风至，闻蝉但益悲。"},
    {"title": "八月湖水平，涵虚混太清。", "content": "气蒸云梦泽，波撼岳阳城。欲济无舟楫，端居耻圣明。坐观垂钓者，徒有羡鱼情。"},
    {"title": "人事有代谢，往来成古今。", "content": "江山留胜迹，我辈复登临。水落鱼梁浅，天寒梦泽深。羊公碑尚在，读罢泪沾襟。(尚在 一作：字在)"},
    {"title": "林卧愁春尽，搴帷览物华。", "content": "忽逢青鸟使，邀入赤松家。金灶初开火，仙桃正发花。童颜若可驻，何惜醉流霞。"},
    {"title": "清瑟怨遥夜，绕弦风雨哀。", "content": "孤灯闻楚角，残月下章台。芳草已云暮，故人殊未来。乡书不可寄，秋雁又南回。"},
    {"title": "江汉曾为客，相逢每醉还。", "content": "浮云一别后，流水十年间。欢笑情如旧，萧疏鬓已斑。何因不归去？淮上有秋山。"},
    {"title": "楚江微雨里，建业暮钟时。", "content": "漠漠帆来重，冥冥鸟去迟。海门深不见，浦树远含滋。相送情无限，沾襟比散丝。"},
    {"title": "夫子何为者，栖栖一代中。", "content": "地犹鄹氏邑，宅即鲁王宫。叹凤嗟身否，伤麟怨道穷。今看两楹奠，当与梦时同。"},
    {"title": "灞原风雨定，晚见雁行频。", "content": "落叶他乡树，寒灯独夜人。空园白露滴，孤壁野僧邻。寄卧郊扉久，何年致此身。"},
    {"title": "露气寒光集，微阳下楚丘。", "content": "猿啼洞庭树，人在木兰舟。广泽生明月，苍山夹乱流。云中君不见，竟夕自悲秋。"},
    {"title": "迢递三巴路，羁危万里身。", "content": "乱山残雪夜，孤烛异乡人。(异乡人 一作：异乡春)渐与骨肉远，转于僮仆亲。那堪正飘泊，明日岁华新。"},
    {"title": "几行归塞尽，念尔独何之。", "content": "暮雨相呼失，寒塘欲下迟。渚云低暗度，关月冷相随。未必逢矰缴，孤飞自可疑。"},
    {"title": "清晨入古寺，初日照高林。", "content": "曲径通幽处，禅房花木深。(曲 一作：竹)山光悦鸟性，潭影空人心。万籁此都寂，但余钟磬音。(都寂 一作：俱寂；但余 一作：惟余)"},
    {"title": "海上生明月，天涯共此时。", "content": "情人怨遥夜，竟夕起相思。灭烛怜光满，披衣觉露滋。不堪盈手赠，还寝梦佳期。"},
    {"title": "调角断清秋，征人倚戍楼。", "content": "春风对青冢，白日落梁州。大漠无兵阻，穷边有客游。蕃情似此水，长愿向南流。"},
    {"title": "前年戍月支，城下没全师。", "content": "(戍 一作：伐；城下 一作：城上)蕃汉断消息，死生长别离。 无人收废帐，归马识残旗。欲祭疑君在，天涯哭此时。"},
    {"title": "红叶晚萧萧，长亭酒一瓢。", "content": "残云归太华，疏雨过中条。树色随山迥，河声入海遥。(随山 一作：随关)帝乡明日到，犹自梦渔樵。"},
    {"title": "遥夜泛清瑟，西风生翠萝。", "content": "残萤委玉露，早雁拂金河。(委 一作：栖)高树晓还密，远山晴更多。淮南一叶下，自觉洞庭波。(洞庭波 一作：老烟波)"},
    {"title": "荒戍落黄叶，浩然离故关。", "content": "高风汉阳渡，初日郢门山。江上几人在，天涯孤棹还。何当重相见，樽酒慰离颜。"},
    {"title": "移家虽带郭，野径入桑麻。", "content": "近种篱边菊，秋来未著花。扣门无犬吠，欲去问西家。报道山中去，归时每日斜。(归时 一作：归来)"},
    {"title": "一路经行处，莓苔见履痕。", "content": "白云依静渚，春草闭闲门。(静渚 一作：静者)过雨看松色，随山到水源。溪花与禅意，相对亦忘言。"},
    {"title": "乡心新岁切，天畔独潸然。", "content": "老至居人下，春归在客先。岭猿同旦暮，江柳共风烟。已似长沙傅，从今又几年。"},
    {"title": "古台摇落后，秋日望乡心。", "content": "(秋日 一作：秋入)野寺来人少，云峰隔水深。夕阳依旧垒，寒磬满空林。惆怅南朝事，长江独至今。"},
    {"title": "流落征南将，曾驱十万师。", "content": "罢归无旧业，老去恋明时。独立三边静，轻生一剑知。茫茫江汉上，日暮欲何之。"},
    {"title": "望君烟水阔，挥手泪沾巾。", "content": "飞鸟没何处，青山空向人。长江一帆远，落日五湖春。谁见汀洲上，相思愁白蘋。"},
    {"title": "天地英雄气，千秋尚凛然。", "content": "(天地 一作：天下)势分三足鼎，业复五铢钱。 得相能开国，生儿不象贤。凄凉蜀故妓，来舞魏宫前。"},
    {"title": "道由白云尽，春与青溪长。", "content": "时有落花至，远随流水香。闲门向山路，深柳读书堂。幽映每白日，清辉照衣裳。"},
    {"title": "故关衰草遍，离别自堪悲。", "content": "(自堪悲 一作：正堪悲)路出寒云外，人归暮雪时。少孤为客早，多难识君迟。掩泪空相向，风尘何处期。(掩泪 一作：掩泣)"},
    {"title": "上国随缘住，来途若梦行。", "content": "浮天沧海远，去世法舟轻。水月通禅寂，鱼龙听梵声。惟怜一灯影，万里眼中明。"},
    {"title": "泉壑带茅茨，云霞生薜帷。", "content": "竹怜新雨后，山爱夕阳时。闲鹭栖常早，秋花落更迟。家僮扫萝径，昨与故人期。"},
    {"title": "西陆蝉声唱，南冠客思深。", "content": "(客思深 一作：客思侵)那堪玄鬓影，来对白头吟。(那堪 一作：不堪)露重飞难进，风多响易沉。无人信高洁，谁为表予心？"},
    {"title": "天秋月又满，城阙夜千重。", "content": "还作江南会，翻疑梦里逢。风枝惊暗鹊，露草泣寒蛩。(泣 一作：覆)羁旅长堪醉，相留畏晓钟。"},
    {"title": "长簟迎风早，空城澹月华。", "content": "星河秋一雁，砧杵夜千家。 节候看应晚，心期卧亦赊。向来吟秀句，不觉已鸣鸦。"},
    {"title": "谢公最小偏怜女，自嫁黔娄百事乖。", "content": "顾我无衣搜荩箧，泥他沽酒拔金钗。(荩箧 一作：画箧)野蔬充膳甘长藿，落叶添薪仰古槐。今日俸钱过十万，与君营奠复营斋。"},
    {"title": "昔日戏言身后意，今朝都到眼前来。", "content": "(身后意 一作：身后事)衣裳已施行看尽，针线犹存未忍开。尚想旧情怜婢仆，也曾因梦送钱财。诚知此恨人人有，贫贱夫妻百事哀。"},
    {"title": "闲坐悲君亦自悲，百年都是几多时。", "content": "邓攸无子寻知命，潘岳悼亡犹费词。同穴窅冥何所望，他生缘会更难期。惟将终夜长开眼，报答平生未展眉。"},
    {"title": "洞门高阁霭馀辉，桃李阴阴柳絮飞。", "content": "禁里疏钟官舍晚，省中啼鸟吏人稀。晨摇玉佩趋金殿，夕奉天书拜琐闱。强欲从君无那老，将因卧病解朝衣。"},
    {"title": "绛帻鸡人报晓筹，尚衣方进翠云裘。", "content": "(报 一作：送)九天阊阖开宫殿，万国衣冠拜冕旒。日色才临仙掌动，香烟欲傍衮龙浮。朝罢须裁五色诏，佩声归向凤池头。(归向 一作：归到)"},
    {"title": "渭水自萦秦塞曲，黄山旧绕汉宫斜。", "content": "銮舆迥出千门柳，阁道回看上苑花。云里帝城双凤阙，雨中春树万人家。为乘阳气行时令，不是宸游玩物华。(玩 一作：重)"},
    {"title": "积雨空林烟火迟，蒸藜炊黍饷东菑。", "content": "漠漠水田飞白鹭，阴阴夏木啭黄鹂。山中习静观朝槿，松下清斋折露葵。野老与人争席罢，海鸥何事更相疑。"},
    {"title": "自河南经乱，关内阻饥，兄弟离散，各在一处。", "content": "因望月有感，聊书所怀，寄上浮梁大兄、於潜七兄、乌江十五兄，兼示符离及下邽弟妹。时难年荒世业空，弟兄羁旅各西东。田园寥落干戈后，骨肉流离道路"},
    {"title": "鸡鸣紫陌曙光寒，莺啭皇州春色阑。", "content": "金阙晓钟开万户，玉阶仙仗拥千官。花迎剑佩星初落，柳拂旌旗露未干。独有凤凰池上客，阳春一曲和皆难。"},
    {"title": "凤凰台上凤凰游，凤去台空江自流。", "content": "吴宫花草埋幽径，晋代衣冠成古丘。三山半落青天外，二水中分白鹭洲。(二水 一作：一水)总为浮云能蔽日，长安不见使人愁。"},
    {"title": "重帏深下莫愁堂，卧后清宵细细长。", "content": "神女生涯原是梦，小姑居处本无郎。风波不信菱枝弱，月露谁教桂叶香。直道相思了无益，未妨惆怅是清狂。"},
    {"title": "凤尾香罗薄几重，碧文圆顶夜深缝。", "content": "扇裁月魄羞难掩，车走雷声语未通。曾是寂寥金烬暗，断无消息石榴红。斑骓只系垂杨岸，何处西南任好风。(任 一作：待)"},
    {"title": "相见时难别亦难，东风无力百花残。", "content": "春蚕到死丝方尽，蜡炬成灰泪始干。晓镜但愁云鬓改，夜吟应觉月光寒。蓬山此去无多路，青鸟殷勤为探看。(蓬山 一作：蓬莱)"},
    {"title": "来是空言去绝踪，月斜楼上五更钟。", "content": "梦为远别啼难唤，书被催成墨未浓。蜡照半笼金翡翠，麝熏微度绣芙蓉。刘郎已恨蓬山远，更隔蓬山一万重！"},
    {"title": "飒飒东风细雨来，芙蓉塘外有轻雷。", "content": "金蟾啮锁烧香入，玉虎牵丝汲井回。贾氏窥帘韩掾少，宓妃留枕魏王才。春心莫共花争发，一寸相思一寸灰！"},
    {"title": "昨夜星辰昨夜风，画楼西畔桂堂东。", "content": "身无彩凤双飞翼，心有灵犀一点通。隔座送钩春酒暖，分曹射覆蜡灯红。嗟余听鼓应官去，走马兰台类转蓬。"},
    {"title": "怅卧新春白袷衣，白门寥落意多违。", "content": "红楼隔雨相望冷，珠箔飘灯独自归。远路应悲春晼晚，残宵犹得梦依稀。玉珰缄札何由达，万里云罗一雁飞。"},
    {"title": "鱼鸟犹疑畏简书，风云常为护储胥。", "content": "(鱼鸟 一作：猿鸟)徒令上将挥神笔，终见降王走传车。管乐有才真不忝，关张无命欲何如？他年锦里经祠庙，梁父吟成恨有余。"},
    {"title": "锦瑟无端五十弦，一弦一柱思华年。", "content": "庄生晓梦迷蝴蝶，望帝春心托杜鹃。沧海月明珠有泪，蓝田日暖玉生烟。此情可待成追忆，只是当时已惘然。"},
    {"title": "紫泉宫殿锁烟霞，欲取芜城作帝家。", "content": "玉玺不缘归日角，锦帆应是到天涯。于今腐草无萤火，终古垂杨有暮鸦。地下若逢陈后主，岂宜重问后庭花。"},
    {"title": "朝闻游子唱离歌，昨夜微霜初渡河。", "content": "鸿雁不堪愁里听，云山况是客中过。关城树色催寒近，御苑砧声向晚多。(树 一作：曙)莫见长安行乐处，空令岁月易蹉跎。(莫见 一作：莫是)"},
    {"title": "支离东北风尘际，漂泊西南天地间。", "content": "三峡楼台淹日月，五溪衣服共云山。羯胡事主终无赖，词客哀时且未还。庾信平生最萧瑟，暮年诗赋动江关。"},
    {"title": "摇落深知宋玉悲，风流儒雅亦吾师。", "content": "怅望千秋一洒泪，萧条异代不同时。江山故宅空文藻，云雨荒台岂梦思。最是楚宫俱泯灭，舟人指点到今疑。"},
    {"title": "群山万壑赴荆门，生长明妃尚有村。", "content": "一去紫台连朔漠，独留青冢向黄昏。画图省识春风面，环珮空归夜月魂。(夜月 一作：月夜)千载琵琶作胡语，分明怨恨曲中论。"},
    {"title": "蜀主窥吴幸三峡，崩年亦在永安宫。", "content": "(窥 一作：征)翠华想像空山里，玉殿虚无野寺中。古庙杉松巢水鹤，岁时伏腊走村翁。武侯祠屋常邻近，一体君臣祭祀同。"},
    {"title": "诸葛大名垂宇宙，宗臣遗像肃清高。", "content": "三分割据纡筹策，万古云霄一羽毛。伯仲之间见伊吕，指挥若定失萧曹。运移汉祚终难复，志决身歼军务劳。"},
    {"title": "清秋幕府井梧寒，独宿江城蜡炬残。", "content": "永夜角声悲自语，中天月色好谁看。风尘荏苒音书绝，关塞萧条行路难。已忍伶俜十年事，强移栖息一枝安。"},
    {"title": "岁暮阴阳催短景，天涯霜雪霁寒宵。", "content": "五更鼓角声悲壮，三峡星河影动摇。野哭千家闻战伐，夷歌数处起渔樵。(千家 一作：几家)卧龙跃马终黄土，人事音书漫寂寥。(音书 一作：依依)"},
    {"title": "剑外忽传收蓟北，初闻涕泪满衣裳。", "content": "却看妻子愁何在，漫卷诗书喜欲狂。白日放歌须纵酒，青春作伴好还乡。即从巴峡穿巫峡，便下襄阳向洛阳。"},
    {"title": "风急天高猿啸哀，渚清沙白鸟飞回。", "content": "无边落木萧萧下，不尽长江滚滚来。万里悲秋常作客，百年多病独登台。艰难苦恨繁霜鬓，潦倒新停浊酒杯。"},
    {"title": "花近高楼伤客心，万方多难此登临。", "content": "锦江春色来天地，玉垒浮云变古今。北极朝廷终不改，西山寇盗莫相侵。可怜后主还祠庙，日暮聊为《梁甫吟》。(梁甫 一作：梁父)"},
    {"title": "丞相祠堂何处寻？锦官城外柏森森。", "content": "映阶碧草自春色，隔叶黄鹂空好音。三顾频烦天下计，两朝开济老臣心。出师未捷身先死，长使英雄泪满襟。"},
    {"title": "舍南舍北皆春水，但见群鸥日日来。", "content": "花径不曾缘客扫，蓬门今始为君开。盘飧市远无兼味，樽酒家贫只旧醅。肯与邻翁相对饮，隔篱呼取尽余杯。"},
    {"title": "西山白雪三城戍，南浦清江万里桥。", "content": "海内风尘诸弟隔，天涯涕泪一身遥。惟将迟暮供多病，未有涓埃答圣朝。(惟 通：唯)跨马出郊时极目，不堪人事日萧条。"},
    {"title": "城上高楼接大荒，海天愁思正茫茫。", "content": "惊风乱飐芙蓉水，密雨斜侵薜荔墙。岭树重遮千里目，江流曲似九回肠。共来百越文身地，犹自音书滞一乡。"},
    {"title": "莺啼燕语报新年，马邑龙堆路几千。", "content": "家住层城临汉苑，心随明月到胡天。(层城 一作：秦城)机中锦字论长恨，楼上花枝笑独眠。为问元戎窦车骑，何时返旆勒燕然。"},
    {"title": "去年花里逢君别，今日花开又一年。", "content": "(又一年 一作：已一年)世事茫茫难自料，春愁黯黯独成眠。身多疾病思田里，邑有流亡愧俸钱。闻道欲来相问讯，西楼望月几回圆。"},
    {"title": "燕台一望客心惊，笳鼓喧喧汉将营。", "content": "(一望 一作：一去；笳鼓 一作：箫鼓)万里寒光生积雪，三边曙色动危旌。沙场烽火连胡月，海畔云山拥蓟城。(连胡月 一作：侵胡月)少小虽非投笔吏，论功还"},
    {"title": "蓬门未识绮罗香，拟托良媒益自伤。", "content": "谁爱风流高格调，共怜时世俭梳妆。敢将十指夸针巧，不把双眉斗画长。苦恨年年压金线，为他人作嫁衣裳。"},
    {"title": "嗟君此别意何如，驻马衔杯问谪居。", "content": "巫峡啼猿数行泪，衡阳归雁几封书。青枫江上秋帆远，白帝城边古木疏。圣代即今多雨露，暂时分手莫踌躇。"},
    {"title": "汉文皇帝有高台，此日登临曙色开。", "content": "三晋云山皆北向，二陵风雨自东来。关门令尹谁能识，河上仙翁去不回。且欲近寻彭泽宰，陶然共醉菊花杯。"},
    {"title": "昔人已乘黄鹤去，此地空余黄鹤楼。", "content": "黄鹤一去不复返，白云千载空悠悠。晴川历历汉阳树，芳草萋萋鹦鹉洲。日暮乡关何处是？烟波江上使人愁。"},
    {"title": "岧峣太华俯咸京，天外三峰削不成。", "content": "武帝祠前云欲散，仙人掌上雨初晴。河山北枕秦关险，驿路西连汉畤平。借问路旁名利客，何如此处学长生。(何 一作：无)"},
    {"title": "澹然空水带斜晖，曲岛苍茫接翠微。", "content": "(带 一作：对)波上马嘶看棹去，柳边人歇待船归。数丛沙草群鸥散，万顷江田一鹭飞。谁解乘舟寻范蠡，五湖烟水独忘机。"},
    {"title": "苏武魂销汉使前，古祠高树两茫然。", "content": "云边雁断胡天月，陇上羊归塞草烟。回日楼台非甲帐，去时冠剑是丁年。茂陵不见封侯印，空向秋波哭逝川。"},
    {"title": "生涯岂料承优诏，世事空知学醉歌。", "content": "江上月明胡雁过，淮南木落楚山多。寄身且喜沧洲近，顾影无如白发何。今日龙钟人共弃，愧君犹遣慎风波。(弃 一作：老)"},
    {"title": "三年谪宦此栖迟，万古惟留楚客悲。", "content": "秋草独寻人去后，寒林空见日斜时。汉文有道恩犹薄，湘水无情吊岂知？寂寂江山摇落处，怜君何事到天涯！"},
    {"title": "汀洲无浪复无烟，楚客相思益渺然。", "content": "汉口夕阳斜渡鸟，洞庭秋水远连天。孤城背岭寒吹角，独树临江夜泊船。(独树 一作：独戍)贾谊上书忧汉室，长沙谪去古今怜。"},
    {"title": "王濬楼船下益州，金陵王气黯然收。", "content": "(王濬 一作：西晋)千寻铁锁沉江底，一片降幡出石头。人世几回伤往事，山形依旧枕寒流。今逢四海为家日，故垒萧萧芦荻秋。"},
    {"title": "云开远见汉阳城，犹是孤帆一日程。", "content": "估客昼眠知浪静，舟人夜语觉潮生。三湘衰鬓逢秋色，万里归心对月明。旧业已随征战尽，更堪江上鼓鼙声。"},
    {"title": "二月黄莺飞上林，春城紫禁晓阴阴。", "content": "(黄莺 一作：黄鹂)长乐钟声花外尽，龙池柳色雨中深。阳和不散穷途恨，霄汉长怀捧日心。(长怀 一作：长悬)献赋十年犹未遇，羞将白发对华簪。"},
    {"title": "十二楼中尽晓妆，望仙楼上望君王。", "content": "锁衔金兽连环冷，水滴铜龙昼漏长。云髻罢梳还对镜，罗衣欲换更添香。遥窥正殿帘开处，袍袴宫人扫御床。"},
    {"title": "仙台初见五城楼，风物凄凄宿雨收。", "content": "(初见 一作：下见)山色遥连秦树晚，砧声近报汉宫秋。疏松影落空坛静，细草香闲小洞幽。(闲 一作：生)何用别寻方外去，人间亦自有丹丘。"},
    {"title": "癸卯岁，西原贼入道县，焚烧杀掠，几尽而去。", "content": "明年，贼又攻永破邵，不犯此州边鄙而退。岂力能制敌与？盖蒙其伤怜而已。诸使何为忍苦征敛，故作诗一篇以示官吏。昔岁逢太平，山林二十年。泉源在庭"},
    {"title": "高卧南斋时，开帷月初吐。", "content": "清辉澹水木，演漾在窗户。冉冉几盈虚，澄澄变今古。(冉冉 一作：荏苒)美人清江畔，是夜越吟苦。千里共如何，微风吹兰杜。(共 一作：其)"},
    {"title": "斜阳照墟落，穷巷牛羊归。", "content": "(斜阳 一作：斜光)野老念牧童，倚杖候荆扉。雉雊麦苗秀，蚕眠桑叶稀。田夫荷锄至，相见语依依。(至 一作：立)即此羡闲逸，怅然吟式微。"},
    {"title": "艳色天下重，西施宁久微。", "content": "朝为越溪女，暮作吴宫妃。贱日岂殊众，贵来方悟稀。邀人傅脂粉，不自著罗衣。君宠益娇态，君怜无是非。当时浣纱伴，莫得同车归。持谢邻家子，效颦安可希。"},
    {"title": "下马饮君酒，问君何所之？君言不得意，归卧南山陲。", "content": "但去莫复问，白云无尽时。"},
    {"title": "圣代无隐者，英灵尽来归。", "content": "遂令东山客，不得顾采薇。既至金门远，孰云吾道非。(金门 一作：君门)江淮度寒食，京洛缝春衣。置酒长安道，同心与我违。(长安道 一作：临长道)行当浮桂棹，未几"},
    {"title": "言入黄花川，每逐青溪水。", "content": "随山将万转，趣途无百里。声喧乱石中，色静深松里。漾漾泛菱荇，澄澄映葭苇。我心素已闲，清川澹如此。请留磐石上，垂钓将已矣。(磐石 一作：盘石)"},
    {"title": "塔势如涌出，孤高耸天宫。", "content": "登临出世界，磴道盘虚空。突兀压神州，峥嵘如鬼工。四角碍白日，七层摩苍穹。下窥指高鸟，俯听闻惊风。连山若波涛，奔凑似朝东。(凑 一作：走；似 一作：如)青槐夹"},
    {"title": "暮从碧山下，山月随人归。", "content": "却顾所来径，苍苍横翠微。相携及田家，童稚开荆扉。绿竹入幽径，青萝拂行衣。欢言得所憩，美酒聊共挥。长歌吟松风，曲尽河星稀。我醉君复乐，陶然共忘机。"},
    {"title": "花间一壶酒，独酌无相亲。", "content": "举杯邀明月，对影成三人。月既不解饮，影徒随我身。暂伴月将影，行乐须及春。我歌月徘徊，我舞影零乱。醒时同交欢，醉后各分散。(同交欢 一作：相交欢)永结无情游，"},
    {"title": "燕草如碧丝，秦桑低绿枝。", "content": "当君怀归日，是妾断肠时。 春风不相识，何事入罗帏。"},
    {"title": "死别已吞声，生别常恻恻。", "content": "江南瘴疠地，逐客无消息。故人入我梦，明我长相忆。恐非平生魂，路远不可测。魂来枫林青，魂返关塞黑。君今在罗网，何以有羽翼？落月满屋梁，犹疑照颜色。水深波浪阔，"},
    {"title": "浮云终日行，游子久不至。", "content": "三夜频梦君，情亲见君意。告归常局促，苦道来不易。江湖多风波，舟楫恐失坠。出门搔白首，若负平生志。冠盖满京华，斯人独憔悴。孰云网恢恢，将老身反累。千秋万岁名，"},
    {"title": "岱宗夫如何？齐鲁青未了。", "content": "造化钟神秀，阴阳割昏晓。荡胸生曾云，决眦入归鸟。( 曾 同：层)会当凌绝顶，一览众山小。"},
    {"title": "人生不相见，动如参与商。", "content": "今夕复何夕，共此灯烛光。少壮能几时，鬓发各已苍。访旧半为鬼，惊呼热中肠。焉知二十载，重上君子堂。昔别君未婚，儿女忽成行。怡然敬父执，问我来何方。问答乃未已，"},
    {"title": "绝代有佳人，幽居在空谷。", "content": "自云良家子，零落依草木。关中昔丧乱，兄弟遭杀戮。官高何足论，不得收骨肉。世情恶衰歇，万事随转烛。夫婿轻薄儿，新人美如玉。合昏尚知时，鸳鸯不独宿。但见新人笑，"},
    {"title": "北山白云里，隐者自怡悦。", "content": "相望试登高，心随雁飞灭。(试 一作 始)愁因薄暮起，兴是清秋发。时见归村人，沙行渡头歇。(沙行 一作：沙平)天边树若荠，江畔洲如月。(洲 一作：舟)何当载酒"},
    {"title": "山光忽西落，池月渐东上。", "content": "散发乘夕凉，开轩卧闲敞。荷风送香气，竹露滴清响。欲取鸣琴弹，恨无知音赏。感此怀故人，中宵劳梦想。(中 一作：终)"},
    {"title": "夕阳度西岭，群壑倏已暝。", "content": "松月生夜凉，风泉满清听。樵人归欲尽，烟鸟栖初定。之子期宿来，孤琴候萝径。"},
    {"title": "绝顶一茅茨，直上三十里。", "content": "扣关无僮仆，窥室唯案几。若非巾柴车，应是钓秋水。差池不相见，黾勉空仰止。草色新雨中，松声晚窗里。及兹契幽绝，自足荡心耳。虽无宾主意，颇得清净理。兴尽方下山，"},
    {"title": "汲井漱寒齿，清心拂尘服。", "content": "闲持贝叶书，步出东斋读。真源了无取，妄迹世所逐。遗言冀可冥，缮性何由熟。道人庭宇静，苔色连深竹。日出雾露馀，青松如膏沐。澹然离言说，悟悦心自足。"},
    {"title": "久为簪组累，幸此南夷谪。", "content": "(累 一作：束)闲依农圃邻，偶似山林客。 晓耕翻露草，夜榜响溪石。来往不逢人，长歌楚天碧。"},
    {"title": "永日方戚戚，出行复悠悠。", "content": "女子今有行，大江溯轻舟。尔辈苦无恃，抚念益慈柔。幼为长所育，两别泣不休。对此结中肠，义往难复留。自小阙内训，事姑贻我忧。赖兹托令门，任恤庶无尤。贫俭诚所尚，"},
    {"title": "客从东方来，衣上灞陵雨。", "content": "问客何为来，采山因买斧。冥冥花正开，飏飏燕新乳。昨别今已春，鬓丝生几缕。"},
    {"title": "落帆逗淮镇，停舫临孤驿。", "content": "浩浩风起波，冥冥日沉夕。人归山郭暗，雁下芦洲白。独夜忆秦关，听钟未眠客。"},
    {"title": "吏舍跼终年，出郊旷清曙。", "content": "杨柳散和风，青山澹吾虑。依丛适自憩，缘涧还复去。微雨霭芳原，春鸠鸣何处。乐幽心屡止，遵事迹犹遽。终罢斯结庐，慕陶直可庶。"},
    {"title": "兵卫森画戟，宴寝凝清香。", "content": "海上风雨至，逍遥池阁凉。烦疴近消散，嘉宾复满堂。自惭居处崇，未睹斯民康。理会是非遣，性达形迹忘。鲜肥属时禁，蔬果幸见尝。俯饮一杯酒，仰聆金玉章。神欢体自轻，"},
    {"title": "凄凄去亲爱，泛泛入烟雾。", "content": "归棹洛阳人，残钟广陵树。今朝此为别，何处还相遇。世事波上舟，沿洄安得住。"},
    {"title": "今朝郡斋冷，忽念山中客。", "content": "涧底束荆薪，归来煮白石。欲持一瓢酒，远慰风雨夕。落叶满空山，何处寻行迹。"},
    {"title": "清溪深不测，隐处唯孤云。", "content": "松际露微月，清光犹为君。茅亭宿花影，药院滋苔纹。余亦谢时去，西山鸾鹤群。"},
    {"title": "孤鸿海上来，池潢不敢顾。", "content": "侧见双翠鸟，巢在三珠树。矫矫珍木巅，得无金丸惧？美服患人指，高明逼神恶。今我游冥冥，弋者何所慕！"},
    {"title": "兰叶春葳蕤，桂华秋皎洁。", "content": "欣欣此生意，自尔为佳节。谁知林栖者，闻风坐相悦。草木有本心，何求美人折！"},
    {"title": "幽人归独卧，滞虑洗孤清。", "content": "持此谢高鸟，因之传远情。日夕怀空意，人谁感至精？飞沉理自隔，何所慰吾诚？"},
    {"title": "江南有丹橘，经冬犹绿林。", "content": "岂伊地气暖？自有岁寒心。可以荐嘉客，奈何阻重深。运命惟所遇，循环不可寻。徒言树桃李，此木岂无阴？"},
    {"title": "幽意无断绝，此去随所偶。", "content": "晚风吹行舟，花路入溪口。际夜转西壑，隔山望南斗。潭烟飞溶溶，林月低向后。生事且弥漫，愿为持竿叟。"},
    {"title": "漫叟以公田米酿酒，因休暇，则载酒于湖上，时取一醉。", "content": "欢醉中，据湖岸，引臂向鱼取酒，使舫载之，遍饮坐者。意疑倚巴丘酌于君山之上，诸子环洞庭而坐，酒舫泛泛然触波涛。而往来者，乃作歌以长之"},
    {"title": "汉皇重色思倾国，御宇多年求不得。", "content": "杨家有女初长成，养在深闺人未识。天生丽质难自弃，一朝选在君王侧。回眸一笑百媚生，六宫粉黛无颜色。春寒赐浴华清池，温泉水滑洗凝脂。侍儿扶起娇无力，始是"},
    {"title": "元和十年，予左迁九江郡司马。", "content": "明年秋，送客湓浦口，闻舟中夜弹琵琶者，听其音，铮铮然有京都声。问其人，本长安倡女，尝学琵琶于穆、曹二善才，年长色衰，委身为贾人妇。遂命酒，使快弹数曲。曲"},
    {"title": "君不见走马川行雪海边，平沙莽莽黄入天。", "content": " 轮台九月风夜吼，一川碎石大如斗，随风满地石乱走。 匈奴草黄马正肥，金山西见烟尘飞，汉家大将西出师。 将军金甲夜不脱，半夜军行戈相拨，风头如刀"},
    {"title": "轮台城头夜吹角，轮台城北旄头落。", "content": "羽书昨夜过渠黎，单于已在金山西。戍楼西望烟尘黑，汉军屯在轮台北。上将拥旄西出征，平明吹笛大军行。四边伐鼓雪海涌，三军大呼阴山动。虏塞兵气连云屯，战场"},
    {"title": "北风卷地白草折，胡天八月即飞雪。", "content": "忽如一夜春风来，千树万树梨花开。散入珠帘湿罗幕，狐裘不暖锦衾薄。将军角弓不得控，都护铁衣冷难着。(难着 一作：犹著)瀚海阑干百丈冰，愁云惨淡万里凝。"},
    {"title": "弃我去者，昨日之日不可留；乱我心者，今日之日多烦忧。", "content": "长风万里送秋雁，对此可以酣高楼。蓬莱文章建安骨，中间小谢又清发。俱怀逸兴壮思飞，欲上青天揽明月。(揽 一作：览；明月 一作：日月"},
    {"title": "我本楚狂人，凤歌笑孔丘。", "content": "手持绿玉杖，朝别黄鹤楼。五岳寻仙不辞远，一生好入名山游。庐山秀出南斗傍，屏风九叠云锦张，影落明湖青黛光。金阙前开二峰长，银河倒挂三石梁，香炉瀑布遥相望，回崖"},
    {"title": "海客谈瀛洲，烟涛微茫信难求；越人语天姥，云霞明灭或可睹。", "content": "天姥连天向天横，势拔五岳掩赤城。天台四万八千丈，对此欲倒东南倾。(四万 一作：一万)我欲因之梦吴越，一夜飞度镜湖月。湖月照我"},
    {"title": "风吹柳花满店香，吴姬压酒劝客尝。", "content": "(劝客 一作：唤客)金陵子弟来相送，欲行不行各尽觞。请君试问东流水，别意与之谁短长？"},
    {"title": "元和天子神武姿，彼何人哉轩与羲。", "content": "誓将上雪列圣耻，坐法宫中朝四夷。淮西有贼五十载，封狼生貙貙生罴。不据山河据平地，长戈利矛日可麾。帝得圣相相曰度，贼斫不死神扶持。腰悬相印作都统，阴风"},
    {"title": "蔡女昔造胡笳声，一弹一十有八拍。", "content": "胡人落泪沾边草，汉使断肠对归客。古戍苍苍烽火寒，大荒沉沉飞雪白。(沉沉 一作：阴沉)先拂商弦后角羽，四郊秋叶惊摵摵。董夫子，通神明，深山窃听来妖精。"},
    {"title": "南山截竹为觱篥，此乐本自龟兹出。", "content": "流传汉地曲转奇，凉州胡人为我吹。傍邻闻者多叹息，远客思乡皆泪垂。世人解听不解赏，长飙风中自来往。枯桑老柏寒飕飗，九雏鸣凤乱啾啾。龙吟虎啸一时发，万籁"},
    {"title": "男儿事长征，少小幽燕客。", "content": "赌胜马蹄下，由来轻七尺。杀人莫敢前，须如猬毛磔。黄云陇底白云飞，未得报恩不得归。辽东小妇年十五，惯弹琵琶解歌舞。今为羌笛出塞声，使我三军泪如雨。"},
    {"title": "四月南风大麦黄，枣花未落桐阴长。", "content": "(阴 一作：叶)青山朝别暮还见，嘶马出门思旧乡。陈侯立身何坦荡，虬须虎眉仍大颡。腹中贮书一万卷，不肯低头在草莽。东门酤酒饮我曹，心轻万事如鸿毛。醉卧"},
    {"title": "主人有酒欢今夕，请奏鸣琴广陵客。", "content": "月照城头乌半飞，霜凄万树风入衣。(万树 一作：万木)铜炉华烛烛增辉，初弹渌水后楚妃。一声已动物皆静，四座无言星欲稀。清淮奉使千余里，敢告云山从此始。"},
    {"title": "孔明庙前有老柏，柯如青铜根如石。", "content": "霜皮溜雨四十围，黛色参天二千尺。君臣已与时际会，树木犹为人爱惜。云来气接巫峡长，月出寒通雪山白。忆昨路绕锦亭东，先主武侯同閟宫。崔嵬枝干郊原古，窈窕"},
    {"title": "大历二年十月十九日，夔府别驾元持宅，见临颍李十二娘舞剑器，壮其蔚跂，问其所师，曰：“余公孙大娘弟子也。", "content": "” 开元五载，余尚童稚，记于郾城观公孙氏，舞剑器浑脱，浏漓顿挫，独出冠时，自高"},
    {"title": "国初已来画鞍马，神妙独数江都王。", "content": "将军得名三十载，人间又见真乘黄。曾貌先帝照夜白，龙池十日飞霹雳。内府殷红玛瑙盘，婕妤传诏才人索。盘赐将军拜舞归，轻纨细绮相追飞。贵戚权门得笔迹，始觉"},
    {"title": "将军魏武之子孙，于今为庶为清门。", "content": "英雄割据虽已矣，文采风流今尚存。学书初学卫夫人，但恨无过王右军。丹青不知老将至，富贵于我如浮云。开元之中常引见，承恩数上南薰殿。凌烟功臣少颜色，将军"},
    {"title": "今我不乐思岳阳，身欲奋飞病在床。", "content": "美人娟娟隔秋水，濯足洞庭望八荒。鸿飞冥冥日月白，青枫叶赤天雨霜。玉京群帝集北斗，或骑麒麟翳凤凰。芙蓉旌旗烟雾落，影动倒景摇潇湘。星宫之君醉琼浆，羽人"},
    {"title": "山寺钟鸣昼已昏，渔梁渡头争渡喧。", "content": "人随沙岸向江村，余亦乘舟归鹿门。鹿门月照开烟树，忽到庞公栖隐处。岩扉松径长寂寥，惟有幽人自来去。"},
    {"title": "渔翁夜傍西岩宿，晓汲清湘燃楚竹。", "content": "烟销日出不见人，欸乃一声山水绿。回看天际下中流，岩上无心云相逐。"},
    {"title": "前不见古人，后不见来者。", "content": "念天地之悠悠，独怆然而涕下！"},
    {"title": "张生手持石鼓文，劝我试作石鼓歌。", "content": "少陵无人谪仙死，才薄将奈石鼓何。周纲凌迟四海沸，宣王愤起挥天戈。大开明堂受朝贺，诸侯剑佩鸣相磨。蒐于岐阳骋雄俊，万里禽兽皆遮罗。镌功勒成告万世，凿石"},
    {"title": "山石荦确行径微，黄昏到寺蝙蝠飞。", "content": "升堂坐阶新雨足，芭蕉叶大栀子肥。僧言古壁佛画好，以火来照所见稀。铺床拂席置羹饭，疏粝亦足饱我饥。夜深静卧百虫绝，清月出岭光入扉。天明独去无道路，出入"},
    {"title": "纤云四卷天无河，清风吹空月舒波。", "content": "沙平水息声影绝，一杯相属君当歌。君歌声酸辞且苦，不能听终泪如雨。洞庭连天九疑高，蛟龙出没猩鼯号。十生九死到官所，幽居默默如藏逃。下床畏蛇食畏药，海气"},
    {"title": "五岳祭秩皆三公，四方环镇嵩当中。", "content": "火维地荒足妖怪，天假神柄专其雄。喷云泄雾藏半腹，虽有绝顶谁能穷？我来正逢秋雨节，阴气晦昧无清风。潜心默祷若有应，岂非正直能感通！须臾静扫众峰出，仰见"},
    {"title": "黄河远上白云间，一片孤城万仞山。", "content": "羌笛何须怨杨柳，春风不度玉门关。"},
    {"title": "秦时明月汉时关，万里长征人未还。", "content": "但使龙城飞将在，不教胡马度阴山。"},
    {"title": "蝉鸣空桑林，八月萧关道。", "content": "出塞入塞寒，处处黄芦草。从来幽并客，皆共尘沙老。(尘沙 一作：沙尘)莫学游侠儿，矜夸紫骝好。"},
    {"title": "饮马渡秋水，水寒风似刀。", "content": "平沙日未没，黯黯见临洮。昔日长城战，咸言意气高。黄尘足今古，白骨乱蓬蒿。"},
    {"title": "奉帚平明金殿开，且将团扇共徘徊。", "content": "(且 一作：暂)玉颜不及寒鸦色，犹带昭阳日影来。"},
    {"title": "渭城朝雨浥轻尘，客舍青青柳色新。", "content": "劝君更尽一杯酒，西出阳关无故人。"},
    {"title": "桂魄初生秋露微，轻罗已薄未更衣。", "content": "银筝夜久殷勤弄，心怯空房不忍归。"},
    {"title": "洛阳女儿对门居，才可颜容十五余。", "content": "良人玉勒乘骢马，侍女金盘脍鲤鱼。画阁朱楼尽相望，红桃绿柳垂檐向。罗帷送上七香车，宝扇迎归九华帐。狂夫富贵在青春，意气骄奢剧季伦。自怜碧玉亲教舞，不惜"},
    {"title": "少年十五二十时，步行夺得胡马骑。", "content": "(夺得 一作：夺取)射杀山中白额虎，肯数邺下黄须儿！一身转战三千里，一剑曾当百万师。汉兵奋迅如霹雳，虏骑崩腾畏蒺藜。卫青不败由天幸，李广无功缘数奇。"},
    {"title": "渔舟逐水爱山春，两岸桃花夹古津。", "content": "坐看红树不知远，行尽青溪不见人。(不见 一作：忽值)山口潜行始隈隩，山开旷望旋平陆。遥看一处攒云树，近入千家散花竹。樵客初传汉姓名，居人未改秦衣服。"},
    {"title": "云想衣裳花想容，春风拂槛露华浓。", "content": " 若非群玉山头见，会向瑶台月下逢。"},
    {"title": "一枝秾艳露凝香，云雨巫山枉断肠。", "content": "(秾艳 一作：红艳)借问汉宫谁得似，可怜飞燕倚新妆。"},
    {"title": "名花倾国两相欢，长得君王带笑看。", "content": "(长得 一作：常得)解释春风无限恨，沉香亭北倚阑干。"},
    {"title": "金樽清酒斗十千，玉盘珍羞直万钱。", "content": "(羞 同：馐；直 同：值)停杯投箸不能食，拔剑四顾心茫然。欲渡黄河冰塞川，将登太行雪满山。(雪满山 一作：雪暗天)闲来垂钓碧溪上，忽复乘舟梦日边。("},
    {"title": "大道如青天，我独不得出。", "content": "羞逐长安社中儿，赤鸡白雉赌梨栗。弹剑作歌奏苦声，曳裾王门不称情。淮阴市井笑韩信，汉朝公卿忌贾生。君不见昔时燕家重郭隗，拥篲折节无嫌猜。剧辛乐毅感恩分，输肝剖"},
    {"title": "有耳莫洗颍川水，有口莫食首阳蕨。", "content": "含光混世贵无名，何用孤高比云月？吾观自古贤达人，功成不退皆殒身。子胥既弃吴江上，屈原终投湘水滨。陆机雄才岂自保？李斯税驾苦不早。华亭鹤唳讵可闻？上蔡"},
    {"title": "君不见黄河之水天上来，奔流到海不复回。", "content": "君不见高堂明镜悲白发，朝如青丝暮成雪。人生得意须尽欢，莫使金樽空对月。天生我材必有用，千金散尽还复来。烹羊宰牛且为乐，会须一饮三百杯。岑夫子，"},
    {"title": "玉阶生白露，夜久侵罗袜。", "content": "却下水晶帘，玲珑望秋月。(水晶 一作：水精)"},
    {"title": "长相思，在长安。", "content": "络纬秋啼金井阑，微霜凄凄簟色寒。孤灯不明思欲绝，卷帷望月空长叹。美人如花隔云端。上有青冥之长天，下有渌水之波澜。(长天 一作：高天)天长路远魂飞苦，梦魂不到关山难。"},
    {"title": "花含烟，月明如素愁不眠。", "content": "(如素 一作：欲素)赵瑟初停凤凰柱，蜀琴欲奏鸳鸯弦。此曲有意无人传，愿随春风寄燕然。忆君迢迢隔青天。昔时横波目，今作流泪泉。不信妾肠断，归来看取明镜"},
    {"title": "妾发初覆额，折花门前剧。", "content": "郎骑竹马来，绕床弄青梅。同居长干里，两小无嫌猜。十四为君妇，羞颜未尝开。低头向暗壁，千唤不一回。十五始展眉，愿同尘与灰。常存抱柱信，岂上望夫台。十六君远行，"},
    {"title": "噫吁嚱，危乎高哉！蜀道之难，难于上青天！蚕丛及鱼凫，开国何茫然！尔来四万八千岁，不与秦塞通人烟。", "content": "西当太白有鸟道，可以横绝峨眉巅。地崩山摧壮士死，然后天梯石栈相钩连。上有六龙回日之高"},
    {"title": "秦地罗敷女，采桑绿水边。", "content": "素手青条上，红妆白日鲜。蚕饥妾欲去，五马莫留连。"},
    {"title": "镜湖三百里，菡萏发荷花。", "content": "五月西施采，人看隘若耶。回舟不待月，归去越王家。"},
    {"title": "长安一片月，万户捣衣声。", "content": "秋风吹不尽，总是玉关情。何日平胡虏，良人罢远征。"},
    {"title": "明朝驿使发，一夜絮征袍。", "content": "素手抽针冷，那堪把剪刀。裁缝寄远道，几日到临洮。"},
    {"title": "明月出天山，苍茫云海间。", "content": "长风几万里，吹度玉门关。汉下白登道，胡窥青海湾。由来征战地，不见有人还。戍客望边邑，思归多苦颜。(望边邑 一作：望边色)高楼当此夜，叹息未应闲。"},
    {"title": "嫁得瞿塘贾，朝朝误妾期。", "content": "早知潮有信，嫁与弄潮儿。"},
    {"title": "白日登山望烽火，黄昏饮马傍交河。", "content": "行人刁斗风沙暗，公主琵琶幽怨多。野云万里无城郭，雨雪纷纷连大漠。胡雁哀鸣夜夜飞，胡儿眼泪双双落。闻道玉门犹被遮，应将性命逐轻车。年年战骨埋荒外，空见"},
    {"title": "长安城头头白乌，夜飞延秋门上呼。", "content": "又向人家啄大屋，屋底达官走避胡。金鞭断折九马死，骨肉不得同驰驱。腰下宝玦青珊瑚，可怜王孙泣路隅。问之不肯道姓名，但道困苦乞为奴。已经百日窜荆棘，身上"},
    {"title": "车辚辚，马萧萧，行人弓箭各在腰。", "content": "耶娘妻子走相送，尘埃不见咸阳桥。(耶娘 一作：爷娘)牵衣顿足拦道哭，哭声直上干云霄。道旁过者问行人，行人但云点行频。或从十五北防河，便至四十西营田。"},
    {"title": "三月三日天气新，长安水边多丽人。", "content": "态浓意远淑且真，肌理细腻骨肉匀。绣罗衣裳照暮春，蹙金孔雀银麒麟。头上何所有？翠微匎叶垂鬓唇。背后何所见？珠压腰衱稳称身。就中云幕椒房亲，赐名大国虢与"},
    {"title": "少陵野老吞声哭，春日潜行曲江曲。", "content": "江头宫殿锁千门，细柳新蒲为谁绿？忆昔霓旌下南苑，苑中万物生颜色。昭阳殿里第一人，同辇随君侍君侧。辇前才人带弓箭，白马嚼啮黄金勒。翻身向天仰射云，一笑"},
    {"title": "劝君莫惜金缕衣，劝君惜取少年时。", "content": "(惜取 一作：须惜)花开堪折直须折，莫待无花空折枝。(花开 一作：有花)"},
    {"title": "卢家少郁金堂，海燕双栖玳瑁梁。", "content": "九月寒砧催木叶，十年征戍忆辽阳。白狼河北音书断，丹凤城南秋夜长。谁为含愁独不见，更教明月照流黄。"},
    {"title": "梧桐相待老，鸳鸯会双死。", "content": "贞女贵殉夫，舍生亦如此。波澜誓不起，妾心古井水。(古井水 一作：井中水)"},
    {"title": "慈母手中线，游子身上衣。", "content": "临行密密缝，意恐迟迟归。谁言寸草心，报得三春晖。"},
    {"title": "开元二十六年，客有从元戎出塞而还者，作《燕歌行》以示，适感征戍之事，因而和焉。", "content": "汉家烟尘在东北，汉将辞家破残贼。男儿本自重横行，天子非常赐颜色。摐金伐鼓下榆关，旌旆逶迤碣石间。(摐"},
    {"title": "君家何处住，妾住在横塘。", "content": "停船暂借问，或恐是同乡。"},
    {"title": "家临九江水，来去九江侧。", "content": "同是长干人，生小不相识。"},
    {"title": "鹫翎金仆姑，燕尾绣蝥弧。", "content": "独立扬新令，千营共一呼。"},
    {"title": "林暗草惊风，将军夜引弓。", "content": "平明寻白羽，没在石棱中。"},
    {"title": "月黑雁飞高，单于夜遁逃。", "content": "欲将轻骑逐，大雪满弓刀。"},
    {"title": "野幕敞琼筵，羌戎贺劳旋。", "content": "醉和金甲舞，雷鼓动山川。"},
    {"title": "平林漠漠烟如织，寒山一带伤心碧。", "content": "暝色入高楼，有人楼上愁。玉阶空伫立，宿鸟归飞急。何处是归程？长亭更短亭。(更短亭 一作：连短亭)"},
    {"title": "箫声咽，秦娥梦断秦楼月。", "content": "秦楼月，年年柳色，灞陵伤别。乐游原上清秋节，咸阳古道音尘绝。音尘绝，西风残照，汉家陵阙。"},
    {"title": "秋风清，秋月明，落叶聚还散，寒鸦栖复惊。", "content": "相思相见知何日？此时此夜难为情！入我相思门，知我相思苦。长相思兮长相忆，短相思兮无穷极。早知如此绊人心，何如当初莫相识。(后三句疑伪作)"},
    {"title": "西塞山前白鹭飞，桃花流水鳜鱼肥。", "content": "青箬笠，绿蓑衣，斜风细雨不须归。"},
    {"title": "边草，边草，边草尽来兵老。", "content": "山南山北雪晴，千里万里月明。明月，明月，胡笳一声愁绝。"},
    {"title": "团扇，团扇，美人病来遮面。", "content": "玉颜憔悴三年，谁复商量管弦。弦管，弦管，春草昭阳路断。"},
    {"title": "山桃红花满上头，蜀江春水拍山流。", "content": "花红易衰似郎意，水流无限似侬愁。"},
    {"title": "斑竹枝，斑竹枝，泪痕点点寄相思。", "content": "楚客欲听瑶瑟怨，潇湘深夜月明时。"},
    {"title": "江南好，风景旧曾谙。", "content": "日出江花红胜火，春来江水绿如蓝。能不忆江南？"},
    {"title": "江南好，风景旧曾谙。", "content": "日出江花红胜火，春来江水绿如蓝。能不忆江南？江南忆，最忆是杭州。山寺月中寻桂子，郡亭枕上看潮头。何日更重游？江南忆，其次忆吴宫。吴酒一杯春竹叶，吴娃双舞醉芙蓉。"},
    {"title": "汴水流，泗水流，流到瓜洲古渡头。", "content": "吴山点点愁。思悠悠，恨悠悠，恨到归时方始休。月明人倚楼。"},
    {"title": "花非花，雾非雾。", "content": "夜半来，天明去。来如春梦几多时？去似朝云无觅处。"},
    {"title": "借问江潮与海水，何似君情与妾心？相恨不如潮有信，相思始觉海非深。", "content": ""},
    {"title": "菡萏香莲十顷陂(举棹)，小姑贪戏采莲迟(年少)。", "content": "晚来弄水船头湿(举棹)，更脱红裙裹鸭儿(年少)。"},
    {"title": "兰烬落，屏上暗红蕉。", "content": "闲梦江南梅熟日，夜船吹笛雨萧萧。人语驿边桥。"},
    {"title": "梳洗罢，独倚望江楼。", "content": "过尽千帆皆不是，斜晖脉脉水悠悠。肠断白蘋洲。"},
    {"title": "小山重叠金明灭，鬓云欲度香腮雪。", "content": "懒起画蛾眉，弄妆梳洗迟。照花前后镜，花面交相映。新帖绣罗襦，双双金鹧鸪。(帖 一作：贴)"},
    {"title": "柳丝长，春雨细，花外漏声迢递。", "content": "惊塞雁，起城乌，画屏金鹧鸪。香雾薄，透帘幕，惆怅谢家池阁。红烛背，绣帘垂，梦长君不知。"},
    {"title": "红楼别夜堪惆怅，香灯半卷流苏帐。", "content": "残月出门时，美人和泪辞。琵琶金翠羽，弦上黄莺语。劝我早归家，绿窗人似花。"},
    {"title": "人人尽说江南好，游人只合江南老。", "content": "春水碧于天，画船听雨眠。垆边人似月，皓腕凝霜雪。未老莫还乡，还乡须断肠。"},
    {"title": "劝君今夜须沉醉，尊前莫话明朝事。", "content": "珍重主人心，酒深情亦深。须愁春漏短，莫诉金杯满。遇酒且呵呵，人生能几何。"},
    {"title": "四月十七，正是去年今日，别君时。", "content": "忍泪佯低面，含羞半敛眉。不知魂已断，空有梦相随。除却天边月，没人知。"},
    {"title": "昨夜夜半，枕上分明梦见。", "content": "语多时。依旧桃花面，频低柳叶眉。半羞还半喜，欲去又依依。觉来知是梦，不胜悲。"},
    {"title": "春日游，杏花吹满头。", "content": "陌上谁家年少，足风流。妾拟将身嫁与，一生休。纵被无情弃，不能羞。"},
    {"title": "红蓼渡头秋正雨，印沙鸥迹自成行，整鬟飘袖野风香。", "content": "不语含嚬深浦里，几回愁煞棹船郎，燕归帆尽水茫茫。"},
    {"title": "衔泥燕，飞到画堂前。", "content": "占得杏梁安稳处，体轻唯有主人怜，堪羡好因缘。"},
    {"title": "新月曲如眉，未有团圞意。", "content": "红豆不堪看，满眼相思泪。终日劈桃穰，仁在心儿里。两朵隔墙花，早晚成连理。"},
    {"title": "古庙依青嶂，行宫枕碧流。", "content": "水声山色锁妆楼。往事思悠悠。云雨朝还暮，烟花春复秋。啼猿何必近孤舟。行客自多愁。"},
    {"title": "乘彩舫，过莲塘，棹歌惊起睡鸳鸯。", "content": "游女带香偎伴笑，争窈窕，竞折团荷遮晚照。(带香 一作：带花)"},
    {"title": "永夜抛人何处去？绝来音。", "content": "香阁掩，眉敛，月将沉。争忍不相寻？怨孤衾。换我心，为你心，始知相忆深。"},
    {"title": "蓼岸风多橘柚香。", "content": "江边一望楚天长。片帆烟际闪孤光。目送征鸿飞杳杳，思随流水去茫茫。兰红波碧忆潇湘。"},
    {"title": "风乍起，吹皱一池春水。", "content": "闲引鸳鸯香径里，手挼红杏蕊。斗鸭阑干独倚，碧玉搔头斜坠。终日望君君不至，举头闻鹊喜。"},
    {"title": "谁道闲情抛掷久？每到春来，惆怅还依旧。", "content": "日日花前常病酒，敢辞镜里朱颜瘦。(抛掷 一作：抛弃；敢辞 一作：不辞)河畔青芜堤上柳，为问新愁，何事年年有？独立小桥风满袖，平林新月人归后。"},
    {"title": "几日行云何处去？忘却归来，不道春将暮。", "content": "百草千花寒食路，香车系在谁家树？泪眼倚楼频独语。双燕来时，陌上相逢否？撩乱春愁如柳絮，依依梦里无寻处。(依依 一作：悠悠)"},
    {"title": "雨晴烟晚。", "content": "绿水新池满。双燕飞来垂柳院，小阁画帘高卷。黄昏独倚朱阑。西南新月眉弯。砌下落花风起，罗衣特地春寒。"},
    {"title": "春日宴，绿酒一杯歌一遍。", "content": "再拜陈三愿：一愿郎君千岁，二愿妾身常健，三愿如同梁上燕，岁岁长相见。"},
    {"title": "菡萏香销翠叶残，西风愁起绿波间。", "content": "还与韶光共憔悴，不堪看。细雨梦回鸡塞远，小楼吹彻玉笙寒。多少泪珠何限恨，倚阑干。(何限恨 一作：无限恨)"},
    {"title": "手卷真珠上玉钩，依前春恨锁重楼。", "content": "风里落花谁是主？思悠悠。青鸟不传云外信，丁香空结雨中愁。回首绿波三峡暮，接天流。(三峡 一作：三楚)"},
    {"title": "昨夜风兼雨，帘帏飒飒秋声。", "content": "烛残漏断频欹枕，起坐不能平。世事漫随流水，算来一梦浮生。醉乡路稳宜频到，此外不堪行。(一梦 一作：梦里)"},
    {"title": "春花秋月何时了？往事知多少。", "content": "小楼昨夜又东风，故国不堪回首月明中。雕栏玉砌应犹在，只是朱颜改。问君能有几多愁？恰似一江春水向东流。(栏 一作：阑)"},
    {"title": "风回小院庭芜绿，柳眼春相续。", "content": "凭阑半日独无言，依旧竹声新月似当年。笙歌未散尊罍在，池面冰初解。烛明香暗画堂深，满鬓青霜残雪思难任。(画堂 一作：画楼)"},
    {"title": "无言独上西楼，月如钩。", "content": "寂寞梧桐深院锁清秋。剪不断，理还乱，是离愁。别是一般滋味在心头。(一般 一作：一番)"},
    {"title": "林花谢了春红，太匆匆。", "content": "无奈朝来寒雨晚来风。胭脂泪，相留醉，几时重。自是人生长恨水长东。(相留 一作：留人)"},
    {"title": "一重山，两重山。", "content": "山远天高烟水寒，相思枫叶丹。菊花开，菊花残。塞雁高飞人未还，一帘风月闲。"},
    {"title": "帘外雨潺潺，春意阑珊。", "content": "罗衾不耐五更寒。梦里不知身是客，一晌贪欢。独自莫凭栏，无限江山。别时容易见时难。流水落花春去也，天上人间。(江山 一作：关山)"},
    {"title": "别来春半，触目柔肠断。", "content": "砌下落梅如雪乱，拂了一身还满。(柔肠断 一作：愁肠断)雁来音信无凭，路遥归梦难成。离恨恰如春草，更行更远还生。"},
    {"title": "深院静，小庭空，断续寒砧断续风。", "content": "无奈夜长人不寐，数声和月到帘栊。"},
    {"title": "四十年来家国，三千里地山河。", "content": "凤阁龙楼连霄汉，玉树琼枝作烟萝，几曾识干戈？一旦归为臣虏，沈腰潘鬓消磨。最是仓皇辞庙日，教坊犹奏别离歌，垂泪对宫娥。"},
    {"title": "饮散离亭西去，浮生长恨飘蓬。", "content": "回头烟柳渐重重。淡云孤雁远，寒日暮天红。今夜画船何处？潮平淮月朦胧。酒醒人静奈愁浓。残灯孤枕梦，轻浪五更风。"},
    {"title": "枕前发尽千般愿，要休且待青山烂。", "content": "水面上秤锤浮，直待黄河彻底枯。白日参辰现，北斗回南面。休即未能休，且待三更见日头。(见 一作：出)"},
    {"title": "叵耐灵鹊多谩语，送喜何曾有凭据？几度飞来活捉取，锁上金笼休共语。", "content": "比拟好心来送喜，谁知锁我在金笼里。欲他征夫早归来，腾身却放我向青云里。"},
    {"title": "五两竿头风欲平，长风举棹觉船轻。", "content": "柔橹不施停却棹，是船行。满眼风波多闪灼，看山恰似走来迎。子细看山山不动，是船行。"},
    {"title": "天上月，遥望似一团银。", "content": "夜久更阑风渐紧。为奴吹散月边云。照见负心人。(为 一作：与)"},
    {"title": "雨恨云愁，江南依旧称佳丽。", "content": "水村渔市，一缕孤烟细。天际征鸿，遥认行如缀。平生事，此时凝睇，谁会凭栏意。(栏 通：阑)"},
    {"title": "长忆观潮，满郭人争江上望。", "content": "来疑沧海尽成空，万面鼓声中。 弄潮儿向涛头立，手把红旗旗不湿。别来几向梦中看，梦觉尚心寒。"},
    {"title": "吴山青，越山青，两岸青山相送迎，谁知离别情？(相送 一作：相对；谁知离别情 一作：争忍有离情)君泪盈，妾泪盈，罗带同心结未成，江边潮已平。", "content": "(江边 一作：江头)"},
    {"title": "春色将阑，莺声渐老，红英落尽青梅小。", "content": "画堂人静雨蒙蒙，屏山半掩余香袅。密约沉沉，离情杳杳，菱花尘满慵将照。倚楼无语欲销魂，长空黯淡连芳草。"},
    {"title": "碧云天，黄叶地，秋色连波，波上寒烟翠。", "content": "山映斜阳天接水，芳草无情，更在斜阳外。黯乡魂，追旅思，夜夜除非，好梦留人睡。明月楼高休独倚，酒入愁肠，化作相思泪。(留人睡 一作：留人醉)"},
    {"title": "塞下秋来风景异，衡阳雁去无留意。", "content": "四面边声连角起，千嶂里，长烟落日孤城闭。浊酒一杯家万里，燕然未勒归无计。羌管悠悠霜满地，人不寐，将军白发征夫泪。"},
    {"title": "伫倚危楼风细细，望极春愁，黯黯生天际。", "content": "草色烟光残照里，无言谁会凭阑意。(阑 通 栏)拟把疏狂图一醉，对酒当歌，强乐还无味。衣带渐宽终不悔，为伊消得人憔悴。"},
    {"title": "自春来惨绿愁红，芳心是事可可。", "content": "日上花梢，莺穿柳带，犹压香衾卧。暖酥消、腻云亸，终日厌厌倦梳裹。无那。恨薄情一去，音书无个。早知恁么，悔当初、不把雕鞍锁。向鸡窗，只与蛮笺象管，拘束教"},
    {"title": "寒蝉凄切，对长亭晚，骤雨初歇。", "content": "都门帐饮无绪，留恋处，兰舟催发。执手相看泪眼，竟无语凝噎。念去去，千里烟波，暮霭沉沉楚天阔。(留恋处 一作：方留恋处)多情自古伤离别，更那堪，冷落清秋"},
    {"title": "东南形胜，三吴都会，钱塘自古繁华。", "content": "烟柳画桥，风帘翠幕，参差十万人家。云树绕堤沙，怒涛卷霜雪，天堑无涯。市列珠玑，户盈罗绮，竞豪奢。(三吴 一作：江吴)重湖叠𪩘清嘉，有三秋桂子，十"},
    {"title": "才过笄年，初绾云鬟，便学歌舞。", "content": "席上尊前，王孙随分相许。算等闲、酬一笑，便千金慵觑。常只恐、容易蕣华偷换，光阴虚度。 已受君恩顾，好与花为主。万里丹霄，何妨携手同归去。永弃却、烟花伴"},
    {"title": "对潇潇暮雨洒江天，一番洗清秋。", "content": "渐霜风凄紧，关河冷落，残照当楼。是处红衰翠减，苒苒物华休。唯有长江水，无语东流。(凄紧 一作：凄惨；唯有 一作：惟有) 不忍登高临远，望故乡渺邈，归思"},
    {"title": "远岸收残雨。", "content": "雨残稍觉江天暮。拾翠汀洲人寂静，立双双鸥鹭。望几点、渔灯隐映蒹葭浦。停画桡、两两舟人语。道去程今夜，遥指前村烟树。游宦成羁旅。短樯吟倚闲凝伫。万水千山迷远近，想乡关何处"},
    {"title": "黄金榜上，偶失龙头望。", "content": "明代暂遗贤，如何向。未遂风云便，争不恣游狂荡。何须论得丧？才子词人，自是白衣卿相。(游狂荡 一作：狂荡)烟花巷陌，依约丹青屏障。幸有意中人，堪寻访。且恁偎红倚"},
    {"title": "时为嘉禾小倅，以病眠，不赴府会。", "content": "水调数声持酒听，午醉醒来愁未醒。送春春去几时回？临晚镜，伤流景，往事后期空记省。沙上并禽池上暝，云破月来花弄影。重重帘幕密遮灯，风不定，人初静，明日"},
    {"title": "数声鶗鴂，又报芳菲歇。", "content": "惜春更把残红折。雨轻风色暴，梅子青时节。永丰柳，无人尽日飞花雪。(飞花雪 一作：花飞雪)莫把幺弦拨，怨极弦能说。天不老，情难绝。心似双丝网，中有千千结。夜过也"},
    {"title": "乍暖还轻冷。", "content": "风雨晚来方定。庭轩寂寞近清明，残花中酒，又是去年病。 楼头画角风吹醒。入夜重门静。那堪更被明月，隔墙送过秋千影。"},
    {"title": "双蝶绣罗裙，东池宴，初相见。", "content": "朱粉不深匀，闲花淡淡春。 细看诸处好，人人道，柳腰身。昨日乱山昏，来时衣上云。"},
    {"title": "一曲新词酒一杯，去年天气旧亭台。", "content": "夕阳西下几时回？无可奈何花落去，似曾相识燕归来。小园香径独徘徊。"},
    {"title": "一向年光有限身，等闲离别易销魂，酒筵歌席莫辞频。", "content": "满目山河空念远，落花风雨更伤春，不如怜取眼前人。"},
    {"title": "红笺小字，说尽平生意。", "content": "鸿雁在云鱼在水，惆怅此情难寄。 斜阳独倚西楼，遥山恰对帘钩。人面不知何处，绿波依旧东流。"},
    {"title": "家住西秦。", "content": "赌博艺随身。花柳上、斗尖新。偶学念奴声调，有时高遏行云。蜀锦缠头无数，不负辛勤。 数年来往咸京道，残杯冷炙漫消魂。衷肠事、托何人。若有知音见采，不辞遍唱阳春。一曲当筵落泪"},
    {"title": "槛菊愁烟兰泣露，罗幕轻寒，燕子双飞去。", "content": "明月不谙离恨苦，斜光到晓穿朱户。(双飞去 一作：双来去；离恨苦 一作：离别苦)昨夜西风凋碧树，独上高楼，望尽天涯路。欲寄彩笺兼尺素，山长水阔知"},
    {"title": "燕子来时新社，梨花落后清明。", "content": "池上碧苔三四点，叶底黄鹂一两声。日长飞絮轻。巧笑东邻女伴，采桑径里逢迎。疑怪昨宵春梦好，元是今朝斗草赢。笑从双脸生。"},
    {"title": "一带江山如画，风物向秋潇洒。", "content": "水浸碧天何处断？霁色冷光相射。蓼屿荻花洲，掩映竹篱茅舍。云际客帆高挂，烟外酒旗低亚。多少六朝兴废事，尽入渔樵闲话。怅望倚层楼，红日无言西下。(红日 一作"},
    {"title": "东城渐觉风光好，縠皱波纹迎客棹。", "content": "绿杨烟外晓寒轻，红杏枝头春意闹。浮生长恨欢娱少，肯爱千金轻一笑。为君持酒劝斜阳，且向花间留晚照。"},
    {"title": "满斟绿醑留君住。", "content": "莫匆匆归去。三分春色二分愁，更一分风雨。花开花谢、都来几许。且高歌休诉。不知来岁牡丹时，再相逢何处。"},
    {"title": "清晨帘幕卷轻霜，呵手试梅妆。", "content": "都缘自有离恨，故画作远山长。思往事，惜流芳，易成伤。拟歌先敛，欲笑还颦，最断人肠。"},
    {"title": "候馆梅残，溪桥柳细。", "content": "草薰风暖摇征辔。离愁渐远渐无穷，迢迢不断如春水。 寸寸柔肠，盈盈粉泪。楼高莫近危阑倚。平芜尽处是春山，行人更在春山外。"},
    {"title": "去年元夜时，花市灯如昼。", "content": "月上柳梢头，人约黄昏后。今年元夜时，月与灯依旧。不见去年人，泪湿春衫袖。(湿 一作：满)"},
    {"title": "庭院深深深几许，杨柳堆烟，帘幕无重数。", "content": "玉勒雕鞍游冶处，楼高不见章台路。雨横风狂三月暮，门掩黄昏，无计留春住。泪眼问花花不语，乱红飞过秋千去。"},
    {"title": "花底忽闻敲两桨。", "content": "逡巡女伴来寻访。酒盏旋将荷叶当。莲舟荡。时时盏里生红浪。花气酒香清厮酿。花腮酒面红相向。醉倚绿阴眠一饷。惊起望。船头阁在沙滩上。(阁 同：搁)"},
    {"title": "近日门前溪水涨。", "content": "郎船几度偷相访。船小难开红斗帐。无计向。合欢影里空惆怅。愿妾身为红菡萏。年年生在秋江上。重愿郎为花底浪。无隔障。随风逐雨长来往。"},
    {"title": "把酒祝东风，且共从容。", "content": "垂杨紫陌洛城东。总是当时携手处，游遍芳丛。聚散苦匆匆，此恨无穷。今年花胜去年红。可惜明年花更好，知与谁同？"},
    {"title": "锁离愁，连绵无际，来时陌上初熏。", "content": "绣帏人念远，暗垂珠泪，泣送征轮。长亭长在眼，更重重、远水孤云。但望极楼高，尽日目断王孙。 消魂。池塘别后，曾行处、绿妒轻裙。恁时携素手，乱花飞絮里，"},
    {"title": "登临送目，正故国晚秋，天气初肃。", "content": "千里澄江似练，翠峰如簇。归帆去棹残阳里，背西风，酒旗斜矗。彩舟云淡，星河鹭起，画图难足。(归帆 一作：征帆)念往昔，繁华竞逐。叹门外楼头，悲恨相续。"},
    {"title": "平岸小桥千嶂抱。", "content": "柔蓝一水萦花草。茅屋数间窗窈窕。尘不到。时时自有春风扫。午枕觉来闻语鸟。欹眠似听朝鸡早。忽忆故人今总老。贪梦好。茫然忘了邯郸道。"},
    {"title": "伊吕两衰翁，历遍穷通。", "content": "一为钓叟一耕佣。若使当时身不遇，老了英雄。汤武偶相逢，风虎云龙。兴王只在谈笑中。直至如今千载后，谁与争功！(谈笑 一作：笑谈)"},
    {"title": "留春不住，费尽莺儿语。", "content": "满地残红宫锦污，昨夜南园风雨。小怜初上琵琶，晓来思绕天涯。不肯画堂朱户，春风自在杨花。"},
    {"title": "水是眼波横，山是眉峰聚。", "content": "欲问行人去那边？眉眼盈盈处。才始送春归，又送君归去。若到江南赶上春，千万和春住。"},
    {"title": "梦后楼台高锁，酒醒帘幕低垂。", "content": "去年春恨却来时。落花人独立，微雨燕双飞。 记得小蘋初见，两重心字罗衣。琵琶弦上说相思。当时明月在，曾照彩云归。(蘋 通：苹)"},
    {"title": "醉别西楼醒不记。", "content": "春梦秋云，聚散真容易。斜月半窗还少睡。画屏闲展吴山翠。 衣上酒痕诗里字。点点行行，总是凄凉意。红烛自怜无好计。夜寒空替人垂泪。"},
    {"title": "留人不住，醉解兰舟去。", "content": "一棹碧涛春水路，过尽晓莺啼处。渡头杨柳青青，枝枝叶叶离情。此后锦书休寄，画楼云雨无凭。"},
    {"title": "彩袖殷勤捧玉钟。", "content": "当年拚却醉颜红。舞低杨柳楼心月，歌尽桃花扇底风。从别后，忆相逢。几回魂梦与君同。今宵剩把银釭照，犹恐相逢是梦中。"},
    {"title": "小令尊前见玉箫。", "content": "银灯一曲太妖娆。歌中醉倒谁能恨，唱罢归来酒未消。 春悄悄，夜迢迢。碧云天共楚宫遥。梦魂惯得无拘检，又踏杨花过谢桥。"},
    {"title": "旧香残粉似当初。", "content": "人情恨不如。一春犹有数行书。秋来书更疏。 衾凤冷，枕鸳孤。愁肠待酒舒。梦魂纵有也成虚。那堪和梦无。"},
    {"title": "木叶下君山。", "content": "空水漫漫。十分斟酒敛芳颜。不是渭城西去客，休唱阳关。醉袖抚危栏。天淡云闲。何人此路得生还。回首夕阳红尽处，应是长安。"},
    {"title": "似花还似非花，也无人惜从教坠。", "content": "抛家傍路，思量却是，无情有思。萦损柔肠，困酣娇眼，欲开还闭。梦随风万里，寻郎去处，又还被、莺呼起。不恨此花飞尽，恨西园、落红难缀。晓来雨过，遗踪何在？"},
    {"title": "王定国歌儿曰柔奴，姓宇文氏，眉目娟丽，善应对，家世住京师。", "content": "定国南迁归，余问柔：“广南风土， 应是不好？”柔对曰：“此心安处，便是吾乡。”因为缀词云。常羡人间琢玉郎，天应乞与点酥娘。"},
    {"title": "丙辰中秋，欢饮达旦，大醉，作此篇，兼怀子由。", "content": "明月几时有？把酒问青天。不知天上宫阙，今夕是何年。我欲乘风归去，又恐琼楼玉宇，高处不胜寒。起舞弄清影，何似在人间。(何似 一作：何时；又"},
    {"title": "大江东去，浪淘尽，千古风流人物。", "content": "故垒西边，人道是，三国周郎赤壁。乱石穿空，惊涛拍岸，卷起千堆雪。(穿空 一作：崩云)江山如画，一时多少豪杰。遥想公瑾当年，小乔初嫁了，雄姿英发。羽扇"},
    {"title": "世事一场大梦，人生几度秋凉？夜来风叶已鸣廊。", "content": "看取眉头鬓上。(秋凉 一作：新凉)酒贱常愁客少，月明多被云妨。中秋谁与共孤光。把盏凄然北望。"},
    {"title": "顷在黄州，春夜行蕲水中，过酒家饮，酒醉，乘月至一溪桥上，解鞍曲肱，醉卧少休。", "content": "及觉已晓，乱山攒拥，流水锵然，疑非尘世也。书此语桥柱上。照野弥弥浅浪，横空隐隐层霄。障泥未解玉骢骄，我欲"},
    {"title": "夜饮东坡醒复醉，归来仿佛三更。", "content": "家童鼻息已雷鸣。敲门都不应，倚杖听江声。 长恨此身非我有，何时忘却营营。夜阑风静縠纹平。小舟从此逝，江海寄余生。(余 一作：馀)"},
    {"title": "三月七日，沙湖道中遇雨，雨具先去，同行皆狼狈，余独不觉。", "content": "已而遂晴，故作此(词)。莫听穿林打叶声，何妨吟啸且徐行。竹杖芒鞋轻胜马，谁怕？一蓑烟雨任平生。料峭春风吹酒醒，微冷，山头斜照"},
    {"title": "缺月挂疏桐，漏断人初静。", "content": "谁见幽人独往来，缥缈孤鸿影。(谁见 一作：时见)惊起却回头，有恨无人省。拣尽寒枝不肯栖，寂寞沙洲冷。"},
    {"title": "仆七岁时，见眉州老尼，姓朱，忘其名，年九十岁。", "content": "自言尝随其师入蜀主孟昶宫中，一日大热，蜀主与花蕊夫人夜纳凉摩诃池上，作一词，朱具能记之。今四十年，朱已死久矣，人无知此词者，但记其首两"},
    {"title": "老夫聊发少年狂，左牵黄，右擎苍，锦帽貂裘，千骑卷平冈。", "content": "为报倾城随太守，亲射虎，看孙郎。酒酣胸胆尚开张。鬓微霜，又何妨！持节云中，何日遣冯唐？会挽雕弓如满月，西北望，射天狼。"},
    {"title": "十年生死两茫茫，不思量，自难忘。", "content": "千里孤坟，无处话凄凉。纵使相逢应不识，尘满面，鬓如霜。夜来幽梦忽还乡，小轩窗，正梳妆。相顾无言，惟有泪千行。料得年年肠断处，明月夜，短松冈。"},
    {"title": "花褪残红青杏小，燕子飞时，绿水人家绕。", "content": "枝上柳绵吹又少。天涯何处无芳草。墙里秋千墙外道，墙外行人，墙里佳人笑。笑渐不闻声渐悄。多情却被无情恼。"},
    {"title": "彭城夜宿燕子楼，梦盼盼，因作此词。", "content": "明月如霜，好风如水，清景无限。曲港跳鱼，圆荷泻露，寂寞无人见。紞如三鼓，铿然一叶，黯黯梦云惊断。夜茫茫，重寻无处，觉来小园行遍。 天涯倦客，山中归"},
    {"title": "游蕲水清泉寺，寺临兰溪，溪水西流。", "content": "山下兰芽短浸溪，松间沙路净无泥，萧萧暮雨子规啼。(萧萧 一作：潇潇)谁道人生无再少？门前流水尚能西！休将白发唱黄鸡。"},
    {"title": "簌簌衣巾落枣花，村南村北响缲车，牛衣古柳卖黄瓜。", "content": "(缲 通：缫)酒困路长惟欲睡，日高人渴漫思茶。敲门试问野人家。"},
    {"title": "我住长江头，君住长江尾。", "content": "日日思君不见君，共饮长江水。 此水几时休，此恨何时已。只愿君心似我心，定不负相思意。"},
    {"title": "红旗高举，飞出深深杨柳渚。", "content": "鼓击春雷，直破烟波远远回。欢声震地，惊退万人争战气。金碧楼西，衔得锦标第一归。"},
    {"title": "杨柳丝丝弄轻柔，烟缕织成愁。", "content": "海棠未雨，梨花先雪，一半春休。而今往事难重省，归梦绕秦楼。相思只在，丁香枝上，豆蔻梢头。"},
    {"title": "八月十七日，同诸生步自永安城楼，过张宽夫园待月。", "content": "偶有名酒，因以金荷酌众客。客有孙彦立，善吹笛。援笔作乐府长短句，文不加点。断虹霁雨，净秋空，山染修眉新绿。桂影扶疏，谁便道，今夕清辉"},
    {"title": "瑶草一何碧，春入武陵溪。", "content": "溪上桃花无数，枝上有黄鹂。我欲穿花寻路，直入白云深处，浩气展虹霓。只恐花深里，红露湿人衣。坐玉石，倚玉枕，拂金徽。谪仙何处？无人伴我白螺杯。我为灵芝仙草，不"},
    {"title": "春归何处？寂寞无行路。", "content": "若有人知春去处，唤取归来同住。 春无踪迹谁知？除非问取黄鹂。百啭无人能解，因风飞过蔷薇。(问取 一作：唤取)"},
    {"title": "黄菊枝头生晓寒。", "content": "人生莫放酒杯干。风前横笛斜吹雨，醉里簪花倒著冠。 身健在，且加餐。舞裙歌板尽清欢。黄花白发相牵挽，付与时人冷眼看。"},
    {"title": "一年春物，惟梅柳间意味最深。", "content": "至莺花烂漫时，则春已衰迟，使人无复新意。予作《洞仙歌》，使探春者歌之，无后时之悔。雪云散尽，放晓晴池院。杨柳于人便青眼。更风流多处，一点梅心，相映远，约"},
    {"title": "小雨纤纤风细细，万家杨柳青烟里。", "content": "恋树湿花飞不起，愁无比，和春付与东流水。九十光阴能有几？金龟解尽留无计。寄语东阳沽酒市，拚一醉，而今乐事他年泪。"},
    {"title": "胡马嘶风，汉旗翻雪，彤云又吐，一竿残照。", "content": "古木连空，乱山无数，行尽暮沙衰草。星斗横幽馆，夜无眠、灯花空老。雾浓香鸭，冰凝泪烛，霜天难晓。 长记小妆才了，一杯未尽，离怀多少。醉里秋波，"},
    {"title": "梅英疏淡，冰澌溶泄，东风暗换年华。", "content": "金谷俊游，铜驼巷陌，新晴细履平沙。长记误随车。正絮翻蝶舞，芳思交加。柳下桃蹊，乱分春色到人家。西园夜饮鸣笳。有华灯碍月，飞盖妨花。兰苑未空，行人渐"},
    {"title": "倚危亭。", "content": "恨如芳草，萋萋刬尽还生。念柳外青骢别后，水边红袂分时，怆然暗惊。无端天与娉婷。夜月一帘幽梦，春风十里柔情。怎奈向、欢娱渐随流水，素弦声断，翠绡香减，那堪片片飞花弄晚，蒙蒙残"},
    {"title": "山抹微云，天连衰草，画角声断谯门。", "content": "暂停征棹，聊共引离尊。多少蓬莱旧事，空回首、烟霭纷纷。斜阳外，寒鸦万点，流水绕孤村。(连衰草 一作：粘衰草；万点 一作：数点)销魂当此际，香囊暗解"},
    {"title": "西城杨柳弄春柔，动离忧，泪难收。", "content": "犹记多情、曾为系归舟。碧野朱桥当日事，人不见，水空流。韶华不为少年留，恨悠悠，几时休？飞絮落花时候、一登楼。便作春江都是泪，流不尽，许多愁。"},
    {"title": "纤云弄巧，飞星传恨，银汉迢迢暗度。", "content": "金风玉露一相逢，便胜却人间无数。柔情似水，佳期如梦，忍顾鹊桥归路。两情若是久长时，又岂在朝朝暮暮。"},
    {"title": "水边沙外。", "content": "城郭春寒退。花影乱，莺声碎。飘零疏酒盏，离别宽衣带。人不见，碧云暮合空相对。 忆昔西池会。鹓鹭同飞盖。携手处，今谁在。日边清梦断，镜里朱颜改。春去也，飞红万点愁如海。"},
    {"title": "雾失楼台，月迷津渡。", "content": "桃源望断无寻处。可堪孤馆闭春寒，杜鹃声里斜阳暮。 驿寄梅花，鱼传尺素。砌成此恨无重数。郴江幸自绕郴山，为谁流下潇湘去。"},
    {"title": "漠漠轻寒上小楼，晓阴无赖似穷秋。", "content": "淡烟流水画屏幽。自在飞花轻似梦，无边丝雨细如愁。宝帘闲挂小银钩。"},
    {"title": "树绕村庄，水满陂塘。", "content": "倚东风，豪兴徜徉。小园几许，收尽春光。有桃花红，李花白，菜花黄。远远围墙，隐隐茅堂。飏青旗，流水桥旁。偶然乘兴，步过东冈。正莺儿啼，燕儿舞，蝶儿忙。(围墙 一作"},
    {"title": "重过阊门万事非。", "content": "同来何事不同归。梧桐半死清霜后，头白鸳鸯失伴飞。 原上草，露初晞。旧栖新垅两依依。空床卧听南窗雨，谁复挑灯夜补衣。"},
    {"title": "砧面莹，杵声齐。", "content": "捣就征衣泪墨题。寄到玉关应万里，戍人犹在玉关西。"},
    {"title": "杨柳回塘，鸳鸯别浦。", "content": "绿萍涨断莲舟路。断无蜂蝶慕幽香，红衣脱尽芳心苦。 返照迎潮，行云带雨。依依似与骚人语。当年不肯嫁春风，无端却被秋风误。"},
    {"title": "凌波不过横塘路，但目送、芳尘去。", "content": "锦瑟华年谁与度？月桥花院，琐窗朱户，只有春知处。(花院 一作：花榭)飞云冉冉蘅皋暮，彩笔新题断肠句。试问闲情都几许？一川烟草，满城风絮，梅子黄时雨。"},
    {"title": "少年侠气，交结五都雄。", "content": "肝胆洞，毛发耸。立谈中，死生同。一诺千金重。推翘勇，矜豪纵。轻盖拥，联飞鞚，斗城东。轰饮酒垆，春色浮寒瓮，吸海垂虹。闲呼鹰嗾犬，白羽摘雕弓，狡穴俄空。乐匆匆。"},
    {"title": "薄雨收寒，斜照弄晴，春意空阔。", "content": "长亭柳色才黄，远客一枝先折。烟横水际，映带几点归鸿，平沙消尽龙荒雪。犹记出关来，恰如今时节。将发。画楼芳酒，红泪清歌，顿成轻别。回首经年，杳杳音尘都绝"},
    {"title": "紫府东风放夜时。", "content": "步莲秾李伴人归。五更钟动笙歌散，十里月明灯火稀。 香苒苒，梦依依。天涯寒尽减春衣。凤凰城阙知何处，寥落星河一雁飞。"},
    {"title": "十里青山远，潮平路带沙。", "content": "数声啼鸟怨年华。又是凄凉时候，在天涯。白露收残月，清风散晓霞。绿杨堤畔问荷花：记得年时沽酒，那人家？(残月 一作：残暑)"},
    {"title": "清波门外拥轻衣。", "content": "杨花相送飞。西湖又还春晚，水树乱莺啼。闲院宇，小帘帏。晚初归。钟声已过，篆香才点，月到门时。"},
    {"title": "买陂塘、旋栽杨柳，依稀淮岸江浦。", "content": "东皋嘉雨新痕涨，沙觜鹭来鸥聚。堪爱处最好是、一川夜月光流渚。无人独舞。任翠幄张天，柔茵藉地，酒尽未能去。 青绫被，莫忆金闺故步。儒冠曾把身误。弓刀千"},
    {"title": "开时似雪。谢时似雪。", "content": "花中奇绝。香非在蕊，香非在萼，骨中香彻。 占溪风，留溪月。堪羞损、山桃如血。直饶更、疏疏淡淡，终有一般情别。"},
    {"title": "帘幕疏疏风透。", "content": "一线香飘金兽。朱阑倚遍黄昏后。廊上月华如昼。 别离滋味浓于酒。著人瘦。此情不及墙东柳。春色年年如旧。(墙东 一作：东墙)"},
    {"title": "未遇行藏谁肯信，如今方表名踪。", "content": "无端良匠画形容。当风轻借力，一举入高空。 才得吹嘘身渐稳，只疑远赴蟾宫。雨馀时候夕阳红。几人平地上，看我碧霄中。"},
    {"title": "章台路。还见褪粉梅梢，试花桃树。", "content": "愔愔坊陌人家，定巢燕子，归来旧处。 黯凝伫。因念个人痴小，乍窥门户。侵晨浅约宫黄，障风映袖，盈盈笑语。 前度刘郎重到，访邻寻里，同时歌舞。唯有旧家秋"},
    {"title": "风老莺雏，雨肥梅子，午阴嘉树清圆。", "content": "地卑山近，衣润费炉烟。人静乌鸢自乐，小桥外、新绿溅溅。凭阑久，黄芦苦竹，拟泛九江船。年年。如社燕，飘流瀚海，来寄修椽。且莫思身外，长近尊前。憔悴江"},
    {"title": "燎沉香，消溽暑。", "content": "鸟雀呼晴，侵晓窥檐语。叶上初阳干宿雨，水面清圆，一一风荷举。故乡遥，何日去？家住吴门，久作长安旅。五月渔郎相忆否？小楫轻舟，梦入芙蓉浦。"},
    {"title": "并刀如水，吴盐胜雪，纤手破新橙。", "content": "锦幄初温，兽烟不断，相对坐调笙。 低声问：向谁行宿？城上已三更。马滑霜浓，不如休去，直是少人行！"},
    {"title": "叶下斜阳照水。", "content": "卷轻浪、沈沈千里。桥上酸风射眸子。立多时，看黄昏，灯火市。古屋寒窗底。听几片、井桐飞坠。不恋单衾再三起。有谁知，为萧娘，书一纸。"},
    {"title": "风销焰蜡，露浥红莲，花市光相射。", "content": "桂华流瓦。纤云散，耿耿素娥欲下。衣裳淡雅。看楚女纤腰一把。箫鼓喧，人影参差，满路飘香麝。因念都城放夜。望千门如昼，嬉笑游冶。钿车罗帕。相逢处，自有暗"},
    {"title": "柳阴直，烟里丝丝弄碧。", "content": "隋堤上、曾见几番，拂水飘绵送行色。登临望故国，谁识京华倦客？长亭路，年去岁来，应折柔条过千尺。闲寻旧踪迹，又酒趁哀弦，灯照离席。梨花榆火催寒食。愁一箭风快，半"},
    {"title": "正单衣试酒，怅客里、光阴虚掷。", "content": "愿春暂留，春归如过翼。一去无迹。为问花何在，夜来风雨，葬楚宫倾国。钗钿堕处遗香泽。乱点桃蹊，轻翻柳陌。多情为谁追惜。但蜂媒蝶使，时叩窗隔。(怅客里 一"},
    {"title": "佳丽地，南朝盛事谁记。", "content": "山围故国绕清江，髻鬟对起。怒涛寂寞打孤城，风樯遥度天际。 断崖树、犹倒倚，莫愁艇子曾系。空余旧迹郁苍苍，雾沉半垒。夜深月过女墙来，伤心东望淮水。 酒旗戏鼓甚处"},
    {"title": "疏篱曲径田家小。", "content": "云树开清晓。天寒山色有无中。野外一声钟起、送孤蓬。 添衣策马寻亭堠。愁抱惟宜酒。菰蒲睡鸭占陂塘。纵被行人惊散、又成双。"},
    {"title": "月皎惊乌栖不定，更漏将残，轣辘牵金井。", "content": "唤起两眸清炯炯。泪花落枕红绵冷。执手霜风吹鬓影。去意徊徨，别语愁难听。楼上阑干横斗柄，露寒人远鸡相应。"},
    {"title": "桃溪不作从容住，秋藕绝来无续处。", "content": "当时相候赤阑桥，今日独寻黄叶路。烟中列岫青无数，雁背夕阳红欲暮。人如风后入江云，情似雨馀粘地絮。"},
    {"title": "杏花村馆酒旗风。", "content": "水溶溶，飏残红。野渡舟横，杨柳绿阴浓。望断江南山色远，人不见，草连空。 夕阳楼外晚烟笼。粉香融，淡眉峰。记得年时，相见画屏中。只有关山今夜月，千里外，素光同。"},
    {"title": "泪湿阑干花著露，愁到眉峰碧聚。", "content": "此恨平分取，更无言语空相觑。 断雨残云无意绪，寂寞朝朝暮暮。今夜山深处，断魂分付潮回去。"},
    {"title": "秋色渐将晚，霜信报黄花。", "content": "小窗低户深映，微路绕欹斜。为问山翁何事，坐看流年轻度，拚却鬓双华。徙倚望沧海，天净水明霞。 念平昔，空飘荡，遍天涯。归来三径重扫，松竹本吾家。却恨悲风时起，"},
    {"title": "缥缈危亭，笑谈独在千峰上。", "content": "与谁同赏。万里横烟浪。 老去情怀，犹作天涯想。空惆怅。少年豪放。莫学衰翁样。"},
    {"title": "新月娟娟，夜寒江静山衔斗。", "content": "起来搔首，梅影横窗瘦。好个霜天，闲却传杯手。君知否？乱鸦啼后，归兴浓于酒。"},
    {"title": "洗妆真态，不作铅花御。", "content": "竹外一枝斜，想佳人，天寒日暮。黄昏院落，无处著清香，风细细，雪垂垂，何况江头路。月边疏影，梦到消魂处。梅子欲黄时，又须作，廉纤细雨。孤芳一世，供断有情愁，消瘦"},
    {"title": "见梨花初带夜月，海棠半含朝雨。", "content": "内苑春、不禁过青门，御沟涨、潜通南浦。东风静、细柳垂金缕。望凤阙、非烟非雾。好时代、朝野多欢，遍九陌、太平箫鼓。 乍莺儿百啭断续，燕子飞来飞去。近绿水"},
    {"title": "摇首出红尘，醒醉更无时节。", "content": "活计绿蓑青笠，惯披霜冲雪。 晚来风定钓丝闲，上下是新月。千里水天一色，看孤鸿明灭。"},
    {"title": "金陵城上西楼，倚清秋。", "content": "万里夕阳垂地大江流。中原乱，簪缨散，几时收？试倩悲风吹泪过扬州。"},
    {"title": "我是清都山水郎，天教分付与疏狂。", "content": "曾批给雨支风券，累上留云借月章。(券 一作：敕；累上 一作：累奏)诗万首，酒千觞。几曾着眼看侯王？玉楼金阙慵归去，且插梅花醉洛阳。"},
    {"title": "朝云横度。", "content": "辘辘车声如水去。白草黄沙。月照孤村三两家。飞鸿过也。万结愁肠无昼夜。渐近燕山。回首乡关归路难。"},
    {"title": "山冥云阴重，天寒雨意浓。", "content": "数枝幽艳湿啼红。莫为惜花惆怅对东风。蓑笠朝朝出，沟塍处处通。人间辛苦是三农。要得一犁水足望年丰。"},
    {"title": "裁剪冰绡，轻叠数重，淡著燕脂匀注。", "content": "新样靓妆，艳溢香融，羞杀蕊珠宫女。易得凋零，更多少、无情风雨。愁苦。闲院落凄凉，几番春暮。(闲院 一作：问院)凭寄离恨重重，这双燕，何曾会人言语。"},
    {"title": "天上星河转，人间帘幕垂。", "content": "凉生枕簟泪痕滋。起解罗衣聊问、夜何其。翠贴莲蓬小，金销藕叶稀。旧时天气旧时衣。只有情怀不似、旧家时。"},
    {"title": "红藕香残玉簟秋。", "content": "轻解罗裳，独上兰舟。云中谁寄锦书来？雁字回时，月满西楼。花自飘零水自流。一种相思，两处闲愁。此情无计可消除，才下眉头，却上心头。"},
    {"title": "天接云涛连晓雾，星河欲转千帆舞。", "content": "仿佛梦魂归帝所。闻天语，殷勤问我归何处。我报路长嗟日暮，学诗谩有惊人句。九万里风鹏正举。风休住，蓬舟吹取三山去！"},
    {"title": "常记溪亭日暮，沉醉不知归路。", "content": "兴尽晚回舟，误入藕花深处。争渡，争渡，惊起一滩鸥鹭。"},
    {"title": "昨夜雨疏风骤，浓睡不消残酒。", "content": "试问卷帘人，却道海棠依旧。知否，知否？应是绿肥红瘦。"},
    {"title": "香冷金猊，被翻红浪，起来慵自梳头。", "content": "任宝奁尘满，日上帘钩。生怕离怀别苦，多少事、欲说还休。新来瘦，非干病酒，不是悲秋。休休，这回去也，千万遍《阳关》，也则难留。念武陵人远，烟锁秦楼。"},
    {"title": "年年雪里，常插梅花醉。", "content": "挼尽梅花无好意，赢得满衣清泪。今年海角天涯，萧萧两鬓生华。看取晚来风势，故应难看梅花。"},
    {"title": "暖雨晴风初破冻，柳眼梅腮，已觉春心动。", "content": "酒意诗情谁与共？泪融残粉花钿重。乍试夹衫金缕缝，山枕斜欹，枕损钗头凤。独抱浓愁无好梦，夜阑犹剪灯花弄。"},
    {"title": "寒日萧萧上琐窗，梧桐应恨夜来霜。", "content": "酒阑更喜团茶苦，梦断偏宜瑞脑香。秋已尽，日犹长，仲宣怀远更凄凉。不如随分尊前醉，莫负东篱菊蕊黄。"},
    {"title": "薄雾浓云愁永昼，瑞脑销金兽。", "content": "佳节又重阳，玉枕纱厨，半夜凉初透。(销金兽 一作：消金兽)东篱把酒黄昏后，有暗香盈袖。莫道不销魂，帘卷西风，人比黄花瘦。(销魂 一作：消魂；人比 一作："},
    {"title": "风住尘香花已尽，日晚倦梳头。", "content": "物是人非事事休，欲语泪先流。闻说双溪春尚好，也拟泛轻舟。只恐双溪舴艋舟，载不动许多愁。"},
    {"title": "蹴罢秋千，起来慵整纤纤手。", "content": "露浓花瘦，薄汗轻衣透。见客入来，袜刬金钗溜。和羞走，倚门回首，却把青梅嗅。"},
    {"title": "落日熔金，暮云合璧，人在何处。", "content": "染柳烟浓，吹梅笛怨，春意知几许。元宵佳节，融和天气，次第岂无风雨。来相召、香车宝马，谢他酒朋诗侣。(熔金 一作：镕金)中州盛日，闺门多暇，记得偏重三五"},
    {"title": "寻寻觅觅，冷冷清清，凄凄惨惨戚戚。", "content": "乍暖还寒时候，最难将息。三杯两盏淡酒，怎敌他、晚来风急！雁过也，正伤心，却是旧时相识。满地黄花堆积，憔悴损，如今有谁堪摘？守着窗儿，独自怎生得黑？"},
    {"title": "春涨一篙添水面。", "content": "芳草鹅儿，绿满微风岸。画舫夷犹湾百转。横塘塔近依前远。 江国多寒农事晚。村北村南，谷雨才耕遍。秀麦连冈桑叶贱。看看尝面收新茧。"},
    {"title": "恨君不似江楼月，南北东西，南北东西，只有相随无别离。", "content": "恨君却似江楼月，暂满还亏，暂满还亏，待得团圆是几时？"},
    {"title": "芳菲歇，故园目断伤心切。", "content": "伤心切，无边烟水，无穷山色。可堪更近乾龙节，眼中泪尽空啼血。空啼血，子规声外，晓风残月。"},
    {"title": "与君别。", "content": "相思一夜梅花发。梅花发。凄凉南浦，断桥斜月。 盈盈微步凌波袜。东风笑倚天涯阔。天涯阔。一声羌管，暮云愁绝。"},
    {"title": "天。", "content": "休使圆蟾照客眠。人何在，桂影自婵娟。"},
    {"title": "萋萋芳草忆王孙，柳外楼高空断魂，杜宇声声不忍闻。", "content": "欲黄昏，雨打梨花深闭门。"},
    {"title": "忆昔午桥桥上饮，坐中多是豪英。", "content": "长沟流月去无声。杏花疏影里，吹笛到天明。 二十余年如一梦，此身虽在堪惊。闲登小阁看新晴。古今多少事，渔唱起三更。"},
    {"title": "曳杖危楼去。", "content": "斗垂天、沧波万顷，月流烟渚。扫尽浮云风不定，未放扁舟夜渡。宿雁落、寒芦深处。怅望关河空吊影，正人间、鼻息鸣鼍鼓。谁伴我，醉中舞。 十年一梦扬州路。倚高寒、愁生故国，气吞"},
    {"title": "梦绕神州路。", "content": "怅秋风、连营画角，故宫离黍。底事昆仑倾砥柱，九地黄流乱注。聚万落千村狐兔。天意从来高难问，况人情老易悲难诉！更南浦，送君去。(怅秋风 一作：恨秋风；悲难诉 一作：悲如许"},
    {"title": "茅舍疏篱。", "content": "半飘残雪，斜卧低枝。可更相宜，烟笼修竹，月在寒溪。 宁宁伫立移时。判瘦损、无妨为伊。谁赋才情，画成幽思，写入新诗。"},
    {"title": "此腔自虏传至边，饮牛马即横笛吹之，不鼓不拍，声甚凄断。", "content": "闻兀术每遇对阵之际，吹此则鏖战无还期也。边头春未到，雪满交河道。暮沙明残照，塞烽云间小。断鸿悲，陇月低，泪湿征衣悄。岁华老。"},
    {"title": "怒发冲冠，凭栏处、潇潇雨歇。", "content": "抬望眼，仰天长啸，壮怀激烈。三十功名尘与土，八千里路云和月。莫等闲，白了少年头，空悲切！(栏 通：阑)靖康耻，犹未雪。臣子恨，何时灭！驾长车，踏破贺兰山"},
    {"title": "昨夜寒蛩不住鸣。", "content": "惊回千里梦，已三更。起来独自绕阶行。人悄悄，帘外月胧明。白首为功名。旧山松竹老，阻归程。欲将心事付瑶琴。知音少，弦断有谁听？"},
    {"title": "一点残红欲尽时。", "content": "乍凉秋气满屏帏。梧桐叶上三更雨，叶叶声声是别离。 调宝瑟，拨金猊。那时同唱鹧鸪词。如今风雨西楼夜，不听清歌也泪垂。"},
    {"title": "倚天绝壁，直下江千尺。", "content": "天际两蛾凝黛，愁与恨，几时极！暮潮风正急，酒阑闻塞笛。试问谪仙何处？青山外，远烟碧。"},
    {"title": "迟迟春月弄轻柔，花径暗香流。", "content": "清明过了，不堪回首，云锁朱楼。午窗睡起莺声巧，何处唤春愁？绿杨影里，海棠亭畔，红杏梢头。"},
    {"title": "春已半。", "content": "触目此情无限。十二阑干闲倚遍。愁来天不管。 好是风和日暖。输与莺莺燕燕。满院落花帘不卷。断肠芳草远。"},
    {"title": "楼外垂杨千万缕。", "content": "欲系青春，少住春还去。犹自风前飘柳絮。随春且看归何处。 绿满山川闻杜宇。便做无情，莫也愁人苦。把酒送春春不语。黄昏却下潇潇雨。"},
    {"title": "秋入云山，物情潇洒。", "content": "百般景物堪图画。丹枫万叶碧云边，黄花千点幽岩下。 已喜佳辰，更怜清夜。一轮明月林梢挂。松醪常与野人期，忘形共说清闲话。"},
    {"title": "郊原初过雨。", "content": "见败叶零乱，风定犹舞。斜阳挂深树。映浓愁浅黛，遥山眉妩。来时旧路。尚岩花、娇黄半吐。到而今，唯有溪边流水，见人如故。 无语。邮亭深静，下马还寻，旧曾题处。无聊倦旅。伤离"},
    {"title": "红酥手，黄縢酒，满城春色宫墙柳。", "content": "东风恶，欢情薄。一怀愁绪，几年离索。错、错、错。春如旧，人空瘦，泪痕红浥鲛绡透。桃花落，闲池阁。山盟虽在，锦书难托。莫、莫、莫！"},
    {"title": "秋到边城角声哀，烽火照高台。", "content": "悲歌击筑，凭高酹酒，此兴悠哉。多情谁似南山月，特地暮云开。灞桥烟柳，曲江池馆，应待人来。"},
    {"title": "驿外断桥边，寂寞开无主。", "content": "已是黄昏独自愁，更着风和雨。(着 同：著)无意苦争春，一任群芳妒。零落成泥碾作尘，只有香如故。"},
    {"title": "雪晓清笳乱起。", "content": "梦游处、不知何地。铁骑无声望似水。想关河，雁门西，青海际。睡觉寒灯里。漏声断、月斜窗纸。自许封侯在万里。有谁知，鬓虽残，心未死。"},
    {"title": "华灯纵博，雕鞍驰射，谁记当年豪举。", "content": "酒徒一半取封侯，独去作、江边渔父。轻舟八尺，低篷三扇，占断蘋洲烟雨。镜湖元自属闲人，又何必、官家赐与。(官家 一作：君恩)"},
    {"title": "当年万里觅封侯，匹马戍梁州。", "content": "关河梦断何处？尘暗旧貂裘。胡未灭，鬓先秋，泪空流。此生谁料，心在天山，身老沧洲。"},
    {"title": "世情薄，人情恶，雨送黄昏花易落。", "content": "晓风干，泪痕残。欲笺心事，独语斜阑。难，难，难！人成各，今非昨，病魂常似秋千索。角声寒，夜阑珊。怕人寻问，咽泪装欢。瞒，瞒，瞒！"},
    {"title": "独自上层楼，楼外青山远。", "content": "望以斜阳欲尽时，不见西飞雁。 独自下层楼，楼下蛩声怨。待到黄昏月上时，依旧柔肠断。"},
    {"title": "晚饮诚斋，忽有一鸥来泊松上，已而复去，感而赋之。", "content": "偶听松梢扑鹿，知是沙鸥来宿。稚子莫喧哗，恐惊他。俄倾忽然飞去，飞去不知何处？我已乞归休，报沙鸥。"},
    {"title": "月未到诚斋，先到万花川谷。", "content": "不是诚斋无月，隔一林修竹。 如今才是十三夜，月色已如玉。未是秋光奇绝，看十五十六。"},
    {"title": "不是爱风尘，似被前缘误。", "content": "花落花开自有时，总赖东君主。去也终须去，住也如何住！若得山花插满头，莫问奴归处。"},
    {"title": "长淮望断，关塞莽然平。", "content": "征尘暗，霜风劲，悄边声。黯销凝。追想当年事，殆天数，非人力，洙泗上，弦歌地，亦膻腥。隔水毡乡，落日牛羊下，区脱纵横。看名王宵猎，骑火一川明。笳鼓悲鸣。遣人惊。"},
    {"title": "雪洗虏尘静，风约楚云留。", "content": "何人为写悲壮，吹角古城楼。湖海平生豪气，关塞如今风景，剪烛看吴钩。剩喜燃犀处，骇浪与天浮。忆当年，周与谢，富春秋，小乔初嫁，香囊未解，勋业故优游。赤壁矶头落"},
    {"title": "洞庭青草，近中秋，更无一点风色。", "content": "玉鉴琼田三万顷，着我扁舟一叶。素月分辉，明河共影，表里俱澄澈。悠然心会，妙处难与君说。(着 同：著；玉鉴 一作：玉界；明河 一作 银河)应念岭海经年"},
    {"title": "问讯湖边春色，重来又是三年。", "content": "东风吹我过湖船，杨柳丝丝拂面。世路如今已惯，此心到处悠然。寒光亭下水如天，飞起沙鸥一片。"},
    {"title": "满载一船秋色，平铺十里湖光。", "content": "波神留我看斜阳，放起鳞鳞细浪。明日风回更好，今宵露宿何妨。水晶宫里奏霓裳，准拟岳阳楼上。"},
    {"title": "过尽征鸿来尽燕，故园消息茫然。", "content": "一春憔悴有谁怜。怀家寒食夜，中酒落花天。见说江头春浪渺，殷勤欲送归船。别来此处最萦牵。短篷南浦雨，疏柳断桥烟。"},
    {"title": "淳熙己亥，自湖北漕移湖南，同官王正之置酒小山亭，为赋。", "content": "更能消、几番风雨，匆匆春又归去。惜春长怕花开早，何况落红无数。春且住，见说道、天涯芳草无归路。怨春不语。算只有殷勤，画檐蛛网，"},
    {"title": "楚天千里清秋，水随天去秋无际。", "content": "遥岑远目，献愁供恨，玉簪螺髻。落日楼头，断鸿声里，江南游子。把吴钩看了，栏杆拍遍，无人会，登临意。(栏杆 一作：阑干)休说鲈鱼堪脍，尽西风，季鹰归未？"},
    {"title": "郁孤台下清江水，中间多少行人泪。", "content": "西北望长安，可怜无数山。青山遮不住，毕竟东流去。江晚正愁余，山深闻鹧鸪。 (愁余 一作：愁予)"},
    {"title": "东风夜放花千树，更吹落、星如雨。", "content": "宝马雕车香满路。凤箫声动，玉壶光转，一夜鱼龙舞。蛾儿雪柳黄金缕，笑语盈盈暗香去。众里寻他千百度。蓦然回首，那人却在，灯火阑珊处。"},
    {"title": "茅檐低小，溪上青青草。", "content": "醉里吴音相媚好，白发谁家翁媪？大儿锄豆溪东，中儿正织鸡笼。最喜小儿亡赖，溪头卧剥莲蓬。(亡 同：无)"},
    {"title": "绕床饥鼠，蝙蝠翻灯舞。", "content": "屋上松风吹急雨，破纸窗间自语。平生塞北江南，归来华发苍颜。布被秋宵梦觉，眼前万里江山。"},
    {"title": "举头西北浮云，倚天万里须长剑。", "content": "人言此地，夜深长见，斗牛光焰。我觉山高，潭空水冷，月明星淡。待燃犀下看，凭栏却怕，风雷怒，鱼龙惨。峡束苍江对起，过危楼，欲飞还敛。元龙老矣！不妨高卧，"},
    {"title": "明月别枝惊鹊，清风半夜鸣蝉。", "content": "稻花香里说丰年，听取蛙声一片。 七八个星天外，两三点雨山前。旧时茅店社林边，路转溪桥忽见。(溪桥 一作：溪头)"},
    {"title": "绿树听鹈鴂。", "content": "更那堪、鹧鸪声住，杜鹃声切。啼到春归无寻处，苦恨芳菲都歇。算未抵、人间离别。马上琵琶关塞黑，更长门、翠辇辞金阙。看燕燕，送归妾。 将军百战身名裂。向河梁、回头万里，故人"},
    {"title": "邑中园亭，仆皆为赋此词。", "content": "一日，独坐停云，水声山色，竞来相娱。意溪山欲援例者，遂作数语，庶几仿佛渊明思亲友之意云。甚矣吾衰矣。怅平生、交游零落，只今余几！白发空垂三千丈，一笑人间万事"},
    {"title": "少年不识愁滋味，爱上层楼。", "content": "爱上层楼，为赋新词强说愁。 而今识尽愁滋味，欲说还休。欲说还休，却道“天凉好个秋”！"},
    {"title": "一轮秋影转金波，飞镜又重磨。", "content": "把酒问姮娥：被白发，欺人奈何？乘风好去，长空万里，直下看山河。斫去桂婆娑，人道是，清光更多。"},
    {"title": "醉里挑灯看剑，梦回吹角连营。", "content": "八百里分麾下炙，五十弦翻塞外声，沙场秋点兵。马作的卢飞快，弓如霹雳弦惊。了却君王天下事，赢得生前身后名。可怜白发生！"},
    {"title": "壮岁旌旗拥万夫，锦襜突骑渡江初。", "content": "燕兵夜娖银胡䩮，汉箭朝飞金仆姑。追往事，叹今吾，春风不染白髭须。却将万字平戎策，换得东家种树书。"},
    {"title": "醉里且贪欢笑，要愁那得工夫。", "content": "近来始觉古人书，信著全无是处。昨夜松边醉倒，问松我醉何如。只疑松动要来扶，以手推松曰“去！”"},
    {"title": "千古江山，英雄无觅，孙仲谋处。", "content": "舞榭歌台，风流总被，雨打风吹去。斜阳草树，寻常巷陌，人道寄奴曾住。想当年，金戈铁马，气吞万里如虎。元嘉草草，封狼居胥，赢得仓皇北顾。四十三年，望中犹记"},
    {"title": "何处望神州？满眼风光北固楼。", "content": "千古兴亡多少事？悠悠。不尽长江滚滚流。年少万兜鍪，坐断东南战未休。天下英雄谁敌手？曹刘。生子当如孙仲谋。"},
    {"title": "见也如何暮。", "content": "别也如何遽。别也应难见也难，后会难凭据。 去也如何去。住也如何住。住也应难去也难，此际难分付。"},
    {"title": "不见南师久，漫说北群空。", "content": "当场只手，毕竟还我万夫雄。自笑堂堂汉使，得似洋洋河水，依旧只流东？且复穹庐拜，会向藁街逢！尧之都，舜之壤，禹之封。于中应有，一个半个耻臣戎！万里腥膻如许，千"},
    {"title": "闹花深处层楼，画帘半卷东风软。", "content": "春归翠陌，平莎茸嫩，垂杨金浅。迟日催花，淡云阁雨，轻寒轻暖。恨芳菲世界，游人未赏，都付与、莺和燕。 寂寞凭高念远。向南楼、一声归雁。金钗斗草，青丝勒马"},
    {"title": "安远楼小集，侑觞歌板之姬黄其姓者，乞词于龙洲道人，为赋此《唐多令》。", "content": "同柳阜之、刘去非、石民瞻、周嘉仲、陈孟参、孟容。时八月五日也。芦叶满汀洲，寒沙带浅流。二十年重过南楼。柳下系船犹"},
    {"title": "堂上谋臣尊俎，边头将士干戈。", "content": "天时地利与人和，“燕可伐欤？”曰：“可”。今日楼台鼎鼐，明年带砺山河。大家齐唱《大风歌》，不日四方来贺。"},
    {"title": "燕雁无心，太湖西畔随云去。", "content": "数峰清苦。商略黄昏雨。 第四桥边，拟共天随住。今何许。凭阑怀古。残柳参差舞。"},
    {"title": "燕燕轻盈，莺莺娇软，分明又向华胥见。", "content": "夜长争得薄情知？春初早被相思染。别后书辞，别时针线，离魂暗逐郎行远。淮南皓月冷千山，冥冥归去无人管。"},
    {"title": "京洛风流绝代人。", "content": "因何风絮落溪津。笼鞋浅出鸦头袜，知是凌波缥缈身。 红乍笑，绿长嚬。与谁同度可怜春。鸳鸯独宿何曾惯，化作西楼一缕云。"},
    {"title": "余客武陵。", "content": "湖北宪治在焉：古城野水，乔木参天。余与二三友，日荡舟其间。薄荷花而饮，意象幽闲，不类人境。秋水且涸。荷叶出地寻丈，因列坐其下，上不见日。清风徐来，绿云自动。间于疏处，窥见"},
    {"title": "丙辰岁，与张功父会饮张达可之堂。", "content": "闻屋壁间蟋蟀有声，功父约予同赋，以授歌者。功父先成，辞甚美。予裴回末利花间，仰见秋月，顿起幽思，寻亦得此。蟋蟀，中都呼为促织，善斗。好事者或以三二十"},
    {"title": "淳熙丙申至日，予过维扬。", "content": "夜雪初霁，荠麦弥望。入其城，则四顾萧条，寒水自碧，暮色渐起，戍角悲吟。予怀怆然，感慨今昔，因自度此曲。千岩老人以为有《黍离》之悲也。淮左名都，竹西佳处，解鞍"},
    {"title": "余颇喜自制曲。", "content": "初率意为长短句，然后协以律，故前后阕多不同。桓大司马云：“昔年种柳，依依汉南。今看摇落，凄怆江潭：树犹如此，人何以堪？”此语余深爱之。渐吹尽，枝头香絮，是处人家，绿深"},
    {"title": "辛亥之冬，余载雪诣石湖。", "content": "止既月，授简索句，且征新声，作此两曲，石湖把玩不已，使工妓隶习之，音节谐婉，乃名之曰《暗香》《疏影》。旧时月色，算几番照我，梅边吹笛？唤起玉人，不管清寒与攀"},
    {"title": "辛亥之冬，余载雪诣石湖。", "content": "止既月，授简索句，且征新声，作此两曲，石湖把玩不已，使工妓隶习之，音节谐婉，乃名之曰《暗香》、《疏影》。苔枝缀玉，有翠禽小小，枝上同宿。客里相逢，篱角黄昏，"},
    {"title": "一春长费买花钱，日日醉湖边。", "content": "玉骢惯识西湖路，骄嘶过、沽酒楼前。红杏香中箫鼓，绿杨影里秋千。(湖边 一作：花边)暖风十里丽人天，花压鬓云偏。画船载取春归去，馀情寄、湖水湖烟。明日重扶"},
    {"title": "袖剑飞吟。", "content": "洞庭青草，秋水深深。万顷波光，岳阳楼上，一快披襟。不须携酒登临。问有酒、何人共斟？变尽人间，君山一点，自古如今。"},
    {"title": "莎衫筠笠。", "content": "正是村村农务急。绿水千畦，惭愧秧针出得齐。风斜雨细。麦欲黄时寒又至。馌妇耕夫，画作今年稔岁图。"},
    {"title": "过春社了，度帘幕中间，去年尘冷。", "content": "差池欲住，试入旧巢相并。还相雕梁藻井。又软语、商量不定。飘然快拂花梢，翠尾分开红影。 芳径。芹泥雨润。爱贴地争飞，竞夸轻俊。红楼归晚，看足柳昏花暝。"},
    {"title": "做冷欺花，将烟困柳，千里偷催春暮。", "content": "尽日冥迷，愁里欲飞还住。惊粉重、蝶宿西园，喜泥润、燕归南浦。最妨它、佳约风流，钿车不到杜陵路。 沉沉江上望极，还被春潮晚急，难寻官渡。隐约遥峰，和"},
    {"title": "画楼帘幕卷新晴。", "content": "掩银屏，晓寒轻。坠粉飘香，日日唤愁生。暗数十年湖上路，能几度，著娉婷？ 年华空自感飘零。拥春酲，对谁醒？天阔云闲，无处觅箫声。载酒买花年少事，浑不似，旧心情。"},
    {"title": "春讯飞琼管。", "content": "风日薄、度墙啼鸟声乱。江城次第，笙歌翠合，绮罗香暖。溶溶涧渌冰泮。醉梦里、年华暗换。料黛眉重锁隋堤，芳心还动梁苑。 新来雁阔云音，鸾分鉴影，无计重见。啼春细雨，笼愁澹月"},
    {"title": "莫上玉楼看。", "content": "花雨斑斑。四垂罗幕护朝寒。燕子不知人去也，飞认阑干。 回首几关山。后会应难。相逢祗有梦魂间，可奈梦随春漏短，不到江南。"},
    {"title": "寒江夜宿。", "content": "长啸江之曲。水底鱼龙惊动，风卷地、浪翻屋。 诗情吟未足。酒兴断还续。草草兴亡休问，功名泪、欲盈掬。"},
    {"title": "春风只在园西畔，荠菜花繁胡蝶乱。", "content": "冰池晴绿照还空，香径落红吹已断。 意长翻恨游丝短，尽日相思罗带缓。宝奁明月不欺人，明日归来君试看。"},
    {"title": "一卷阴符，二石硬弓，百斤宝刀。", "content": "更玉花骢喷，鸣鞭电抹，乌丝阑展，醉墨龙跳。牛角书生，虬髯豪客，谈笑皆堪折简招。依稀记，曾请缨系粤，草檄征辽。 当年目视云霄。谁信道凄凉今折腰。怅燕然未"},
    {"title": "寒相催。", "content": "暖相催。催了开时催谢时。丁宁花放迟。 角声吹。笛声吹。吹了南枝吹北枝。明朝成雪飞。"},
    {"title": "北望神州路。", "content": "试平章、这场公事，怎生分付。记得太行山百万，曾入宗爷驾驭。今把作、握蛇骑虎。君去京东豪杰喜，想投戈、下拜真吾父。谈笑里，定齐鲁。 两河萧瑟惟狐兔。问当年、祖生去后，有人"},
    {"title": "湛湛长空黑。", "content": "更那堪、斜风细雨，乱愁如织。老眼平生空四海，赖有高楼百尺。看浩荡、千崖秋色。白发书生神州泪，尽凄凉、不向牛山滴。追往事，去无迹。 少年自负凌云笔。到而今、春华落尽，满怀"},
    {"title": "年年跃马长安市。", "content": "客舍似家家似寄。青钱换酒日无何，红烛呼卢宵不寐。 易挑锦妇机中字。难得玉人心下事。男儿西北有神州，莫滴水西桥畔泪。"},
    {"title": "片片蝶衣轻，点点猩红小。", "content": "道是天公不惜花，百种千般巧。 朝见树头繁，暮见枝头少。道是天公果惜花，雨洗风吹了。"},
    {"title": "一片春愁待酒浇。", "content": "江上舟摇，楼上帘招。秋娘渡与泰娘桥，风又飘飘，雨又萧萧。（渡 一作：度）何日归家洗客袍？银字笙调，心字香烧。流光容易把人抛，红了樱桃，绿了芭蕉。"},
    {"title": "少年听雨歌楼上，红烛昏罗帐。", "content": "壮年听雨客舟中，江阔云低、断雁叫西风。 而今听雨僧庐下，鬓已星星也。悲欢离合总无情，一任阶前、点滴到天明。"},
    {"title": "红玉阶前，问何事、翩然引去。", "content": "湖海上、一汀鸥鹭，半帆烟雨。报国无门空自怨，济时有策从谁吐。过垂虹亭下，系扁舟，鲈堪煮。 拚一醉，留君住。歌一曲，送君路。遍江南江北，欲归何处。世事悠悠"},
    {"title": "家园十亩屋头边。", "content": "正春妍，酿花天。杨柳多情，拂拂带轻烟。别馆闲亭随分有，时策杖，小盘旋。采山钓水美而鲜。饮中仙，醉中禅。闲处光阴，赢得日高眠。一品高官人道好，多少事，碎心田。"},
    {"title": "壶山居士，未老心先懒。", "content": "爱学道人家，办竹几、蒲团茗碗。青山可买，小结屋三间，开一径，俯清溪，修竹栽教满。客来便请，随分家常饭。若肯小留连，更薄酒，三杯两盏，吟诗度曲，风月任招呼。身外"},
    {"title": "花过雨，又是一番红素。", "content": "燕子归来愁不语，旧巢无觅处。谁在玉关劳苦？谁在玉楼歌舞？若使胡尘吹得去，东风侯万户。"},
    {"title": "年年社日停针线。", "content": "怎忍见、双飞燕。今日江城春已半。一身犹在，乱山深处，寂寞溪桥畔。春衫著破谁针线。点点行行泪痕满。落日解鞍芳草岸。花无人戴，酒无人劝，醉也无人管。"},
    {"title": "近清明。", "content": "翠禽枝上消魂。可惜一片清歌，都付与黄昏。欲共柳花低诉，怕柳花轻薄，不解伤春。念楚乡旅宿，柔情别绪，谁与温存。 空樽夜泣，青山不语，残照当门。翠玉楼前，惟是有、一波湘水，摇荡"},
    {"title": "花深深，柳阴阴。", "content": "度柳穿花觅信音，君心负妾心。怨鸣琴，恨孤衾。钿誓钗盟何处寻？当初谁料今！"},
    {"title": "秋雨一何碧，山色倚晴空。", "content": "江南江北愁思，分付酒螺红。芦叶蓬舟千重，菰菜莼羹一梦，无语寄归鸿。醉眼渺河洛，遗恨夕阳中。 苹洲外，山欲暝，敛眉峰。人间俯仰陈迹，叹息两仙翁。不见当时杨柳，"},
    {"title": "门隔花深梦旧游。", "content": "夕阳无语燕归愁。玉纤香动小帘钩。 落絮无声春堕泪，行云有影月含羞。东风临夜冷于秋。"},
    {"title": "听风听雨过清明。", "content": "愁草瘗花铭。楼前绿暗分携路，一丝柳、一寸柔情。料峭春寒中酒，交加晓梦啼莺。 西园日日扫林亭。依旧赏新晴。黄蜂频扑秋千索，有当时、纤手香凝。惆怅双鸳不到，幽阶一夜苔生"},
    {"title": "残寒正欺病酒，掩沉香绣户。", "content": "燕来晚、飞入西城，似说春事迟暮。画船载、清明过却，晴烟冉冉吴宫树。念羁情、游荡随风，化为轻絮。　　十载西湖，傍柳系马，趁娇尘软雾。溯红渐、招入仙溪，锦儿偷"},
    {"title": "渺空烟四远，是何年、青天坠长星？幻苍崖云树，名娃金屋，残霸宫城。", "content": "箭径酸风射眼，腻水染花腥。时靸双鸳响，廊叶秋声。宫里吴王沉醉，倩五湖倦客，独钓醒醒。问苍波无语，华发奈山青。水涵空、"},
    {"title": "何处合成愁。", "content": "离人心上秋。纵芭蕉不雨也飕飕。都道晚凉天气好，有明月、怕登楼。 年事梦中休。花空烟水流。燕辞归、客尚淹留。垂柳不萦裙带住。漫长是、系行舟。"},
    {"title": "珠帘寂寂。", "content": "愁背银缸泣。记得少年初选入。三十六宫第一。 当年掌上承恩。而今冷落长门。又是羊车过也，月明花落黄昏。"},
    {"title": "一勺西湖水。", "content": "渡江来，百年歌舞，百年酣醉。回首洛阳花石尽，烟渺黍离之地。更不复、新亭堕泪。簇乐红妆摇画舫，问中流、击楫何人是？千古恨，几时洗？(花石尽 一作：花世界)余生自负澄清志。"},
    {"title": "天上低昂似旧，人间儿女成狂。", "content": "夜来处处试新妆。却是人间天上。 不觉新凉似水，相思两鬓如霜。梦从海底跨枯桑。阅尽银河风浪。"},
    {"title": "送春去。", "content": "春去人间无路。秋千外，芳草连天，谁遣风沙暗南浦。依依甚意绪。漫忆海门飞絮。乱鸦过，斗转城荒，不见来时试灯处。 春去。最谁苦。但箭雁沉边，梁燕无主。杜鹃声里长门暮。想玉树凋土"},
    {"title": "太液芙蓉，浑不似、旧时颜色。", "content": " 曾记得、春风雨露，玉楼金阙。名播兰馨妃后里，晕潮莲脸君王侧。忽一声、鼙鼓揭天来，繁华歇。龙虎散，风云灭。千古恨，凭谁说。对山河百二，泪盈襟血。客馆夜惊"},
    {"title": "辛卯岁，沈尧道同余北归，各处杭、越。", "content": "逾岁，尧道来问寂寞，语笑数日。又复别去。赋此曲，并寄赵学舟。记玉关踏雪事清游，寒气脆貂裘。傍枯林古道，长河饮马，此意悠悠。短梦依然江表，老泪洒西"},
    {"title": "候蛩凄断，人语西风岸。", "content": "月落沙平江似练，望尽芦花无雁。暗教愁损兰成，可怜夜夜关情。只有一枝梧叶，不知多少秋声！"},
    {"title": "日出而作，日入而息。", "content": "凿井而饮，耕田而食。帝力于我何有哉！"},
    {"title": "关关雎鸠，在河之洲。", "content": "窈窕淑女，君子好逑。参差荇菜，左右流之。窈窕淑女，寤寐求之。求之不得，寤寐思服。悠哉悠哉，辗转反侧。参差荇菜，左右采之。窈窕淑女，琴瑟友之。参差荇菜，左右芼之。"},
    {"title": "投我以木瓜，报之以琼琚。", "content": "匪报也，永以为好也！投我以木桃，报之以琼瑶。匪报也，永以为好也！投我以木李，报之以琼玖。匪报也，永以为好也！"},
    {"title": "桃之夭夭，灼灼其华。", "content": "之子于归，宜其室家。桃之夭夭，有蕡其实。之子于归，宜其家室。桃之夭夭，其叶蓁蓁。之子于归，宜其家人。"},
    {"title": "蒹葭苍苍，白露为霜。", "content": "所谓伊人，在水一方。溯洄从之，道阻且长。溯游从之，宛在水中央。蒹葭萋萋，白露未晞。所谓伊人，在水之湄。溯洄从之，道阻且跻。溯游从之，宛在水中坻。蒹葭采采，白露未"},
    {"title": "岂曰无衣？七兮。", "content": "不如子之衣，安且吉兮。岂曰无衣？六兮。不如子之衣，安且燠兮。"},
    {"title": "谁谓河广？一苇杭之。", "content": "谁谓宋远？跂予望之。谁谓河广？曾不容刀。谁谓宋远？曾不崇朝。"},
    {"title": "采薇采薇，薇亦作止。", "content": "曰归曰归，岁亦莫止。 靡室靡家，猃狁之故。不遑启居，猃狁之故。采薇采薇，薇亦柔止。曰归曰归，心亦忧止。 忧心烈烈，载饥载渴。我戍未定，靡使归聘。采薇采薇，薇亦刚"},
    {"title": "硕鼠硕鼠，无食我黍！三岁贯女，莫我肯顾。", "content": "逝将去女，适彼乐土。乐土乐土，爰得我所。硕鼠硕鼠，无食我麦！三岁贯女，莫我肯德。逝将去女，适彼乐国。乐国乐国，爰得我直。硕鼠硕鼠，无食我苗！"},
    {"title": "坎坎伐檀兮，置之河之干兮。", "content": "河水清且涟猗。不稼不穑，胡取禾三百廛兮？不狩不猎，胡瞻尔庭有县貆兮？彼君子兮，不素餐兮！(置 一作 寘)坎坎伐辐兮，置之河之侧兮。河水清且直猗。不稼不穑，"},
    {"title": "相鼠有皮，人而无仪！", "content": "人而无仪，不死何为？相鼠有齿，人而无止！人而无止，不死何俟？相鼠有体，人而无礼！人而无礼，胡不遄死？"},
    {"title": "风萧萧兮易水寒，壮士一去兮不复还。", "content": "(复还 一作：复反)探虎穴兮入蛟宫，仰天呼气兮成白虹。(此句疑为后人补作)"},
    {"title": "力拔山兮气盖世。", "content": "时不利兮骓不逝。骓不逝兮可奈何！虞兮虞兮奈若何！"},
    {"title": "大风起兮云飞扬，威加海内兮归故乡，安得猛士兮守四方！", "content": ""},
    {"title": "秋风起兮白云飞，草木黄落兮雁南归。", "content": "兰有秀兮菊有芳，怀佳人兮不能忘。泛楼船兮济汾河，横中流兮扬素波。箫鼓鸣兮发棹歌，欢乐极兮哀情多。少壮几时兮奈老何！"},
    {"title": "北方有佳人，绝世而独立。", "content": "一顾倾人城，再顾倾人国。宁不知倾城与倾国？佳人难再得。"},
    {"title": "上邪！我欲与君相知，长命无绝衰。", "content": "山无陵，江水为竭，冬雷震震，夏雨雪，天地合，乃敢与君绝。"},
    {"title": "江南可采莲，莲叶何田田。", "content": "鱼戏莲叶间。鱼戏莲叶东，鱼戏莲叶西，鱼戏莲叶南，鱼戏莲叶北。"},
    {"title": "青青园中葵，朝露待日晞。", "content": "阳春布德泽，万物生光辉。常恐秋节至，焜黄华叶衰。百川东到海，何时复西归？少壮不努力，老大徒伤悲！"},
    {"title": "秋风萧萧愁杀人，出亦愁，入亦愁。", "content": "座中何人，谁不怀忧？令我白头。胡地多飚风，树木何修修。离家日趋远，衣带日趋缓。心思不能言，肠中车轮转。"},
    {"title": "十五从军征，八十始得归。", "content": "道逢乡里人：“家中有阿谁？”“遥看是君家，松柏冢累累。”(遥看 一作：遥望)兔从狗窦入，雉从梁上飞。中庭生旅谷，井上生旅葵。舂谷持作饭，采葵持作羹。羹饭一时"},
    {"title": "明月何皎皎，照我罗床帏。", "content": "忧愁不能寐，揽衣起徘徊。客行虽云乐，不如早旋归。出户独彷徨，愁思当告谁！引领还入房，泪下沾裳衣。"},
    {"title": "东城高且长，逶迤自相属。", "content": "回风动地起，秋草萋已绿。四时更变化，岁暮一何速！晨风怀苦心，蟋蟀伤局促。荡涤放情志，何为自结束！燕赵多佳人，美者颜如玉。被服罗裳衣，当户理清曲。音响一何悲！"},
    {"title": "行行重行行，与君生别离。", "content": "相去万余里，各在天一涯。道路阻且长，会面安可知？(知 一作：期)胡马依北风，越鸟巢南枝。相去日已远，衣带日已缓。浮云蔽白日，游子不顾反。思君令人老，岁月忽已"},
    {"title": "涉江采芙蓉，兰泽多芳草。", "content": "采之欲遗谁？所思在远道。还顾望旧乡，长路漫浩浩。同心而离居，忧伤以终老。"},
    {"title": "迢迢牵牛星，皎皎河汉女。", "content": "纤纤擢素手，札札弄机杼。终日不成章，泣涕零如雨。河汉清且浅，相去复几许。盈盈一水间，脉脉不得语。"},
    {"title": "回车驾言迈，悠悠涉长道。", "content": "四顾何茫茫，东风摇百草。所遇无故物，焉得不速老。盛衰各有时，立身苦不早。人生非金石，岂能长寿考？奄忽随物化，荣名以为宝。"},
    {"title": "客从远方来，遗我一端绮。", "content": "相去万余里，故人心尚尔。文采双鸳鸯，裁为合欢被。著以长相思，缘以结不解。以胶投漆中，谁能别离此？"},
    {"title": "凛凛岁云暮，蝼蛄夕鸣悲。", "content": "凉风率已厉，游子寒无衣。锦衾遗洛浦，同袍与我违。独宿累长夜，梦想见容辉。良人惟古欢，枉驾惠前绥。愿得常巧笑，携手同车归。既来不须臾，又不处重闱。亮无晨风翼，"},
    {"title": "举秀才，不知书。", "content": "察孝廉，父别居。寒素清白浊如泥，高第良将怯如鸡。(如鸡 一作：如黾)"},
    {"title": "神龟虽寿，犹有竟时；腾蛇乘雾，终为土灰。", "content": "(腾 一作：螣)老骥伏枥，志在千里；烈士暮年，壮心不已。盈缩之期，不但在天；养怡之福，可得永年。幸甚至哉，歌以咏志。"},
    {"title": "关东有义士，兴兵讨群凶。", "content": "初期会盟津，乃心在咸阳。军合力不齐，踌躇而雁行。势利使人争，嗣还自相戕。淮南弟称号，刻玺于北方。铠甲生虮虱，万姓以死亡。白骨露于野，千里无鸡鸣。生民百遗一，"},
    {"title": "东临碣石，以观沧海。", "content": "水何澹澹，山岛竦峙。树木丛生，百草丰茂。秋风萧瑟，洪波涌起。日月之行，若出其中；星汉灿烂，若出其里。幸甚至哉，歌以咏志。"},
    {"title": "对酒当歌，人生几何！譬如朝露，去日苦多。", "content": "慨当以慷，忧思难忘。何以解忧？唯有杜康。(唯 一作：惟)青青子衿，悠悠我心。但为君故，沉吟至今。呦呦鹿鸣，食野之苹。我有嘉宾，鼓瑟吹笙。明明"},
    {"title": "亭亭山上松，瑟瑟谷中风。", "content": "风声一何盛，松枝一何劲！冰霜正惨凄，终岁常端正。岂不罹凝寒？松柏有本性。"},
    {"title": "沉阴结愁忧，愁忧为谁兴？念与君相别，各在天一方。", "content": "良会未有期，中心摧且伤。不聊忧餐食，慊慊常饥空。端坐而无为，仿佛君容光。峨峨高山首，悠悠万里道。君去日已远，郁结令人老。人生一世间，"},
    {"title": "秋风萧瑟天气凉，草木摇落露为霜，群燕辞归鹄南翔。", "content": "(鹄南翔 一作：雁南翔)念君客游思断肠，慊慊思归恋故乡，何为淹留寄他方。(思断肠 一作：多断肠；何为 一作：君何）贱妾茕茕守空房，忧"},
    {"title": "白马饰金羁，连翩西北驰。", "content": "借问谁家子，幽并游侠儿。 少小去乡邑，扬声沙漠垂。宿昔秉良弓，楛矢何参差。控弦破左的，右发摧月支。仰手接飞猱，俯身散马蹄。狡捷过猴猿，勇剽若豹螭。边城多警急"},
    {"title": "煮豆持作羹，漉菽以为汁。", "content": "(菽 一作：豉)萁在釜下燃，豆在釜中泣。本自同根生，相煎何太急？(版本一)(煮豆燃豆萁，豆在釜中泣。本是同根生，相煎何太急？版本二)"},
    {"title": "南国有佳人，容华若桃李。", "content": "朝游江北岸，夕宿潇湘沚。时俗薄朱颜，谁为发皓齿？俯仰岁将暮，荣耀难久恃。"},
    {"title": "西京乱无象，豺虎方遘患。", "content": "复弃中国去，委身适荆蛮。(委身 一作：远身)亲戚对我悲，朋友相追攀。出门无所见，白骨蔽平原。路有饥妇人，抱子弃草间。顾闻号泣声，挥涕独不还。未知身死处，何能"},
    {"title": "息徒兰圃，秣马华山。", "content": "流磻平皋，垂纶长川。目送归鸿，手挥五弦。俯仰自得，游心太玄。嘉彼钓叟，得鱼忘筌。郢人逝矣，谁与尽言？"},
    {"title": "夜中不能寐，起坐弹鸣琴。", "content": "薄帷鉴明月，清风吹我襟。孤鸿号外野，翔鸟鸣北林。(翔鸟 一作：朔鸟)徘徊将何见？忧思独伤心。"},
    {"title": "宁饮建业水，不食武昌鱼。", "content": "宁还建业死，不止武昌居。"},
    {"title": "郁郁涧底松，离离山上苗。", "content": "以彼径寸茎，荫此百尺条。世胄蹑高位，英俊沉下僚。地势使之然，由来非一朝。金张藉旧业，七叶珥汉貂。冯公岂不伟，白首不见招。"},
    {"title": "秋风起兮木叶飞，吴江水兮鲈正肥。", "content": "三千里兮家未归，恨难禁兮仰天悲。"},
    {"title": "少无适俗韵，性本爱丘山。", "content": "误落尘网中，一去三十年。(误落 一作：误入)羁鸟恋旧林，池鱼思故渊。开荒南野际，守拙归园田。方宅十余亩，草屋八九间。榆柳荫后檐，桃李罗堂前。暧暧远人村，依依"},
    {"title": "种豆南山下，草盛豆苗稀。", "content": "晨兴理荒秽，带月荷锄归。道狭草木长，夕露沾我衣。衣沾不足惜，但使愿无违。"},
    {"title": "结庐在人境，而无车马喧。", "content": "问君何能尔？心远地自偏。采菊东篱下，悠然见南山。山气日夕佳，飞鸟相与还。此中有真意，欲辨已忘言。"},
    {"title": "燕丹善养士，志在报强嬴。", "content": "招集百夫良，岁暮得荆卿。君子死知己，提剑出燕京；素骥鸣广陌，慷慨送我行。雄发指危冠，猛气冲长缨。饮饯易水上，四座列群英。渐离击悲筑，宋意唱高声。萧萧哀风逝，"},
    {"title": "孟夏草木长，绕屋树扶疏。", "content": " 众鸟欣有托，吾亦爱吾庐。 既耕亦已种，时还读我书。 穷巷隔深辙，颇回故人车。 欢然酌春酒，摘我园中蔬。(欢然 一作：欢言)微雨从东来，好风与之俱。 泛览周"},
    {"title": "精卫衔微木，将以填沧海。", "content": "刑天舞干戚，猛志固常在。同物既无虑，化去不复悔。徒设在昔心，良辰讵可待。(辰 一作：晨)"},
    {"title": "人生无根蒂，飘如陌上尘。", "content": "分散逐风转，此已非常身。落地为兄弟，何必骨肉亲！得欢当作乐，斗酒聚比邻。盛年不重来，一日难再晨。及时当勉励，岁月不待人。"},
    {"title": "古人云此水，一歃怀千金。", "content": "试使夷齐饮，终当不易心。"},
    {"title": "江南倦历览，江北旷周旋。", "content": "怀新道转迥，寻异景不延。乱流趋正绝，孤屿媚中川。云日相辉映，空水共澄鲜。表灵物莫赏，蕴真谁为传。想象昆山姿，缅邈区中缘。始信安期术，得尽养生年。"},
    {"title": "泻水置平地，各自东西南北流。", "content": "人生亦有命，安能行叹复坐愁？酌酒以自宽，举杯断绝歌路难。心非木石岂无感，吞声踯躅不敢言。"},
    {"title": "对案不能食，拔剑击柱长叹息。", "content": "丈夫生世会几时？安能蹀躞垂羽翼！弃置罢官去，还家自休息。朝出与亲辞，暮还在亲侧。(在 一作：往)弄儿床前戏，看妇机中织。自古圣贤尽贫贱，何况我辈孤且直！"},
    {"title": "中庭杂树多，偏为梅咨嗟。", "content": "问君何独然？念其霜中能作花，露中能作实。摇荡春风媚春日，念尔零落逐寒风，徒有霜华无霜质。(寒风 一作：风飚)"},
    {"title": "折花逢驿使，寄与陇头人。", "content": "(折花 一作：折梅)江南无所有，聊赠一枝春。"},
    {"title": "灞涘望长安，河阳视京县。", "content": "白日丽飞甍，参差皆可见。馀霞散成绮，澄江静如练。喧鸟覆春洲，杂英满芳甸。去矣方滞淫，怀哉罢欢宴。佳期怅何许，泪下如流霰。有情知望乡，谁能鬒不变？"},
    {"title": "绿草蔓如丝，杂树红英发。", "content": "无论君不归，君归芳已歇。"},
    {"title": "江干远树浮，天末孤烟起。", "content": "江天自如合，烟树还相似。沧流未可源，高帆去何已。"},
    {"title": "郎作十里行，侬作九里送。", "content": "拔侬头上钗，与郎资路用。有信数寄书，无信心相忆。莫作瓶落井，一去无消息。大艑珂峨头，何处发扬州。借问艑上郎，见侬所欢不？初发扬州时，船出平津泊。五两如竹林，"},
    {"title": "河汉纵且横，北斗横复直。", "content": "星汉空如此，宁知心有忆？孤灯暧不明，寒机晓犹织。零泪向谁道，鸡鸣徒叹息。"},
    {"title": "兔园标物序，惊时最是梅。", "content": "衔霜当路发，映雪拟寒开。枝横却月观，花绕凌风台。朝洒长门泣，夕驻临邛杯。应知早飘落，故逐上春来。"},
    {"title": "柳黄未吐叶，水绿半含苔。", "content": "春色边城动，客思故乡来。"},
    {"title": "山际见来烟，竹中窥落日。", "content": "鸟向檐上飞，云从窗里出。"},
    {"title": "山中何所有，岭上多白云。", "content": "只可自怡悦，不堪持赠君。(赠 一作：寄)"},
    {"title": "艅艎何泛泛，空水共悠悠。", "content": "阴霞生远岫，阳景逐回流。蝉噪林逾静，鸟鸣山更幽。此地动归念，长年悲倦游。"},
    {"title": "建平督邮道，鱼复永安宫。", "content": "若奏巴渝曲，时当君思中。"},
    {"title": "巫山七百里，巴水三回曲。", "content": "笛声下复高，猿啼断还续。"},
    {"title": "大江一浩荡，离悲足几重。", "content": "潮落犹如盖，云昏不作峰。远戍唯闻鼓，寒山但见松。九十方称半，归途讵有踪。"},
    {"title": "关山三五月，客子忆秦川。", "content": "思妇高楼上，当窗应未眠。星旗映疏勒，云阵上祁连。战气今如此，从军复几年。"},
    {"title": "白云满鄣来，黄尘暗天起。", "content": "关山四面绝，故乡几千里。"},
    {"title": "玉关道路远，金陵信使疏。", "content": "独下千行泪，开君万里书。"},
    {"title": "春蚕不应老，昼夜常怀丝。", "content": "何惜微躯尽，缠绵自有时。"},
    {"title": "陇头流水，流离山下。", "content": "念吾一身，飘然旷野。朝发欣城，暮宿陇头。寒不能语，舌卷入喉。陇头流水，鸣声呜咽。遥望秦川，心肝断绝。"},
    {"title": "上马不捉鞭，反折杨柳枝。", "content": "蹀座吹长笛，愁杀行客儿。腹中愁不乐，愿作郎马鞭。出入擐郎臂，蹀座郎膝边。放马两泉泽，忘不著连羁。担鞍逐马走，何见得马骑。遥看孟津河，杨柳郁婆娑。我是虏家儿，"},
    {"title": "敕勒川，阴山下。", "content": "天似穹庐，笼盖四野。天苍苍，野茫茫，风吹草低见牛羊。"},
    {"title": "心逐南云逝，形随北雁来。", "content": "故乡篱下菊，今日几花开。"},
    {"title": "入春才七日，离家已二年。", "content": "人归落雁后，思发在花前。"},
    {"title": "可惜庭中树，移根逐汉臣。", "content": "只为来时晚，花开不及春。"},
    {"title": "鸣骹直上一千尺，天静无风声更干。", "content": "碧眼胡儿三百骑，尽提金勒向云看。"},
    {"title": "亭亭画舸系春潭，直到行人酒半酣。", "content": "不管烟波与风雨，载将离恨过江南。"},
    {"title": "马穿山径菊初黄，信马悠悠野兴长。", "content": "万壑有声含晚籁，数峰无语立斜阳。棠梨叶落胭脂色，荞麦花开白雪香。何事吟馀忽惆怅，村桥原树似吾乡。(余 一作：馀)"},
    {"title": "两株桃杏映篱斜，妆点商州副使家。", "content": "何事春风容不得？和莺吹折数枝花。"},
    {"title": "晓带轻烟间杏花，晚凝深翠拂平沙。", "content": "长条别有风流处，密映钱塘苏小家。"},
    {"title": "岸阔樯稀波渺茫，独凭危槛思何长。", "content": "萧萧远树疏林外，一半秋山带夕阳。"},
    {"title": "鲍老当筵笑郭郎，笑他舞袖太郎当。", "content": "若教鲍老当筵舞，转更郎当舞袖长。"},
    {"title": "众芳摇落独暄妍，占尽风情向小园。", "content": "疏影横斜水清浅，暗香浮动月黄昏。霜禽欲下先偷眼，粉蝶如知合断魂。幸有微吟可相狎，不须檀板共金樽。剪绡零碎点酥乾，向背稀稠画亦难。日薄从甘春至晚，霜深"},
    {"title": "坠素翻红各自伤，青青烟雨忍相忘。", "content": "将飞更作回风舞，已落犹成半面妆。沧海客归珠有泪，章台人去骨遗香。可能无意传双蝶，尽付芳心与蜜房。"},
    {"title": "枕中云气千峰近，床底松声万壑哀。", "content": "要看银山拍天浪，开窗放入大江来。"},
    {"title": "行到东溪看水时，坐临孤屿发船迟。", "content": "野凫眠岸有闲意，老树着花无丑枝。短短蒲茸齐似剪，平平沙石净于筛。情虽不厌住不得，薄暮归来车马疲。"},
    {"title": "适与野情惬，千山高复低。", "content": "好峰随处改，幽径独行迷。霜落熊升树，林空鹿饮溪。人家在何许？云外一声鸡。"},
    {"title": "陶尽门前土，屋上无片瓦。", "content": "十指不沾泥，鳞鳞居大厦。"},
    {"title": "春云浓淡日微光，双阙重门耸建章。", "content": "不上楼来知几日，满城无算柳梢黄。"},
    {"title": "夜雨连明春水生，娇云浓暖弄阴晴。", "content": "帘虚日薄花竹静，时有乳鸠相对鸣。"},
    {"title": "别院深深夏席清，石榴开遍透帘明。", "content": "(夏席清 一作：夏簟清)树阴满地日当午，梦觉流莺时一声。"},
    {"title": "昨日入城市，归来泪满巾。", "content": "遍身罗绮者，不是养蚕人。"},
    {"title": "卧闻岳阳城里钟，系舟岳阳城下树。", "content": "正见空江明月来，云水苍茫失江路。夜深江月弄清辉，水上人歌月下归；一阕声长听不尽，轻舟短楫去如飞。"},
    {"title": "百啭千声随意移，山花红紫树高低。", "content": "始知锁向金笼听，不及林间自在啼。"},
    {"title": "春风疑不到天涯，二月山城未见花。", "content": "残雪压枝犹有橘，冻雷惊笋欲抽芽。夜闻归雁生乡思，病入新年感物华。曾是洛阳花下客，野芳虽晚不须嗟。"},
    {"title": "红树青山日欲斜，长郊草色绿无涯。", "content": "游人不管春将老，来往亭前踏落花。"},
    {"title": "花光浓烂柳轻明，酌酒花前送我行。", "content": "我亦且如常日醉，莫教弦管作离声。"},
    {"title": "人言落日是天涯，望极天涯不见家。", "content": "已恨碧山相阻隔，碧山还被暮云遮。"},
    {"title": "墙角数枝梅，凌寒独自开。", "content": "遥知不是雪，为有暗香来。"},
    {"title": "百战疲劳壮士哀，中原一败势难回。", "content": "江东子弟今虽在，肯与君王卷土来？"},
    {"title": "爆竹声中一岁除，春风送暖入屠苏。", "content": "千门万户曈曈日，总把新桃换旧符。"},
    {"title": "京口瓜洲一水间，钟山只隔数重山。", "content": "春风又绿江南岸，明月何时照我还。(又绿 一作：自绿)"},
    {"title": "飞来山上千寻塔，闻说鸡鸣见日升。", "content": "(飞来山 一作：飞来峰)不畏浮云遮望眼，自缘身在最高层。"},
    {"title": "金炉香烬漏声残，翦翦轻风阵阵寒。", "content": "春色恼人眠不得，月移花影上栏杆。"},
    {"title": "云淡风轻近午天，傍花随柳过前川。", "content": "时人不识余心乐，将谓偷闲学少年。(时人 一作：旁人)"},
    {"title": "青苔满地初晴后，绿树无人昼梦余。", "content": "唯有南风旧相识，偷开门户又翻书。"},
    {"title": "一雨池塘水面平，淡磨明镜照檐楹。", "content": "东风忽起垂杨舞，更作荷心万点声。"},
    {"title": "清风无力屠得热，落日着翅飞上山。", "content": "人固已惧江海竭，天岂不惜河汉干？昆仑之高有积雪，蓬莱之远常遗寒。不能手提天下往，何忍身去游其间？"},
    {"title": "三月残花落更开，小檐日日燕飞来。", "content": "子规夜半犹啼血，不信东风唤不回。"},
    {"title": "水绕陂田竹绕篱，榆钱落尽槿花稀。", "content": "夕阳牛背无人卧，带得寒鸦两两归。"},
    {"title": "乱条犹未变初黄，倚得东风势便狂。", "content": "解把飞花蒙日月，不知天地有清霜。"},
    {"title": "雨过横塘水满堤，乱山高下路东西。", "content": "一番桃李花开尽，惟有青青草色齐。"},
    {"title": "横看成岭侧成峰，远近高低各不同。", "content": "不识庐山真面目，只缘身在此山中。"},
    {"title": "竹外桃花三两枝，春江水暖鸭先知。", "content": "蒌蒿满地芦芽短，正是河豚欲上时。两两归鸿欲破群，依依还似北归人。遥知朔漠多风雪，更待江南半月春。"},
    {"title": "人生到处知何似，应似飞鸿踏雪泥。", "content": "泥上偶然留指爪，鸿飞那复计东西。老僧已死成新塔，坏壁无由见旧题。往日崎岖还记否，路长人困蹇驴嘶。"},
    {"title": "春宵一刻值千金，花有清香月有阴。", "content": "歌管楼台声细细，秋千院落夜沉沉。"},
    {"title": "水光潋滟晴方好，山色空蒙雨亦奇。", "content": "欲把西湖比西子，淡妆浓抹总相宜。"},
    {"title": "荷尽已无擎雨盖，菊残犹有傲霜枝。", "content": "一年好景君须记，最是橙黄橘绿时。(最是 一作：正是)"},
    {"title": "东风袅袅泛崇光，香雾空蒙月转廊。", "content": "只恐夜深花睡去，故烧高烛照红妆。"},
    {"title": "百里西风禾黍香，鸣泉落窦谷登场。", "content": "老牛粗了耕耘债，啮草坡头卧夕阳。"},
    {"title": "试说途中景，方知别后心。", "content": "行人日暮少，风雪乱山深。"},
    {"title": "骑牛远远过前村，短笛横吹隔陇闻。", "content": "(短笛横吹 一作：吹笛风斜)多少长安名利客，机关用尽不如君。"},
    {"title": "痴儿了却公家事，快阁东西倚晚晴。", "content": "落木千山天远大，澄江一道月分明。朱弦已为佳人绝，青眼聊因美酒横。万里归船弄长笛，此心吾与白鸥盟。"},
    {"title": "四顾山光接水光，凭栏十里芰荷香。", "content": "清风明月无人管，并作南楼一味凉。"},
    {"title": "投荒万死鬓毛斑，生入瞿塘滟滪关。", "content": "(生入 一作：生出)未到江南先一笑，岳阳楼上对君山。满川风雨独凭栏，绾结湘娥十二鬟。可惜不当湖水面，银山堆里看青山。"},
    {"title": "风蒲猎猎弄清柔，欲立蜻蜓不自由。", "content": "五月临平山下路，藕花无数满汀洲。"},
    {"title": "阴阴溪曲绿交加，小雨翻萍上浅沙。", "content": "鹅鸭不知春去尽，争随流水趁桃花。"},
    {"title": "如丝苣甲饤春盘，韭叶金黄雪未干。", "content": "旅饭二年无此味，故园千里几时还。异方时节三巵酒，残岁风烟一惨颜。曾奉龙旗典邦礼，岁穷祠祀少休闲。"},
    {"title": "庭户无人秋月明，夜霜欲落气先清。", "content": "梧桐真不甘衰谢，数叶迎风尚有声。"},
    {"title": "携杖来追柳外凉，画桥南畔倚胡床。", "content": "月明船笛参差起，风定池莲自在香。"},
    {"title": "一夕轻雷落万丝，霁光浮瓦碧参差。", "content": "有情芍药含春泪，无力蔷薇卧晓枝。"},
    {"title": "天寒水鸟自相依，十百为群戏落晖。", "content": "过尽行人都不起，忽闻水响一齐飞。"},
    {"title": "断墙著雨蜗成字，老屋无僧燕作家。", "content": "剩欲出门追语笑，却嫌归鬓著尘沙。风翻蛛网开三面，雷动蜂窠趁两衙。屡失南邻春事约，只今容有未开花。"},
    {"title": "时三子已归自外家去远即相忘，归近不可忍。", "content": "儿女已在眼，眉目略不省。喜极不得语，泪尽方一哂。了知不是梦，忽忽心未稳。"},
    {"title": "双飞燕子几时回？夹岸桃花蘸水开。", "content": "春雨断桥人不渡，小舟撑出柳阴来。(渡 一作：度)"},
    {"title": "游子春衫已试单，桃花飞尽野梅酸。", "content": "怪来一夜蛙声歇，又作东风十日寒。"},
    {"title": "稍离烟瘴近湘潭，疾病衰颓已不堪。", "content": "儿女不知来避地，强言风物胜江南。"},
    {"title": "女子弄文诚可罪，那堪咏月更吟风。", "content": "磨穿铁砚非吾事，绣折金针却有功。闷无消遣只看诗，不见诗中话别离。添得情怀转萧索，始知伶俐不如痴。"},
    {"title": "连理枝头花正开，妒花风雨便相催。", "content": "愿教青帝常为主，莫遣纷纷点翠苔。"},
    {"title": "一春略无十日晴，处处浮云将雨行。", "content": "野田春水碧于镜，人影渡傍鸥不惊。桃花嫣然出篱笑，似开未开最有情。茅茨烟暝客衣湿，破梦午鸡啼一声。"},
    {"title": "辇毂繁华事可伤，师师垂老过湖湘。", "content": "缕衣檀板无颜色，一曲当时动帝王。"},
    {"title": "生当作人杰，死亦为鬼雄。", "content": "至今思项羽，不肯过江东。"},
    {"title": "苏秀道中，自七月二十五日夜大雨三日，秋苗以苏，喜而有作。", "content": "一夕骄阳转作霖，梦回凉冷润衣襟。不愁屋漏床床湿，且喜溪流岸岸深。千里稻花应秀色，五更桐叶最佳音。无田似我犹欣舞，何况田间望岁"},
    {"title": "梅子黄时日日晴，小溪泛尽却山行。", "content": "绿阴不减来时路，添得黄鹂四五声。"},
    {"title": "耕犁千亩实千箱，力尽筋疲谁复伤？但得众生皆得饱，不辞羸病卧残阳。", "content": ""},
    {"title": "飞花两岸照船红，百里榆堤半日风。", "content": "卧看满天云不动，不知云与我俱东。"},
    {"title": "天缺西南江面清，纤云不动小滩横。", "content": "墙头语鹊衣犹湿，楼外残雷气未平。尽取微凉供稳睡，急搜奇句报新晴。今宵绝胜无人共，卧看星河尽意明。"},
    {"title": "一自胡尘入汉关，十年伊洛路漫漫。", "content": "青墩溪畔龙钟客，独立东风看牡丹。"},
    {"title": "经年尘土满征衣，特特寻芳上翠微。", "content": "好水好山看不足，马蹄催趁月明归。"},
    {"title": "一担干柴古渡头，盘缠一日颇优游。", "content": "归来涧底磨刀斧，又作全家明日谋。"},
    {"title": "世味年来薄似纱，谁令骑马客京华。", "content": "小楼一夜听春雨，深巷明朝卖杏花。矮纸斜行闲作草，晴窗细乳戏分茶。素衣莫起风尘叹，犹及清明可到家。"},
    {"title": "黄金错刀白玉装，夜穿窗扉出光芒。", "content": "丈夫五十功未立，提刀独立顾八荒。京华结交尽奇士，意气相期共生死。千年史册耻无名，一片丹心报天子。尔来从军天汉滨，南山晓雪玉嶙峋。呜呼！楚虽三户能亡秦"},
    {"title": "衣上征尘杂酒痕，远游无处不消魂。", "content": "此身合是诗人未？细雨骑驴入剑门。"},
    {"title": "闻道梅花坼晓风，雪堆遍满四山中。", "content": "何方可化身千亿，一树梅前一放翁。(梅前 一作：梅花)"},
    {"title": "死去元知万事空，但悲不见九州同。", "content": "王师北定中原日，家祭无忘告乃翁。"},
    {"title": "风卷江湖雨暗村，四山声作海涛翻。", "content": "溪柴火软蛮毡暖，我与狸奴不出门。僵卧孤村不自哀，尚思为国戍轮台。夜阑卧听风吹雨，铁马冰河入梦来。"},
    {"title": "早岁那知世事艰，中原北望气如山。", "content": "楼船夜雪瓜洲渡，铁马秋风大散关。塞上长城空自许，镜中衰鬓已先斑。出师一表真名世，千载谁堪伯仲间！"},
    {"title": "病骨支离纱帽宽，孤臣万里客江干。", "content": "位卑未敢忘忧国，事定犹须待阖棺。天地神灵扶庙社，京华父老望和銮。出师一表通今古，夜半挑灯更细看。"},
    {"title": "迢迢天汉西南落，喔喔邻鸡一再鸣。", "content": "壮志病来消欲尽，出门搔首怆平生。三万里河东入海，五千仞岳上摩天。遗民泪尽胡尘里，南望王师又一年。"},
    {"title": "梅子金黄杏子肥，麦花雪白菜花稀。", "content": "日长篱落无人过，惟有蜻蜓蛱蝶飞。(惟 一作：唯)"},
    {"title": "南浦春来绿一川，石桥朱塔两依然。", "content": "年年送客横塘路，细雨垂杨系画船。"},
    {"title": "南望朱雀门，北望宣德楼，皆旧御路也。", "content": "州桥南北是天街，父老年年等驾回。忍泪失声询使者，几时真有六军来？"},
    {"title": "溪水将桥不复回，小舟犹倚短篙开。", "content": "交情得似山溪渡，不管风波去又来。"},
    {"title": "一叶渔船两小童，收篙停棹坐船中。", "content": "怪生无雨都张伞，不是遮头是使风。"},
    {"title": "两岸舟船各背驰，波痕交涉亦难为。", "content": "只余鸥鹭无拘管，北去南来自在飞。"},
    {"title": "泉眼无声惜细流，树阴照水爱晴柔。", "content": "(阴 一作：荫)小荷才露尖尖角，早有蜻蜓立上头。"},
    {"title": "毕竟西湖六月中，风光不与四时同。", "content": "接天莲叶无穷碧，映日荷花别样红。"},
    {"title": "篱落疏疏一径深，树头新绿未成阴。", "content": "(新绿 一作：花落)儿童急走追黄蝶，飞入菜花无处寻。"},
    {"title": "山外青山楼外楼，西湖歌舞几时休？暖风熏得游人醉，直把杭州作汴州。", "content": ""},
    {"title": "昨夜江边春水生，蒙冲巨舰一毛轻。", "content": "(蒙冲 一作：艨艟)向来枉费推移力，此日中流自在行。"},
    {"title": "胜日寻芳泗水滨，无边光景一时新。", "content": "等闲识得东风面，万紫千红总是春。"},
    {"title": "律回岁晚冰霜少，春到人间草木知。", "content": "便觉眼前生意满，东风吹水绿参差。"},
    {"title": "细草穿沙雪半销，吴宫烟冷水迢迢。", "content": "梅花竹里无人见，一夜吹香过石桥。美人台上昔欢娱，今日空台望五湖。残雪未融青草死，苦无麋鹿过姑苏。黄帽传呼睡不成，投篙细细激流冰。分明旧泊江南岸，舟尾"},
    {"title": "自作新词韵最娇，小红低唱我吹箫。", "content": "曲终过尽松陵路，回首烟波十四桥。"},
    {"title": "水满田畴稻叶齐，日光穿树晓烟低。", "content": "黄莺也爱新凉好，飞过青山影里啼。"},
    {"title": "黄梅时节家家雨，青草池塘处处蛙。", "content": "有约不来过夜半，闲敲棋子落灯花。"},
    {"title": "绿遍山原白满川，子规声里雨如烟。", "content": "乡村四月闲人少，才了蚕桑又插田。"},
    {"title": "江头落日照平沙，潮退渔船阁岸斜。", "content": "白鸟一双临水立，见人惊起入芦花。"},
    {"title": "小桃无主自开花，烟草茫茫带晚鸦。", "content": "几处败垣围故井，向来一一是人家。"},
    {"title": "应怜屐齿印苍苔，小扣柴扉久不开。", "content": "春色满园关不住，一枝红杏出墙来。"},
    {"title": "一片能教一断肠，可堪平砌更堆墙。", "content": "飘如迁客来过岭，坠似骚人去赴湘。乱点莓苔多莫数，偶粘衣袖久犹香。东风谬掌花权柄，却忌孤高不主张。"},
    {"title": "掷柳迁乔太有情，交交时作弄机声。", "content": "洛阳三月花如锦，多少工夫织得成。"},
    {"title": "乳鸭池塘水浅深，熟梅天气半阴晴。", "content": "(阴晴 一作：晴阴)东园载酒西园醉，摘尽枇杷一树金。"},
    {"title": "门外无人问落花，绿阴冉冉遍天涯。", "content": "林莺啼到无声处，青草池塘独听蛙。"},
    {"title": "古木阴中系短篷，杖藜扶我过桥东。", "content": "沾衣欲湿杏花雨，吹面不寒杨柳风。"},
    {"title": "辛苦遭逢起一经，干戈寥落四周星。", "content": "山河破碎风飘絮，身世浮沉雨打萍。惶恐滩头说惶恐，零丁洋里叹零丁。人生自古谁无死？留取丹心照汗青。"},
    {"title": "愁里高歌梁父吟，犹如金玉戛商音。", "content": "十年勾践亡吴计，七日包胥哭楚心。秋送新鸿哀破国，昼行饥虎齧空林。胸中有誓深于海，肯使神州竟陆沉？"},
    {"title": "花开不并百花丛，独立疏篱趣未穷。", "content": "宁可枝头抱香死，何曾吹落北风中。"},
    {"title": "寒夜客来茶当酒，竹炉汤沸火初红。", "content": "寻常一样窗前月，才有梅花便不同。"},
    {"title": "梅雪争春未肯降，骚人阁笔费评章。", "content": "梅须逊雪三分白，雪却输梅一段香。"},
    {"title": "十年无梦得还家，独立青峰野水涯。", "content": "天地寂寥山雨歇，几生修得到梅花？"},
    {"title": "月儿弯弯照九州，几家欢乐几家愁。", "content": "几家夫妇同罗帐，几个飘零在外头？"},
    {"title": "竹影和诗瘦，梅花入梦香。", "content": "可怜今夜月，不肯下西厢。"},
    {"title": "西北天低五顶高，茫茫松海露灵鳌。", "content": "太行直上犹千里，井底残山枉呼号。万壑千岩位置雄，偶从天巧见神功。湍溪已作风雷恶，更在云山气象中。山云吞吐翠微中，淡绿深青一万重。此景只应天上有，岂知"},
    {"title": "惨澹龙蛇日斗争，干戈直欲尽生灵。", "content": "高原水出山河改，战地风来草木腥。精卫有冤填瀚海，包胥无泪哭秦庭。并州豪杰知谁在，莫拟分军下井陉。万里荆襄入战尘，汴州门外即荆榛。蛟龙岂是池中物？虮虱"},
    {"title": "枝间新绿一重重， 小蕾深藏数点红。", "content": "爱惜芳心莫轻吐， 且教桃李闹春风。"},
    {"title": "一击车中胆气豪，祖龙社稷已惊摇。", "content": "如何十二金人外，犹有人间铁未销。"},
    {"title": "马蹄踏水乱明霞，醉袖迎风受落花。", "content": "怪见溪童出门望，鹊声先我到山家。"},
    {"title": "野店桃花红粉姿，陌头杨柳绿烟丝。", "content": "不因送客东城去，过却春光总不知。"},
    {"title": "客舟系缆柳阴旁，湖影侵篷夜气凉。", "content": " 万顷波光摇月碎，一天风露藕花香。"},
    {"title": "城雪初消荠菜生，角门深巷少人行。", "content": "柳梢听得黄鹂语，此是春来第一声。"},
    {"title": "何处它年寄此生，山中江上总关情。", "content": "无端绕屋长松树，尽把风声作雨声。"},
    {"title": "春草细还生，春雏养渐成。", "content": "茸茸毛色起，应解自呼名。"},
    {"title": "我家洗砚池头树，朵朵花开淡墨痕。", "content": "(我家 一作：吾家；朵朵 一作：个个)不要人夸好颜色，只留清气满乾坤。(好颜色 一作：颜色好)"},
    {"title": "花开红树乱莺啼，草长平湖白鹭飞。", "content": "风日晴和人意好，夕阳箫鼓几船归。"},
    {"title": "牛羊散漫落日下，野草生香乳酪甜。", "content": "卷地朔风沙似雪，家家行帐下毡帘。"},
    {"title": "江水三千里，家书十五行。", "content": "行行无别语，只道早还乡。"},
    {"title": "细雨茸茸湿楝花，南风树树熟枇杷。", "content": "徐行不记山深浅，一路莺啼送到家。"},
    {"title": "绿池芳草满晴波，春色都从雨里过。", "content": "知是人家花落尽，菜畦今日蝶来多。"},
    {"title": "渡水复渡水，看花还看花。", "content": "春风江上路，不觉到君家。"},
    {"title": "春风一夜到衡阳，楚水燕山万里长。", "content": "莫怪春来便归去，江南虽好是他乡。"},
    {"title": "岸蓼疏红水荇青，茨菰花白小如萍。", "content": "双鬟短袖惭人见，背立船头自采菱。"},
    {"title": "下床着新衣，初学小姑拜。", "content": "低头羞见人，双手结裙带。"},
    {"title": "形容不识识乡音，挑尽寒灯到夜深。", "content": "故旧凭君休更说，老怀容易便沾襟。"},
    {"title": "千锤万凿出深山，烈火焚烧若等闲。", "content": "(万凿 一作：万击)粉骨碎身浑不怕，要留清白在人间。(浑不怕 一作：全不怕)"},
    {"title": "碧水丹山映杖藜，夕阳犹在小桥西。", "content": "微吟不道惊溪鸟，飞入乱云深处啼。"},
    {"title": "莫将画竹论难易，刚道繁难简更难。", "content": "君看萧萧只数叶，满堂风雨不胜寒。"},
    {"title": "不炼金丹不坐禅，不为商贾不耕田。", "content": "闲来写就青山卖，不使人间造孽钱。"},
    {"title": "船板胡在兹，而我寝其上。", "content": "情知非江湖，梦寐亦风浪。"},
    {"title": "洞庭叶未下，潇湘秋欲生。", "content": "高斋今夜雨，独卧武昌城。重以桑梓念，凄其江汉情。不知天外雁，何事乐长征？"},
    {"title": "汉江明月照归人，万里秋风一叶身。", "content": "休把客衣轻浣濯，此中犹有帝京尘。"},
    {"title": "十二峰头秋草荒，冷烟寒月过瞿塘。", "content": "青枫江上孤舟客，不听猿声亦断肠。(猿声 一作：猿啼)"},
    {"title": "高田如楼梯，平田如棋局。", "content": "白鹭忽飞来，点破秧针绿。"},
    {"title": "暝色满西山，将军猎骑还。", "content": "隔河见烽火，骄虏夜临关。"},
    {"title": "白羽如霜出塞寒，胡烽不断接长安。", "content": "城头一片西山月，多少征人马上看。"},
    {"title": "浩气还太虚，丹心照千古。", "content": "生平未报国，留作忠魂补。"},
    {"title": "半生落魄已成翁，独立书斋啸晚风。", "content": "笔底明珠无处卖，闲抛闲掷野藤中。"},
    {"title": "南北驱驰报主情，江花边月笑平生。", "content": "(边月 一作：边草)一年三百六十日，多是横戈马上行。"},
    {"title": "今日复今日，今日何其少！今日又不为，此事何时了？人生百年几今日，今日不为真可惜！若言姑待明朝至，明朝又有明朝事。", "content": "为君聊赋今日诗，努力请从今日始。"},
    {"title": "心同流水净，身与白云轻。", "content": "寂寂深山暮，微闻钟磬声。"},
    {"title": "湘山晴色远微微，尽日江头独醉归。", "content": "不见两关传露布，尚闻三殿未垂衣。边筹自古无中下，朝论于今有是非。日暮平沙秋草乱，一双白鸟避人飞。"},
    {"title": "寂历秋江渔火稀，起看残月映林微。", "content": "波光水鸟惊犹宿，露冷流萤湿不飞。"},
    {"title": "并刀昨夜匣中鸣，燕赵悲歌最不平；易水潺湲云草碧，可怜无处送荆卿！", "content": ""},
    {"title": "复楚情何极，亡秦气未平。", "content": "雄风清角劲，落日大旗明。缟素酬家国，戈船决死生！胡笳千古恨，一片月临城。战苦难酬国，仇深敢忆家？一身存汉腊，满目尽胡沙。落月翻旗影，清霜冷剑花。六军浑散尽，"},
    {"title": "三年羁旅客，今日又南冠。", "content": "无限山河泪，谁言天地宽。(山河 一作：河山)已知泉路近，欲别故乡难。毅魄归来日，灵旗空际看。"},
    {"title": "朝求升，暮求合，近来贫汉难存活。", "content": "早早开门拜闯王，管教大小都欢悦。杀牛羊，备酒浆，开了城门迎闯王，闯王来了不纳粮。吃他娘，着她娘，吃着不够有闯王。不当差，不纳粮，大家快活过一场。"},
    {"title": "关山虽胜路难堪，才上征鞍又解骖。", "content": "十丈黄尘千尺雪，可知俱不似江南。"},
    {"title": "鹧鸪声里夕阳西，陌上征人首尽低。", "content": "遍地关山行不得，为谁辛苦尽情啼？"},
    {"title": "居庸关上子规啼，饮马流泉落日低。", "content": "雨雪自飞千嶂外，榆林只隔数峰西。"},
    {"title": "江干多是钓人居，柳陌菱塘一带疏。", "content": "好是日斜风定后，半江红树卖鲈鱼。"},
    {"title": "路回临石岸，树老出墙根。", "content": "野水合诸涧，桃花成一村。呼鸡过篱栅，行酒尽儿孙。老矣吾将隐，前峰恰对门。"},
    {"title": "黄花古渡接芦溪，行过萍乡路渐低。", "content": "吠犬鸣鸡村远近，乳鹅新鸭岸东西。丝缫细雨沾衣润，刀剪良苗出水齐。犹与湖南风土近，春深无处不耕犁。"},
    {"title": "月黑见渔灯，孤光一点萤。", "content": "微微风簇浪，散作满河星。"},
    {"title": "到处陂塘决决流，垂杨百里罨平畴。", "content": "行人便觉须眉绿，一路蝉声过许州。"},
    {"title": "山色江声共寂寥，十三陵树晚萧萧。", "content": "中原事业如江左，芳草何须怨六朝。"},
    {"title": "和雨还穿户，经风忽过墙。", "content": "虽缘草成质，不借月为光。解识幽人意，请今聊处囊。君看落空阔，何异大星芒。"},
    {"title": "夜寒香界白，涧曲寺门通。", "content": "月在众峰顶，泉流乱叶中。一灯群动息，孤磬四天空。归路畏逢虎，况闻岩下风。"},
    {"title": "咬定青山不放松，立根原在破岩中。", "content": "千磨万击还坚劲，任尔东西南北风。"},
    {"title": "晨起开门雪满山，雪晴云淡日光寒。", "content": "檐流未滴梅花冻，一种清孤不等闲。"},
    {"title": "卖得鲜鱼二百钱，籴粮炊饭放归船。", "content": "拔来湿苇烧难着，晒在垂杨古岸边。"},
    {"title": "百金买骏马，千金买美人；万金买高爵，何处买青春？", "content": ""},
    {"title": "爱子心无尽，归家喜及辰。", "content": "寒衣针线密，家信墨痕新。见面怜清瘦，呼儿问苦辛。低徊愧人子，不敢叹风尘。"},
    {"title": "莫唱当年长恨歌，人间亦自有银河。", "content": "石壕村里夫妻别，泪比长生殿上多。"},
    {"title": "秋夜访秋士，先闻水上音。", "content": "半天凉月色，一笛酒人心。响遏碧云近，香传红藕深。相逢清露下，流影湿衣襟。"},
    {"title": "十里崎岖半里平，一峰才送一峰迎。", "content": "青山似茧将人裹，不信前头有路行。"},
    {"title": "牧童骑黄牛，歌声振林樾。", "content": "意欲捕鸣蝉，忽然闭口立。"},
    {"title": "爱好由来下笔难，一诗千改始心安。", "content": "阿婆还似初笄女，头未梳成不许看。"},
    {"title": "浓似春云淡似烟，参差绿到大江边。", "content": "斜阳流水推篷坐，翠色随人欲上船。"},
    {"title": "李杜诗篇万口传，至今已觉不新鲜。", "content": "江山代有才人出，各领风骚数百年。"},
    {"title": "布谷飞飞劝早耕，舂锄扑扑趁春晴。", "content": "千层石树遥行路，一带山田放水声。"},
    {"title": "大道青青望不遮，年时系马醉流霞。", "content": "风前带是同心结，杯底人如解语花。下杜城边南北路，上阑门外去来车。匆匆觉得扬州梦，检点闲愁在鬓华。唤起窗前尚宿酲，啼鹃催去又声声。丹青旧誓相如札，禅榻"},
    {"title": "搴帷拜母河梁去，白发愁看泪眼枯。", "content": "惨惨柴门风雪夜，此时有子不如无。"},
    {"title": "金粉东南十五州，万重恩怨属名流。", "content": "牢盆狎客操全算，团扇才人踞上游。避席畏闻文字狱，著书都为稻粱谋。田横五百人安在，难道归来尽列侯？"},
    {"title": "浩荡离愁白日斜，吟鞭东指即天涯。", "content": "落红不是无情物，化作春泥更护花。"},
    {"title": "九州生气恃风雷，万马齐喑究可哀。", "content": "我劝天公重抖擞，不拘一格降人材。(人材 一作：人才)"},
    {"title": "草长莺飞二月天，拂堤杨柳醉春烟。", "content": "儿童散学归来早，忙趁东风放纸鸢。"},
    {"title": "远看山有色，近听水无声。", "content": "春去花还在，人来鸟不惊。"},
    {"title": "春愁难遣强看山，往事惊心泪欲潸。", "content": "四百万人同一哭，去年今日割台湾。"},
    {"title": "望门投止思张俭，忍死须臾待杜根。", "content": "我自横刀向天笑，去留肝胆两昆仑。(版本一)(望门投趾怜张俭，直谏陈书愧杜根。手掷欧刀仰天笑，留将公罪后人论。版本二)"},
    {"title": "诗界千年靡靡风，兵魂销尽国魂空。", "content": "集中什九从军乐，亘古男儿一放翁。"},
    {"title": "不惜千金买宝刀，貂裘换酒也堪豪。", "content": "一腔热血勤珍重，洒去犹能化碧涛。"},
    {"title": "邹容吾小弟，被发下瀛州。", "content": "快剪刀除辫，干牛肉作餱。英雄一入狱，天地亦悲秋。临命须掺手，乾坤只两头！"},
    {"title": "江南可采莲，莲叶何田田。", "content": "鱼戏莲叶间。鱼戏莲叶东，鱼戏莲叶西，鱼戏莲叶南，鱼戏莲叶北。"},
    {"title": "云对雨，雪对风。", "content": "花对树，鸟对虫。山清对水秀，柳绿对桃红。"},
    {"title": "鹅，鹅，鹅，曲项向天歌。", "content": "白毛浮绿水，红掌拨清波。"},
    {"title": "远看山有色，近听水无声。", "content": "春去花还在，人来鸟不惊。"},
    {"title": "锄禾日当午，汗滴禾下土。", "content": "谁知盘中餐，粒粒皆辛苦。"},
    {"title": "小时不识月，呼作白玉盘。", "content": "又疑瑶台镜，飞在青云端。"},
    {"title": "解落三秋叶，能开二月花。", "content": "过江千尺浪，入竹万竿斜。"},
    {"title": "床前明月光，疑是地上霜。", "content": "举头望明月，低头思故乡。"},
    {"title": "古对今，圆对方。", "content": "严寒对酷暑，春暖对秋凉。晨对暮，雪对霜。和风对细雨，朝霞对夕阳。桃对李，柳对杨，莺歌对燕舞，鸟语对花香。"},
    {"title": "人之初，性本善。", "content": "性相近，习相远。苟不教，性乃迁。教之道，贵以专。子不学，非所宜。幼不学，老何为。玉不琢，不成器。人不学，不知义。"},
    {"title": "小娃撑小艇，偷采白莲回。", "content": "不解藏踪迹，浮萍一道开。"},
    {"title": "泉眼无声惜细流，树阴照水爱晴柔。", "content": "(阴 一作：荫)小荷才露尖尖角，早有蜻蜓立上头。"},
    {"title": "春眠不觉晓，处处闻啼鸟。", "content": "夜来风雨声，花落知多少。"},
    {"title": "松下问童子，言师采药去。", "content": "只在此山中，云深不知处。"},
    {"title": "李白乘舟将欲行，忽闻岸上踏歌声。", "content": "桃花潭水深千尺，不及汪伦送我情。"},
    {"title": "头上红冠不用裁，满身雪白走将来。", "content": "(裁 一作：戴)平生不敢轻言语，一叫千门万户开。"},
    {"title": "白日依山尽，黄河入海流。", "content": "欲穷千里目，更上一层楼。"},
    {"title": "日照香炉生紫烟，遥看瀑布挂前川。", "content": "飞流直下三千尺，疑是银河落九天。"},
    {"title": "千山鸟飞绝，万径人踪灭。", "content": "孤舟蓑笠翁，独钓寒江雪。"},
    {"title": "敕勒川，阴山下。", "content": "天似穹庐，笼盖四野。天苍苍，野茫茫，风吹草低见牛羊。"},
    {"title": "墙角数枝梅，凌寒独自开。", "content": "遥知不是雪，为有暗香来。"},
    {"title": "蓬头稚子学垂纶，侧坐莓苔草映身。", "content": " 路人借问遥招手，怕得鱼惊不应人。"},
    {"title": "危楼高百尺，手可摘星辰。", "content": "不敢高声语，恐惊天上人。"},
    {"title": "草长莺飞二月天，拂堤杨柳醉春烟。", "content": "儿童散学归来早，忙趁东风放纸鸢。"},
    {"title": "碧玉妆成一树高，万条垂下绿丝绦。", "content": "不知细叶谁裁出，二月春风似剪刀。"},
    {"title": "毕竟西湖六月中，风光不与四时同。", "content": "接天莲叶无穷碧，映日荷花别样红。"},
    {"title": "两个黄鹂鸣翠柳，一行白鹭上青天。", "content": "窗含西岭千秋雪，门泊东吴万里船。"},
    {"title": "离离原上草，一岁一枯荣。", "content": "野火烧不尽，春风吹又生。远芳侵古道，晴翠接荒城。又送王孙去，萋萋满别情。"},
    {"title": "春种一粒粟，秋收万颗子。", "content": "四海无闲田，农夫犹饿死。"},
    {"title": "月黑见渔灯，孤光一点萤。", "content": "微微风簇浪，散作满河星。"},
    {"title": "湖光秋月两相和，潭面无风镜未磨。", "content": "遥望洞庭山水翠，白银盘里一青螺。(山水翠 一作：山水色)"},
    {"title": "远上寒山石径斜，白云生处有人家。", "content": "(生处 一作：深处)停车坐爱枫林晚，霜叶红于二月花。"},
    {"title": "萧萧梧叶送寒声，江上秋风动客情。", "content": "知有儿童挑促织，夜深篱落一灯明。"},
    {"title": "空山不见人，但闻人语响。", "content": "返景入深林，复照青苔上。"},
    {"title": "天门中断楚江开，碧水东流至此回。", "content": "两岸青山相对出，孤帆一片日边来。"},
    {"title": "水光潋滟晴方好，山色空蒙雨亦奇。", "content": "欲把西湖比西子，淡妆浓抹总相宜。"},
    {"title": "群儿戏于庭，一儿登瓮，足跌没水中。", "content": "众皆弃去，光持石击瓮破之，水迸，儿得活。"},
    {"title": "牧童骑黄牛，歌声振林樾。", "content": "意欲捕鸣蝉，忽然闭口立。"},
    {"title": "朝辞白帝彩云间，千里江陵一日还。", "content": "两岸猿声啼不住，轻舟已过万重山。"},
    {"title": "荷叶罗裙一色裁，芙蓉向脸两边开。", "content": "乱入池中看不见，闻歌始觉有人来。"},
    {"title": "迟日江山丽，春风花草香。", "content": "泥融飞燕子，沙暖睡鸳鸯。"},
    {"title": "竹外桃花三两枝，春江水暖鸭先知。", "content": "蒌蒿满地芦芽短，正是河豚欲上时。"},
    {"title": "梅子黄时日日晴，小溪泛尽却山行。", "content": "绿阴不减来时路，添得黄鹂四五声。"},
    {"title": "宋人有耕者。", "content": "田中有株。兔走触株，折颈而死。因释其耒而守株，冀复得兔。兔不可复得，而身为宋国笑。"},
    {"title": "爆竹声中一岁除，春风送暖入屠苏。", "content": "千门万户曈曈日，总把新桃换旧符。"},
    {"title": "清明时节雨纷纷，路上行人欲断魂。", "content": "借问酒家何处有？牧童遥指杏花村。"},
    {"title": "独在异乡为异客，每逢佳节倍思亲。", "content": "遥知兄弟登高处，遍插茱萸少一人。"},
    {"title": "江南好，风景旧曾谙。", "content": "日出江花红胜火，春来江水绿如蓝。能不忆江南？"},
    {"title": "独怜幽草涧边生，上有黄鹂深树鸣。", "content": " 春潮带雨晚来急，野渡无人舟自横。"},
    {"title": "人间四月芳菲尽，山寺桃花始盛开。", "content": " 长恨春归无觅处，不知转入此中来。"},
    {"title": "一道残阳铺水中，半江瑟瑟半江红。", "content": "可怜九月初三夜，露似真珠月似弓。"},
    {"title": "横看成岭侧成峰，远近高低各不同。", "content": "不识庐山真面目，只缘身在此山中。"},
    {"title": "梅雪争春未肯降，骚人阁笔费评章。", "content": "梅须逊雪三分白，雪却输梅一段香。"},
    {"title": "炎帝之少女，名曰女娃。", "content": "女娃游于东海，溺而不返，故为精卫，常衔西山之木石，以堙于东海。"},
    {"title": "秦时明月汉时关，万里长征人未还。", "content": "但使龙城飞将在，不教胡马度阴山。"},
    {"title": "葡萄美酒夜光杯，欲饮琵琶马上催。", "content": "醉卧沙场君莫笑，古来征战几人回？"},
    {"title": "生当作人杰，死亦为鬼雄。", "content": "至今思项羽，不肯过江东。"},
    {"title": "王戎七岁，尝与诸小儿游。", "content": "看道边李树多子折枝，诸儿竞走取之，唯戎不动。人问之，答曰：“树在道边而多子，此必苦李。”取之，信然。"},
    {"title": "空山不见人，但闻人语响。", "content": "返景入深林，复照青苔上。"},
    {"title": "云母屏风烛影深，长河渐落晓星沉。", "content": "嫦娥应悔偷灵药，碧海青天夜夜心。"},
    {"title": "千里黄云白日曛，北风吹雁雪纷纷。", "content": "莫愁前路无知己，天下谁人不识君。"},
    {"title": "梅子金黄杏子肥，麦花雪白菜花稀。", "content": "日长篱落无人过，惟有蜻蜓蛱蝶飞。(惟 一作：唯)"},
    {"title": "篱落疏疏一径深，树头新绿未成阴。", "content": "(新绿 一作：花落)儿童急走追黄蝶，飞入菜花无处寻。"},
    {"title": "茅檐低小，溪上青青草。", "content": "醉里吴音相媚好，白发谁家翁媪？大儿锄豆溪东，中儿正织鸡笼。最喜小儿亡赖，溪头卧剥莲蓬。(亡 同：无)"},
    {"title": "寒雨连江夜入吴，平明送客楚山孤。", "content": "洛阳亲友如相问，一片冰心在玉壶。"},
    {"title": "月黑雁飞高，单于夜遁逃。", "content": "欲将轻骑逐，大雪满弓刀。"},
    {"title": "我家洗砚池头树，朵朵花开淡墨痕。", "content": "(我家 一作：吾家；朵朵 一作：个个)不要人夸好颜色，只留清气满乾坤。(好颜色 一作：颜色好)"},
    {"title": "胤恭勤不倦，博学多通。", "content": "家贫不常得油，夏月则练囊盛数十萤火以照书，以夜继日焉。"},
    {"title": "磨针溪，在象耳山下。", "content": "世传李太白读书山中，未成，弃去。过是溪，逢老媪方磨铁杵。问之，曰：“欲作针。”太白感其意，还卒业。"},
    {"title": "读陆游咏梅词，反其意而用之。", "content": "风雨送春归，飞雪迎春到。已是悬崖百丈冰，犹有花枝俏。俏也不争春，只把春来报。待到山花烂漫时，她在丛中笑。"},
    {"title": "黄师塔前江水东，春光懒困倚微风。", "content": "桃花一簇开无主，可爱深红爱浅红？"},
    {"title": "不论平地与山尖，无限风光尽被占。", "content": " 采得百花成蜜后，为谁辛苦为谁甜？"},
    {"title": "众鸟高飞尽，孤云独去闲。", "content": "相看两不厌，只有敬亭山。(只有 一作：唯有)"},
    {"title": "死去元知万事空，但悲不见九州同。", "content": "王师北定中原日，家祭无忘告乃翁。"},
    {"title": "山外青山楼外楼，西湖歌舞几时休？暖风熏得游人醉，直把杭州作汴州。", "content": ""},
    {"title": "九州生气恃风雷，万马齐喑究可哀。", "content": "我劝天公重抖擞，不拘一格降人材。(人材 一作：人才)"},
    {"title": "故今日之责任，不在他人，而全在我少年。", "content": "少年智则国智，少年富则国富；少年强则国强，少年独立则国独立；少年自由则国自由；少年进步则国进步；少年胜于欧洲，则国胜于欧洲；少年雄于地球，则国"},
    {"title": "空山新雨后，天气晚来秋。", "content": "明月松间照，清泉石上流。竹喧归浣女，莲动下渔舟。随意春芳歇，王孙自可留。"},
    {"title": "月落乌啼霜满天，江枫渔火对愁眠。", "content": "姑苏城外寒山寺，夜半钟声到客船。"},
    {"title": "山一程，水一程，身向榆关那畔行，夜深千帐灯。", "content": "风一更，雪一更，聒碎乡心梦不成，故园无此声。"},
    {"title": "知之为知之，不知为不知，是知也。", "content": "敏而好学，不耻下问。默而识之，学而不厌，诲人不倦。我非生而知之者，好古，敏以求之者也。学如不及，犹恐失之。吾尝终日不食，终夜不寝，以思，无益，不如学"},
    {"title": "垂緌饮清露，流响出疏桐。", "content": "居高声自远，非是藉秋风。"},
    {"title": "七夕今宵看碧霄，牵牛织女渡河桥。", "content": " 家家乞巧望秋月，穿尽红丝几万条。"},
    {"title": "西塞山前白鹭飞，桃花流水鳜鱼肥。", "content": "青箬笠，绿蓑衣，斜风细雨不须归。"},
    {"title": "半亩方塘一鉴开，天光云影共徘徊。", "content": "问渠那得清如许？为有源头活水来。(那 通：哪)"},
    {"title": "昨夜江边春水生，蒙冲巨舰一毛轻。", "content": "(蒙冲 一作：艨艟)向来枉费推移力，此日中流自在行。"},
    {"title": "昼出耘田夜绩麻，村庄儿女各当家。", "content": "童孙未解供耕织，也傍桑阴学种瓜。"},
    {"title": "稚子金盆脱晓冰，彩丝穿取当银钲。", "content": "(银钲 一作：银铮)敲成玉磬穿林响，忽作玻璃碎地声。(玻璃 一作：玻瓈)"},
    {"title": "草满池塘水满陂，山衔落日浸寒漪。", "content": "牧童归去横牛背，短笛无腔信口吹。"},
    {"title": "青海长云暗雪山，孤城遥望玉门关。", "content": "黄沙百战穿金甲，不破楼兰终不还。(不破 一作：不斩)"},
    {"title": "三万里河东入海，五千仞岳上摩天。", "content": "遗民泪尽胡尘里，南望王师又一年。"},
    {"title": "剑外忽传收蓟北，初闻涕泪满衣裳。", "content": "却看妻子愁何在，漫卷诗书喜欲狂。白日放歌须纵酒，青春作伴好还乡。即从巴峡穿巫峡，便下襄阳向洛阳。"},
    {"title": "楚人有鬻盾与矛者，誉之曰：“吾盾之坚，物莫能陷也。", "content": "”又誉其矛曰：“吾矛之利，于物无不陷也。”或曰：“以子之矛陷子之盾，何如？”其人弗能应也。夫不可陷之盾与无不陷之矛，不可同世而立。"},
    {"title": "梁国杨氏子九岁，甚聪惠。", "content": "孔君平诣其父，父不在，乃呼儿出。为设果，果有杨梅。孔指以示儿曰：“此是君家果。”儿应声答曰：“未闻孔雀是夫子家禽。”"},
    {"title": "慈母手中线，游子身上衣。", "content": "临行密密缝，意恐迟迟归。谁言寸草心，报得三春晖。"},
    {"title": "人闲桂花落，夜静春山空。", "content": "月出惊山鸟，时鸣春涧中。"},
    {"title": "黄河远上白云间，一片孤城万仞山。", "content": "羌笛何须怨杨柳，春风不度玉门关。"},
    {"title": "故人西辞黄鹤楼，烟花三月下扬州。", "content": "孤帆远影碧空尽，唯见长江天际流。 (唯 通：惟)"},
    {"title": "绿遍山原白满川，子规声里雨如烟。", "content": "乡村四月闲人少，才了蚕桑又插田。"},
    {"title": "移舟泊烟渚，日暮客愁新。", "content": "野旷天低树，江清月近人。"},
    {"title": "黑云翻墨未遮山，白雨跳珠乱入船。", "content": "卷地风来忽吹散，望湖楼下水如天。"},
    {"title": "明月别枝惊鹊，清风半夜鸣蝉。", "content": "稻花香里说丰年，听取蛙声一片。 七八个星天外，两三点雨山前。旧时茅店社林边，路转溪桥忽见。(溪桥 一作：溪头)"},
    {"title": "红军不怕远征难，万水千山只等闲。", "content": "五岭逶迤腾细浪，乌蒙磅礴走泥丸。金沙水拍云崖暖，大渡桥横铁索寒。更喜岷山千里雪，三军过后尽开颜。"},
    {"title": "九曲黄河万里沙，浪淘风簸自天涯。", "content": "如今直上银河去，同到牵牛织女家。"},
    {"title": "千里莺啼绿映红，水村山郭酒旗风。", "content": "南朝四百八十寺，多少楼台烟雨中。"},
    {"title": "茅檐长扫净无苔，花木成畦手自栽。", "content": "一水护田将绿绕，两山排闼送青来。 (一水 一作：一手)"},
    {"title": "伯牙鼓琴，锺子期听之。", "content": "方鼓琴而志在太山，锺子期曰：“善哉乎鼓琴，巍巍乎若太山。”少选之间而志在流水，锺子期又曰：“善哉乎鼓琴，汤汤乎若流水。”锺子期死，伯牙破琴绝弦，终身不复鼓琴，"},
    {"title": "蜀中有杜处士 ，好书画，所宝以百数。", "content": "有戴嵩《牛》一轴，尤所爱，锦囊玉轴，常以自随。　　一日曝书画，有一牧童见之，拊掌大笑，曰：“此画斗牛也。牛斗，力在角，尾搐入两股间，今乃掉尾而斗"},
    {"title": "故人具鸡黍，邀我至田家。", "content": "绿树村边合，青山郭外斜。开轩面场圃，把酒话桑麻。待到重阳日，还来就菊花。"},
    {"title": "赤橙黄绿青蓝紫，谁持彩练当空舞？雨后复斜阳，关山阵阵苍。", "content": "当年鏖战急，弹洞前村壁。装点此关山，今朝更好看。"},
    {"title": "胜日寻芳泗水滨，无边光景一时新。", "content": "等闲识得东风面，万紫千红总是春。"},
    {"title": "少小离家老大回，乡音无改鬓毛衰。", "content": "儿童相见不相识，笑问客从何处来。"},
    {"title": "春城无处不飞花，寒食东风御柳斜。", "content": " 日暮汉宫传蜡烛，轻烟散入五侯家。"},
    {"title": "迢迢牵牛星，皎皎河汉女。", "content": "纤纤擢素手，札札弄机杼。终日不成章，泣涕零如雨。河汉清且浅，相去复几许。盈盈一水间，脉脉不得语。"},
    {"title": "中庭地白树栖鸦，冷露无声湿桂花。", "content": "今夜月明人尽望，不知秋思落谁家。"},
    {"title": "大漠沙如雪，燕山月似钩。", "content": "何当金络脑，快走踏清秋。"},
    {"title": "千锤万凿出深山，烈火焚烧若等闲。", "content": "(万凿 一作：万击)粉骨碎身浑不怕，要留清白在人间。(浑不怕 一作：全不怕)"},
    {"title": "咬定青山不放松，立根原在破岩中。", "content": "千磨万击还坚劲，任尔东西南北风。"},
    {"title": "弈秋，通国之善弈者也。", "content": "使弈秋诲二人弈，其一人专心致志，惟弈秋之为听；一人虽听之，一心以为有鸿鹄将至，思援弓缴而射之。虽与之俱学，弗若之矣。为是其智弗若与？曰：非然也。"},
    {"title": "孔子东游，见两小儿辩斗，问其故。", "content": "(辩斗 一作：辩日)一儿曰：“我以日始出时去人近，而日中时远也。” 一儿曰：“我以日初出远，而日中时近也。”一儿曰：“日初出大如车盖，及日中则如盘盂"},
    {"title": "青青园中葵，朝露待日晞。", "content": "阳春布德泽，万物生光辉。常恐秋节至，焜黄华叶衰。百川东到海，何时复西归？少壮不努力，老大徒伤悲！"},
    {"title": "昔我往矣，杨柳依依。", "content": "今我来思，雨雪霏霏。行道迟迟，载渴载饥。我心伤悲，莫知我哀！"},
    {"title": "渭城朝雨浥轻尘，客舍青青柳色新。", "content": "劝君更尽一杯酒，西出阳关无故人。"},
    {"title": "好雨知时节，当春乃发生。", "content": "随风潜入夜，润物细无声。野径云俱黑，江船火独明。晓看红湿处，花重锦官城。"},
    {"title": "天街小雨润如酥，草色遥看近却无。", "content": "最是一年春好处，绝胜烟柳满皇都。"},
    {"title": "江上往来人，但爱鲈鱼美。", "content": "君看一叶舟，出没风波里。"},
    {"title": "京口瓜洲一水间，钟山只隔数重山。", "content": "春风又绿江南岸，明月何时照我还。(又绿 一作：自绿)"},
    {"title": "应怜屐齿印苍苔，小扣柴扉久不开。", "content": "春色满园关不住，一枝红杏出墙来。"},
    {"title": "水是眼波横，山是眉峰聚。", "content": "欲问行人去那边？眉眼盈盈处。才始送春归，又送君归去。若到江南赶上春，千万和春住。"},
    {"title": "游蕲水清泉寺，寺临兰溪，溪水西流。", "content": "山下兰芽短浸溪，松间沙路净无泥，萧萧暮雨子规啼。(萧萧 一作：潇潇)谁道人生无再少？门前流水尚能西！休将白发唱黄鸡。"},
    {"title": "春归何处？寂寞无行路。", "content": "若有人知春去处，唤取归来同住。 春无踪迹谁知？除非问取黄鹂。百啭无人能解，因风飞过蔷薇。(问取 一作：唤取)"},
    {"title": "东临碣石，以观沧海。", "content": "水何澹澹，山岛竦峙。树木丛生，百草丰茂。秋风萧瑟，洪波涌起。日月之行，若出其中；星汉灿烂，若出其里。幸甚至哉，歌以咏志。"},
    {"title": "客路青山外，行舟绿水前。", "content": "潮平两岸阔，风正一帆悬。海日生残夜，江春入旧年。乡书何处达？归雁洛阳边。"},
    {"title": "杨花落尽子规啼，闻道龙标过五溪。", "content": "我寄愁心与明月，随君直到夜郎西。(随君 一作：随风)"},
    {"title": "枯藤老树昏鸦，小桥流水人家，古道西风瘦马。", "content": "夕阳西下，断肠人在天涯。"},
    {"title": "谢太傅寒雪日内集，与儿女讲论文义。", "content": "俄而雪骤，公欣然曰：“白雪纷纷何所似？”兄子胡儿曰：“撒盐空中差可拟。”兄女曰：“未若柳絮因风起。”公大笑乐。即公大兄无奕女，左将军王凝之妻也。"},
    {"title": "陈太丘与友期行，期日中。", "content": "过中不至，太丘舍去，去后乃至。元方时年七岁，门外戏。客问元方：“尊君在不？”答曰：“待君久不至，已去。”友人便怒曰：“非人哉！与人期行，相委而去。”元方曰："},
    {"title": "子曰：“学而时习之，不亦说乎？有朋自远方来，不亦乐乎？人不知而不愠，不亦君子乎？”《学而》曾子曰：“吾日三省吾身：为人谋而不忠乎？与朋友交而不信乎？传不习乎？”《学而》子曰：“吾十", "content": ""},
    {"title": "一九三六年冬，梅山被围。", "content": "余伤病伏丛莽间二十余日，虑不得脱，得诗三首留衣底。旋围解。断头今日意如何？创业艰难百战多。此去泉台招旧部，旌旗十万斩阎罗。南国烽烟正十年，此头须向国门悬。后"},
    {"title": "夫君子之行，静以修身，俭以养德。", "content": "非淡泊无以明志，非宁静无以致远。夫学须静也，才须学也，非学无以广才，非志无以成学。淫慢则不能励精，险躁则不能治性。年与时驰，意与日去，遂成枯落，多不"},
    {"title": "一屠晚归，担中肉尽，止有剩骨。", "content": "途中两狼，缀行甚远。　　屠惧，投以骨。一狼得骨止，一狼仍从。复投之，后狼止而前狼又至。骨已尽矣，而两狼之并驱如故。　　屠大窘，恐前后受其敌。顾野有麦场"},
    {"title": "却说真君与大圣变做法天象地的规模，正斗时，大圣忽见本营中妖猴惊散，自觉心慌，收了法象，掣棒抽身就走。", "content": "真君见他败走，大步赶上道：“那里走？趁早归降，饶你性命！”大圣不恋战，只情跑起。"},
    {"title": "宋之丁氏，家无井，而出溉汲，常一人居外。", "content": "及其家穿井，告人曰：“吾穿井得一人。”有闻而传之者曰：“丁氏穿井得一人。”国人道之，闻之于宋君。宋君令人问之于丁氏，丁氏对曰：“得一人之使，"},
    {"title": "杞国有人忧天地崩坠，身亡所寄，废寝食者。", "content": "　　又有忧彼之所忧者，因往晓之，曰：“天，积气耳，亡处亡气。若屈伸呼吸，终日在天中行止，奈何忧崩坠乎？”　　其人曰：“天果积气，日月星宿，不"},
    {"title": "峨眉山月半轮秋，影入平羌江水流。", "content": " 夜发清溪向三峡，思君不见下渝州。"},
    {"title": "岐王宅里寻常见，崔九堂前几度闻。", "content": "正是江南好风景，落花时节又逢君。"},
    {"title": "强欲登高去，无人送酒来。", "content": "遥怜故园菊，应傍战场开。"},
    {"title": "回乐烽前沙似雪，受降城外月如霜。", "content": "(回乐烽 一作：回乐峰)不知何处吹芦管，一夜征人尽望乡。"},
    {"title": "自古逢秋悲寂寥，我言秋日胜春朝。", "content": "晴空一鹤排云上，便引诗情到碧霄。"},
    {"title": "君问归期未有期，巴山夜雨涨秋池。", "content": " 何当共剪西窗烛，却话巴山夜雨时。"},
    {"title": "僵卧孤村不自哀，尚思为国戍轮台。", "content": "夜阑卧听风吹雨，铁马冰河入梦来。"},
    {"title": "终古高云簇此城，秋风吹散马蹄声。", "content": "河流大野犹嫌束，山入潼关不解平。"},
    {"title": "初，权谓吕蒙曰：“卿今当涂掌事，不可不学！”蒙辞以军中多务。", "content": "权曰：“孤岂欲卿治经为博士邪！但当涉猎，见往事耳。卿言多务，孰若孤？孤常读书，自以为大有所益。”蒙乃始就学。及鲁肃过寻阳"},
    {"title": "唧唧复唧唧，木兰当户织。", "content": "不闻机杼声，唯闻女叹息。(唯 一作：惟)　　问女何所思，问女何所忆。女亦无所思，女亦无所忆。昨夜见军帖，可汗大点兵，军书十二卷，卷卷有爷名。阿爷无大儿，木兰"},
    {"title": "陈康肃公善射，当世无双 ，公亦以此自矜。", "content": "尝射于家圃，有卖油翁释担而立，睨之久而不去。见其发矢十中八九，但微颔之。(善射 一作：尧咨善射)　　康肃问曰：“汝亦知射乎？吾射不亦精乎？”"},
    {"title": "山不在高，有仙则名。", "content": "水不在深，有龙则灵。斯是陋室，惟吾德馨。苔痕上阶绿，草色入帘青。谈笑有鸿儒，往来无白丁。可以调素琴，阅金经。无丝竹之乱耳，无案牍之劳形。南阳诸葛庐，西蜀子云亭。"},
    {"title": "水陆草木之花，可爱者甚蕃。", "content": "晋陶渊明独爱菊。自李唐来，世人甚爱牡丹。予独爱莲之出淤泥而不染，濯清涟而不妖，中通外直，不蔓不枝，香远益清，亭亭净植，可远观而不可亵玩焉。(甚爱 一作：盛"},
    {"title": "前不见古人，后不见来者。", "content": "念天地之悠悠，独怆然而涕下！"},
    {"title": "岱宗夫如何？齐鲁青未了。", "content": "造化钟神秀，阴阳割昏晓。荡胸生曾云，决眦入归鸟。( 曾 同：层)会当凌绝顶，一览众山小。"},
    {"title": "飞来山上千寻塔，闻说鸡鸣见日升。", "content": "(飞来山 一作：飞来峰)不畏浮云遮望眼，自缘身在最高层。"},
    {"title": "莫笑农家腊酒浑，丰年留客足鸡豚。", "content": "山重水复疑无路，柳暗花明又一村。箫鼓追随春社近，衣冠简朴古风存。从今若许闲乘月，拄杖无时夜叩门。"},
    {"title": "浩荡离愁白日斜，吟鞭东指即天涯。", "content": "落红不是无情物，化作春泥更护花。"},
    {"title": "板印书籍，唐人尚未盛为之。", "content": "自冯瀛王始印五经，已后典籍皆为板本。　　庆历中，有布衣毕昇，又为活板。其法：用胶泥刻字，薄如钱唇，每字为一印，火烧令坚。先设一铁板，其上以松脂、蜡和纸灰之"},
    {"title": "独坐幽篁里，弹琴复长啸。", "content": "深林人不知，明月来相照。"},
    {"title": "谁家玉笛暗飞声，散入春风满洛城。", "content": " 此夜曲中闻折柳，何人不起故园情。"},
    {"title": "故园东望路漫漫，双袖龙钟泪不干。", "content": " 马上相逢无纸笔，凭君传语报平安。"},
    {"title": "草树知春不久归，百般红紫斗芳菲。", "content": "(草树 一作：草木)杨花榆荚无才思，惟解漫天作雪飞。"},
    {"title": "烟笼寒水月笼沙，夜泊秦淮近酒家。", "content": "商女不知亡国恨，隔江犹唱后庭花。"},
    {"title": "宣室求贤访逐臣，贾生才调更无伦。", "content": "可怜夜半虚前席，不问苍生问鬼神。"},
    {"title": "莫言下岭便无难，赚得行人错喜欢。", "content": "(错喜欢 一作：空喜欢)政入万山围子里，一山放出一山拦。(政入 一作：正入；围子 一作：圈子；放出 一作：放过)"},
    {"title": "黄梅时节家家雨，青草池塘处处蛙。", "content": "有约不来过夜半，闲敲棋子落灯花。"},
    {"title": "自三峡七百里中，两岸连山，略无阙处。", "content": "重岩叠嶂，隐天蔽日，自非亭午夜分，不见曦月。(阙 通：缺；重岩 一作：重峦)　　至于夏水襄陵，沿溯阻绝。或王命急宣，有时朝发白帝，暮到江陵，其间"},
    {"title": "山川之美，古来共谈。", "content": "高峰入云，清流见底。两岸石壁，五色交晖。青林翠竹，四时俱备。晓雾将歇，猿鸟乱鸣；夕日欲颓，沉鳞竞跃。实是欲界之仙都。自康乐以来，未复有能与其奇者。(交晖 一作："},
    {"title": "元丰六年十月十二日夜，解衣欲睡，月色入户，欣然起行。", "content": "念无与为乐者，遂至承天寺寻张怀民。怀民亦未寝，相与步于中庭。庭下如积水空明，水中藻、荇交横，盖竹柏影也。何夜无月？何处无竹柏？但"},
    {"title": "风烟俱净，天山共色。", "content": "从流飘荡，任意东西。自富阳至桐庐一百许里，奇山异水，天下独绝。　　水皆缥碧，千丈见底。游鱼细石，直视无碍。急湍甚箭，猛浪若奔。　　夹岸高山，皆生寒树，负势竞上，"},
    {"title": "东皋薄暮望，徙倚欲何依。", "content": "树树皆秋色，山山唯落晖。牧人驱犊返，猎马带禽归。相顾无相识，长歌怀采薇。"},
    {"title": "昔人已乘黄鹤去，此地空余黄鹤楼。", "content": "黄鹤一去不复返，白云千载空悠悠。晴川历历汉阳树，芳草萋萋鹦鹉洲。日暮乡关何处是？烟波江上使人愁。"},
    {"title": "单车欲问边，属国过居延。", "content": "征蓬出汉塞，归雁入胡天。大漠孤烟直，长河落日圆。萧关逢候骑，都护在燕然。"},
    {"title": "渡远荆门外，来从楚国游。", "content": "山随平野尽，江入大荒流。月下飞天镜，云生结海楼。仍怜故乡水，万里送行舟。"},
    {"title": "孤山寺北贾亭西，水面初平云脚低。", "content": "几处早莺争暖树，谁家新燕啄春泥。乱花渐欲迷人眼，浅草才能没马蹄。最爱湖东行不足，绿杨阴里白沙堤。"},
    {"title": "天时不如地利，地利不如人和。", "content": "三里之城，七里之郭，环而攻之而不胜。夫环而攻之，必有得天时者矣，然而不胜者，是天时不如地利也。城非不高也，池非不深也，兵革非不坚利也，米粟非不多也，委而"},
    {"title": "景春曰：“公孙衍、张仪岂不诚大丈夫哉？一怒而诸侯惧，安居而天下熄。", "content": "”　　孟子曰：“是焉得为大丈夫乎？子未学礼乎？丈夫之冠也，父命之；女子之嫁也，母命之，往送之门，戒之曰：‘往之女家"},
    {"title": "舜发于畎亩之中，傅说举于版筑之间，胶鬲举于鱼盐之中，管夷吾举于士，孙叔敖举于海，百里奚举于市。", "content": "故天将降大任于是人也，必先苦其心志，劳其筋骨，饿其体肤，空乏其身，行拂乱其所为，所以动"},
    {"title": "太行、王屋二山，方七百里，高万仞，本在冀州之南，河阳之北。", "content": "　　北山愚公者，年且九十，面山而居。惩山北之塞，出入之迂也，聚室而谋曰：“吾与汝毕力平险，指通豫南，达于汉阴，可乎？”杂然"},
    {"title": "文帝之后六年，匈奴大入边。", "content": "乃以宗正刘礼为将军，军霸上；祝兹侯徐厉为将军，军棘门；以河内守亚夫为将军，军细柳：以备胡。　　上自劳军。至霸上及棘门军，直驰入，将以下骑送迎。已而之细柳军"},
    {"title": "结庐在人境，而无车马喧。", "content": "问君何能尔？心远地自偏。采菊东篱下，悠然见南山。山气日夕佳，飞鸟相与还。此中有真意，欲辨已忘言。"},
    {"title": "国破山河在，城春草木深。", "content": "感时花溅泪，恨别鸟惊心。烽火连三月，家书抵万金。白头搔更短，浑欲不胜簪。"},
    {"title": "黑云压城城欲摧，甲光向日金鳞开。", "content": "角声满天秋色里，塞上燕脂凝夜紫。(塞上 一作：塞土)半卷红旗临易水，霜重鼓寒声不起。报君黄金台上意，提携玉龙为君死。"},
    {"title": "折戟沉沙铁未销，自将磨洗认前朝。", "content": "东风不与周郎便，铜雀春深锁二乔。"},
    {"title": "天接云涛连晓雾，星河欲转千帆舞。", "content": "仿佛梦魂归帝所。闻天语，殷勤问我归何处。我报路长嗟日暮，学诗谩有惊人句。九万里风鹏正举。风休住，蓬舟吹取三山去！"},
    {"title": "庭中有奇树，绿叶发华滋。", "content": "攀条折其荣，将以遗所思。馨香盈怀袖，路远莫致之。此物何足贵？但感别经时。"},
    {"title": "神龟虽寿，犹有竟时；腾蛇乘雾，终为土灰。", "content": "(腾 一作：螣)老骥伏枥，志在千里；烈士暮年，壮心不已。盈缩之期，不但在天；养怡之福，可得永年。幸甚至哉，歌以咏志。"},
    {"title": "亭亭山上松，瑟瑟谷中风。", "content": "风声一何盛，松枝一何劲！冰霜正惨凄，终岁常端正。岂不罹凝寒？松柏有本性。"},
    {"title": "八方各异气，千里殊风雨。", "content": "剧哉边海民，寄身于草野。(草野 一作：草墅)妻子象禽兽，行止依林阻。柴门何萧条，狐兔翔我宇。"},
    {"title": "一曲新词酒一杯，去年天气旧亭台。", "content": "夕阳西下几时回？无可奈何花落去，似曾相识燕归来。小园香径独徘徊。"},
    {"title": "轻舟短棹西湖好，绿水逶迤。", "content": "芳草长堤，隐隐笙歌处处随。无风水面琉璃滑，不觉船移。微动涟漪，惊起沙禽掠岸飞。"},
    {"title": "金陵城上西楼，倚清秋。", "content": "万里夕阳垂地大江流。中原乱，簪缨散，几时收？试倩悲风吹泪过扬州。"},
    {"title": "常记溪亭日暮，沉醉不知归路。", "content": "兴尽晚回舟，误入藕花深处。争渡，争渡，惊起一滩鸥鹭。"},
    {"title": "晋太元中，武陵人捕鱼为业。", "content": "缘溪行，忘路之远近。忽逢桃花林，夹岸数百步，中无杂树，芳草鲜美，落英缤纷。渔人甚异之，复前行，欲穷其林。　　林尽水源，便得一山，山有小口，仿佛若有光。便舍"},
    {"title": "从小丘西行百二十步，隔篁竹，闻水声，如鸣珮环，心乐之。", "content": "伐竹取道，下见小潭，水尤清冽。全石以为底，近岸，卷石底以出，为坻，为屿，为嵁，为岩。青树翠蔓，蒙络摇缀，参差披拂。(珮 一作："},
    {"title": "明有奇巧人曰王叔远，能以径寸之木，为宫室、器皿、人物，以至鸟兽、木石，罔不因势象形，各具情态。", "content": "尝贻余核舟一，盖大苏泛赤壁云。　　舟首尾长约八分有奇，高可二黍许。中轩敞者为舱，箬篷覆"},
    {"title": "关关雎鸠，在河之洲。", "content": "窈窕淑女，君子好逑。参差荇菜，左右流之。窈窕淑女，寤寐求之。求之不得，寤寐思服。悠哉悠哉，辗转反侧。参差荇菜，左右采之。窈窕淑女，琴瑟友之。参差荇菜，左右芼之。"},
    {"title": "蒹葭苍苍，白露为霜。", "content": "所谓伊人，在水一方。溯洄从之，道阻且长。溯游从之，宛在水中央。蒹葭萋萋，白露未晞。所谓伊人，在水之湄。溯洄从之，道阻且跻。溯游从之，宛在水中坻。蒹葭采采，白露未"},
    {"title": "北冥有鱼，其名为鲲。", "content": "鲲之大，不知其几千里也；化而为鸟，其名为鹏。鹏之背，不知其几千里也；怒而飞，其翼若垂天之云。是鸟也，海运则将徙于南冥。南冥者，天池也。《齐谐》者，志怪者也。《谐"},
    {"title": "庄子与惠子游于濠梁之上。", "content": "庄子曰：“鲦鱼出游从容，是鱼之乐也。”惠子曰：“子非鱼，安知鱼之乐？”庄子曰：“子非我，安知我不知鱼之乐？”惠子曰：“我非子，固不知子矣；子固非鱼也，子之不"},
    {"title": "虽有嘉肴，弗食，不知其旨也；虽有至道，弗学，不知其善也。", "content": "是故学然后知不足，教然后知困。知不足，然后能自反也；知困，然后能自强也。故曰：教学相长也。《兑命》曰“学学半”，其此之谓乎！"},
    {"title": "大道之行也，天下为公。", "content": "选贤与能，讲信修睦。故人不独亲其亲，不独子其子，使老有所终，壮有所用，幼有所长，矜、寡、孤、独、废疾者皆有所养，男有分，女有归。货恶其弃于地也，不必藏于己；力"},
    {"title": "世有伯乐，然后有千里马。", "content": "千里马常有，而伯乐不常有。故虽有名马，祗辱于奴隶人之手，骈死于槽枥之间，不以千里称也。(祗 同：衹)　　马之千里者，一食或尽粟一石。食马者不知其能千里而食也"},
    {"title": "暮投石壕村，有吏夜捉人。", "content": "老翁逾墙走，老妇出门看。(出门看 一作：出看门)吏呼一何怒！妇啼一何苦！听妇前致词：三男邺城戍。一男附书至，二男新战死。存者且偷生，死者长已矣！室中更无人，"},
    {"title": "八月秋高风怒号，卷我屋上三重茅。", "content": "茅飞渡江洒江郊，高者挂罥长林梢，下者飘转沉塘坳。南村群童欺我老无力，忍能对面为盗贼。公然抱茅入竹去，唇焦口燥呼不得，归来倚杖自叹息。俄顷风定云墨色，"},
    {"title": "卖炭翁，伐薪烧炭南山中。", "content": "满面尘灰烟火色，两鬓苍苍十指黑。卖炭得钱何所营？身上衣裳口中食。可怜身上衣正单，心忧炭贱愿天寒。夜来城外一尺雪，晓驾炭车辗冰辙。牛困人饥日已高，市南门外泥中"},
    {"title": "式微，式微，胡不归？微君之故，胡为乎中露？式微，式微，胡不归？微君之躬，胡为乎泥中？", "content": ""},
    {"title": "青青子衿，悠悠我心。", "content": "纵我不往，子宁不嗣音？青青子佩，悠悠我思。纵我不往，子宁不来？挑兮达兮，在城阙兮。一日不见，如三月兮！"},
    {"title": "城阙辅三秦，风烟望五津。", "content": "与君离别意，同是宦游人。海内存知己，天涯若比邻。无为在歧路，儿女共沾巾。"},
    {"title": "八月湖水平，涵虚混太清。", "content": "气蒸云梦泽，波撼岳阳城。欲济无舟楫，端居耻圣明。坐观垂钓者，徒有羡鱼情。"},
    {"title": "清晨入古寺，初日照高林。", "content": "曲径通幽处，禅房花木深。(曲 一作：竹)山光悦鸟性，潭影空人心。万籁此都寂，但余钟磬音。(都寂 一作：俱寂；但余 一作：惟余)"},
    {"title": "青山横北郭，白水绕东城。", "content": "此地一为别，孤蓬万里征。浮云游子意，落日故人情。挥手自兹去，萧萧班马鸣。"},
    {"title": "缺月挂疏桐，漏断人初静。", "content": "谁见幽人独往来，缥缈孤鸿影。(谁见 一作：时见)惊起却回头，有恨无人省。拣尽寒枝不肯栖，寂寞沙洲冷。"},
    {"title": "驿外断桥边，寂寞开无主。", "content": "已是黄昏独自愁，更着风和雨。(着 同：著)无意苦争春，一任群芳妒。零落成泥碾作尘，只有香如故。"},
    {"title": "北国风光，千里冰封，万里雪飘。", "content": "望长城内外，惟余莽莽；大河上下，顿失滔滔。(余 通：馀)山舞银蛇，原驰蜡象，欲与天公试比高。(原驰 一作：原驱)须晴日，看红装素裹，分外妖娆。江山如此"},
    {"title": "庆历四年春，滕子京谪守巴陵郡。", "content": "越明年，政通人和，百废具兴，乃重修岳阳楼，增其旧制，刻唐贤今人诗赋于其上，属予作文以记之。(具 通：俱)　　予观夫巴陵胜状，在洞庭一湖。衔远山，吞长江"},
    {"title": "环滁皆山也。", "content": "其西南诸峰，林壑尤美，望之蔚然而深秀者，琅琊也。山行六七里，渐闻水声潺潺，而泻出于两峰之间者，酿泉也。峰回路转，有亭翼然临于泉上者，醉翁亭也。作亭者谁？山之僧智仙也。名"},
    {"title": "崇祯五年十二月，余住西湖。", "content": "大雪三日，湖中人鸟声俱绝。是日更定矣，余拏一小舟，拥毳衣炉火，独往湖心亭看雪。雾凇沆砀，天与云与山与水，上下一白，湖上影子，惟长堤一痕、湖心亭一点、与余舟"},
    {"title": "金樽清酒斗十千，玉盘珍羞直万钱。", "content": "(羞 同：馐；直 同：值)停杯投箸不能食，拔剑四顾心茫然。欲渡黄河冰塞川，将登太行雪满山。(雪满山 一作：雪暗天)闲来垂钓碧溪上，忽复乘舟梦日边。("},
    {"title": "巴山楚水凄凉地，二十三年弃置身。", "content": "怀旧空吟闻笛赋，到乡翻似烂柯人。沉舟侧畔千帆过，病树前头万木春。今日听君歌一曲，暂凭杯酒长精神。"},
    {"title": "丙辰中秋，欢饮达旦，大醉，作此篇，兼怀子由。", "content": "明月几时有？把酒问青天。不知天上宫阙，今夕是何年。我欲乘风归去，又恐琼楼玉宇，高处不胜寒。起舞弄清影，何似在人间。(何似 一作：何时；又"},
    {"title": "次日早，起五更，在府里把担仗都摆在厅前。", "content": "老都管和两个虞候又将一小担财帛，共十一担，拣了十一个壮健的厢禁军，都做脚夫打扮。杨志戴上凉笠儿，穿着青纱衫子，系了缠带行履麻鞋，跨口腰刀，提"},
    {"title": "范进进学回家，母亲、妻子俱各欢喜。", "content": "正待烧锅做饭，只见他丈人胡屠户，手里拿着一副大肠和一瓶酒，走了进来。范进向他作揖，坐下。胡屠户道：“我自倒运，把个女儿嫁与你这现世宝，历年以来，不"},
    {"title": "却说玄德访孔明两次不遇，欲再往访之。", "content": "关公曰：“兄长两次亲往拜谒，其礼太过矣。想诸葛亮有虚名而无实学，故避而不敢见。兄何惑于斯人之甚也！”玄德曰：“不然。昔齐桓公欲见东郭野人，五反而"},
    {"title": "贾母便笑道：“这屋里窄，再往别处逛去罢。", "content": "”刘姥姥笑道：“人人都说：‘大家子住大房’，昨儿见了老太太正房，配上大箱、大柜、大桌子、大床，果然威武。那柜子比我们一间房子还大，还高。怪道"},
    {"title": "戍鼓断人行，边秋一雁声。", "content": "(边秋 一作:秋边)露从今夜白，月是故乡明。有弟皆分散，无家问死生。寄书长不达，况乃未休兵。"},
    {"title": "三年谪宦此栖迟，万古惟留楚客悲。", "content": "秋草独寻人去后，寒林空见日斜时。汉文有道恩犹薄，湘水无情吊岂知？寂寂江山摇落处，怜君何事到天涯！"},
    {"title": "一封朝奏九重天，夕贬潮州路八千。", "content": "欲为圣明除弊事，肯将衰朽惜残年！(欲为 一作：本为；圣明 一作：圣朝；肯将 一作：敢将)云横秦岭家何在？雪拥蓝关马不前。知汝远来应有意，好收吾骨瘴江"},
    {"title": "晨起动征铎，客行悲故乡。", "content": "鸡声茅店月，人迹板桥霜。槲叶落山路，枳花明驿墙。(明驿墙 一作：照驿墙)因思杜陵梦，凫雁满回塘。"},
    {"title": "一上高城万里愁，蒹葭杨柳似汀洲。", "content": "溪云初起日沉阁，山雨欲来风满楼。鸟下绿芜秦苑夕，蝉鸣黄叶汉宫秋。行人莫问当年事，故国东来渭水流。"},
    {"title": "相见时难别亦难，东风无力百花残。", "content": "春蚕到死丝方尽，蜡炬成灰泪始干。晓镜但愁云鬓改，夜吟应觉月光寒。蓬山此去无多路，青鸟殷勤为探看。(蓬山 一作：蓬莱)"},
    {"title": "树绕村庄，水满陂塘。", "content": "倚东风，豪兴徜徉。小园几许，收尽春光。有桃花红，李花白，菜花黄。远远围墙，隐隐茅堂。飏青旗，流水桥旁。偶然乘兴，步过东冈。正莺儿啼，燕儿舞，蝶儿忙。(围墙 一作"},
    {"title": "少年不识愁滋味，爱上层楼。", "content": "爱上层楼，为赋新词强说愁。 而今识尽愁滋味，欲说还休。欲说还休，却道“天凉好个秋”！"},
    {"title": "鱼，我所欲也；熊掌，亦我所欲也。", "content": "二者不可得兼，舍鱼而取熊掌者也。生，亦我所欲也；义，亦我所欲也。二者不可得兼，舍生而取义者也。生亦我所欲，所欲有甚于生者，故不为苟得也；死亦我所恶，"},
    {"title": "秦王使人谓安陵君曰：“寡人欲以五百里之地易安陵，安陵君其许寡人！”安陵君曰：“大王加惠，以大易小，甚善；虽然，受地于先王，愿终守之，弗敢易！”秦王不说。", "content": "安陵君因使唐雎使于秦。　　秦"},
    {"title": "余幼时即嗜学。", "content": "家贫，无从致书以观，每假借于藏书之家，手自笔录，计日以还。天大寒，砚冰坚，手指不可屈伸，弗之怠。录毕，走送之，不敢稍逾约。以是人多以书假余，余因得遍观群书。既加冠，益"},
    {"title": "塞下秋来风景异，衡阳雁去无留意。", "content": "四面边声连角起，千嶂里，长烟落日孤城闭。浊酒一杯家万里，燕然未勒归无计。羌管悠悠霜满地，人不寐，将军白发征夫泪。"},
    {"title": "老夫聊发少年狂，左牵黄，右擎苍，锦帽貂裘，千骑卷平冈。", "content": "为报倾城随太守，亲射虎，看孙郎。酒酣胸胆尚开张。鬓微霜，又何妨！持节云中，何日遣冯唐？会挽雕弓如满月，西北望，射天狼。"},
    {"title": "醉里挑灯看剑，梦回吹角连营。", "content": "八百里分麾下炙，五十弦翻塞外声，沙场秋点兵。马作的卢飞快，弓如霹雳弦惊。了却君王天下事，赢得生前身后名。可怜白发生！"},
    {"title": "小住京华，早又是中秋佳节。", "content": "为篱下、黄花开遍，秋容如拭。四面歌残终破楚，八年风味徒思浙。苦将侬、强派作蛾眉，殊未屑！(徒思浙 一作：独思浙)身不得，男儿列，心却比，男儿烈。算平生肝胆"},
    {"title": "十年春，齐师伐我。", "content": "公将战，曹刿请见。其乡人曰：“肉食者谋之，又何间焉？”刿曰：“肉食者鄙，未能远谋。”乃入见。问：“何以战？”公曰：“衣食所安，弗敢专也，必以分人。”对曰：“小惠未"},
    {"title": "邹忌修八尺有余，而形貌昳丽。", "content": "朝服衣冠，窥镜，谓其妻曰：“我孰与城北徐公美？”其妻曰：“君美甚，徐公何能及君也？”城北徐公，齐国之美丽者也。忌不自信，而复问其妾曰：“吾孰与徐公美？”"},
    {"title": "陈胜者，阳城人也，字涉。", "content": "吴广者，阳夏人也，字叔。陈涉少时，尝与人佣耕，辍耕之垄上，怅恨久之，曰：“苟富贵，无相忘。”佣者笑而应曰：“若为佣耕，何富贵也？”陈涉太息曰：“嗟乎！燕雀安"},
    {"title": "先帝创业未半而中道崩殂，今天下三分，益州疲弊，此诚危急存亡之秋也。", "content": "然侍卫之臣不懈于内，忠志之士忘身于外者，盖追先帝之殊遇，欲报之于陛下也。诚宜开张圣听，以光先帝遗德，恢弘志士之气，"},
    {"title": "十五从军征，八十始得归。", "content": "道逢乡里人：“家中有阿谁？”“遥看是君家，松柏冢累累。”(遥看 一作：遥望)兔从狗窦入，雉从梁上飞。中庭生旅谷，井上生旅葵。舂谷持作饭，采葵持作羹。羹饭一时"},
    {"title": "北风卷地白草折，胡天八月即飞雪。", "content": "忽如一夜春风来，千树万树梨花开。散入珠帘湿罗幕，狐裘不暖锦衾薄。将军角弓不得控，都护铁衣冷难着。(难着 一作：犹著)瀚海阑干百丈冰，愁云惨淡万里凝。"},
    {"title": "何处望神州？满眼风光北固楼。", "content": "千古兴亡多少事？悠悠。不尽长江滚滚流。年少万兜鍪，坐断东南战未休。天下英雄谁敌手？曹刘。生子当如孙仲谋。"},
    {"title": "辛苦遭逢起一经，干戈寥落四周星。", "content": "山河破碎风飘絮，身世浮沉雨打萍。惶恐滩头说惶恐，零丁洋里叹零丁。人生自古谁无死？留取丹心照汗青。"},
    {"title": "峰峦如聚，波涛如怒，山河表里潼关路。", "content": "望西都，意踌躇。(踌躇 一作：踟蹰)伤心秦汉经行处，宫阙万间都做了土。兴，百姓苦；亡，百姓苦。"},
    {"title": "三月七日，沙湖道中遇雨，雨具先去，同行皆狼狈，余独不觉。", "content": "已而遂晴，故作此(词)。莫听穿林打叶声，何妨吟啸且徐行。竹杖芒鞋轻胜马，谁怕？一蓑烟雨任平生。料峭春风吹酒醒，微冷，山头斜照"},
    {"title": "忆昔午桥桥上饮，坐中多是豪英。", "content": "长沟流月去无声。杏花疏影里，吹笛到天明。 二十余年如一梦，此身虽在堪惊。闲登小阁看新晴。古今多少事，渔唱起三更。"},
    {"title": "一轮秋影转金波，飞镜又重磨。", "content": "把酒问姮娥：被白发，欺人奈何？乘风好去，长空万里，直下看山河。斫去桂婆娑，人道是，清光更多。"},
    {"title": "身向云山那畔行，北风吹断马嘶声，深秋远塞若为情！一抹晚烟荒戍垒，半竿斜日旧关城。", "content": "古今幽恨几时平！"},
    {"title": "梅花南北路，风雨湿征衣。", "content": "出岭同谁出？归乡如此归！(如此 一作：如不)山河千古在，城郭一时非。饿死真吾志，梦中行采薇。"},
    {"title": "三年羁旅客，今日又南冠。", "content": "无限山河泪，谁言天地宽。(山河 一作：河山)已知泉路近，欲别故乡难。毅魄归来日，灵旗空际看。"},
    {"title": "骊山四顾，阿房一炬，当时奢侈今何处？只见草萧疏，水萦纡。", "content": "至今遗恨迷烟树。列国周齐秦汉楚。赢，都变做了土；输，都变做了土。"},
    {"title": "喇叭，唢呐，曲儿小腔儿大。", "content": "官船来往乱如麻，全仗你抬声价。(唢呐 一作：锁呐； 声价 一作：身价)军听了军愁，民听了民怕。哪里去辨甚么真共假？(甚么 同：什么)眼见的吹翻了这家，吹伤"},
    {"title": "独立寒秋，湘江北去，橘子洲头。", "content": "看万山红遍，层林尽染；漫江碧透，百舸争流。鹰击长空，鱼翔浅底，万类霜天竞自由。怅寥廓，问苍茫大地，谁主沉浮？携来百侣曾游。忆往昔峥嵘岁月稠。恰同学少年"},
    {"title": "采采芣苢，薄言采之。", "content": "采采芣苢，薄言有之。采采芣苢，薄言掇之。采采芣苢，薄言捋之。采采芣苢，薄言袺之。采采芣苢，薄言襭之。"},
    {"title": "田夫抛秧田妇接，小儿拔秧大儿插。", "content": "笠是兜鍪蓑是甲，雨从头上湿到胛。唤渠朝餐歇半霎，低头折腰只不答。秧根未牢莳未匝，照管鹅儿与雏鸭。"},
    {"title": "对酒当歌，人生几何！譬如朝露，去日苦多。", "content": "慨当以慷，忧思难忘。何以解忧？唯有杜康。(唯 一作：惟)青青子衿，悠悠我心。但为君故，沉吟至今。呦呦鹿鸣，食野之苹。我有嘉宾，鼓瑟吹笙。明明"},
    {"title": "少无适俗韵，性本爱丘山。", "content": "误落尘网中，一去三十年。(误落 一作：误入)羁鸟恋旧林，池鱼思故渊。开荒南野际，守拙归园田。方宅十余亩，草屋八九间。榆柳荫后檐，桃李罗堂前。暧暧远人村，依依"},
    {"title": "海客谈瀛洲，烟涛微茫信难求；越人语天姥，云霞明灭或可睹。", "content": "天姥连天向天横，势拔五岳掩赤城。天台四万八千丈，对此欲倒东南倾。(四万 一作：一万)我欲因之梦吴越，一夜飞度镜湖月。湖月照我"},
    {"title": "风急天高猿啸哀，渚清沙白鸟飞回。", "content": "无边落木萧萧下，不尽长江滚滚来。万里悲秋常作客，百年多病独登台。艰难苦恨繁霜鬓，潦倒新停浊酒杯。"},
    {"title": "元和十年，予左迁九江郡司马。", "content": "明年秋，送客湓浦口，闻舟中夜弹琵琶者，听其音，铮铮然有京都声。问其人，本长安倡女，尝学琵琶于穆、曹二善才，年长色衰，委身为贾人妇。遂命酒，使快弹数曲。曲"},
    {"title": "大江东去，浪淘尽，千古风流人物。", "content": "故垒西边，人道是，三国周郎赤壁。乱石穿空，惊涛拍岸，卷起千堆雪。(穿空 一作：崩云)江山如画，一时多少豪杰。遥想公瑾当年，小乔初嫁了，雄姿英发。羽扇"},
    {"title": "千古江山，英雄无觅，孙仲谋处。", "content": "舞榭歌台，风流总被，雨打风吹去。斜阳草树，寻常巷陌，人道寄奴曾住。想当年，金戈铁马，气吞万里如虎。元嘉草草，封狼居胥，赢得仓皇北顾。四十三年，望中犹记"},
    {"title": "寻寻觅觅，冷冷清清，凄凄惨惨戚戚。", "content": "乍暖还寒时候，最难将息。三杯两盏淡酒，怎敌他、晚来风急！雁过也，正伤心，却是旧时相识。满地黄花堆积，憔悴损，如今有谁堪摘？守着窗儿，独自怎生得黑？"},
    {"title": "君子曰：学不可以已。", "content": "　　青，取之于蓝，而青于蓝；冰，水为之，而寒于水。木直中绳，𫐓以为轮，其曲中规。虽有槁暴，不复挺者，𫐓使之然也。故木受绳则直，金就砺则利，君子博学而日参省乎"},
    {"title": "古之学者必有师。", "content": "师者，所以传道受业解惑也。人非生而知之者，孰能无惑？惑而不从师，其为惑也，终不解矣。生乎吾前，其闻道也固先乎吾，吾从而师之；生乎吾后，其闻道也亦先乎吾，吾从而师之。"},
    {"title": "壬戌之秋，七月既望，苏子与客泛舟游于赤壁之下。", "content": "清风徐来，水波不兴。举酒属客，诵明月之诗，歌窈窕之章。少焉，月出于东山之上，徘徊于斗牛之间。白露横江，水光接天。纵一苇之所如，凌万顷之"},
    {"title": "泰山之阳，汶水西流；其阴，济水东流。", "content": "阳谷皆入汶，阴谷皆入济。当其南北分者，古长城也。最高日观峰，在长城南十五里。　　余以乾隆三十九年十二月，自京师乘风雪，历齐河、长清，穿泰山西北谷"},
    {"title": "静女其姝，俟我于城隅。", "content": "爱而不见，搔首踟蹰。静女其娈，贻我彤管。彤管有炜，说怿女美。自牧归荑，洵美且异。匪女之为美，美人之贻。"},
    {"title": "涉江采芙蓉，兰泽多芳草。", "content": "采之欲遗谁？所思在远道。还顾望旧乡，长路漫浩浩。同心而离居，忧伤以终老。"},
    {"title": "春花秋月何时了？往事知多少。", "content": "小楼昨夜又东风，故国不堪回首月明中。雕栏玉砌应犹在，只是朱颜改。问君能有几多愁？恰似一江春水向东流。(栏 一作：阑)"},
    {"title": "纤云弄巧，飞星传恨，银汉迢迢暗度。", "content": "金风玉露一相逢，便胜却人间无数。柔情似水，佳期如梦，忍顾鹊桥归路。两情若是久长时，又岂在朝朝暮暮。"},
    {"title": "子路、曾皙、冉有、公西华侍坐。", "content": "　　子曰：“以吾一日长乎尔，毋吾以也。居则曰：‘不吾知也。’如或知尔，则何以哉？”　　子路率尔而对曰：“千乘之国，摄乎大国之间，加之以师旅，因之以饥馑"},
    {"title": "齐宣王问曰：“齐桓、晋文之事可得闻乎？”　　孟子对曰：“仲尼之徒无道桓文之事者，是以后世无传焉，臣未之闻也。", "content": "无以，则王乎？”　　曰：“德何如则可以王矣？”　　曰：“保民而王，莫之能"},
    {"title": "庖丁为文惠君解牛，手之所触，肩之所倚，足之所履，膝之所踦，砉然向然，奏刀騞然，莫不中音。", "content": "合于《桑林》之舞，乃中《经首》之会。　　文惠君曰：“嘻，善哉！技盖至此乎？”　　庖丁释刀对曰"},
    {"title": "晋侯、秦伯围郑，以其无礼于晋，且贰于楚也。", "content": "晋军函陵，秦军氾南。　　佚之狐言于郑伯曰：“国危矣，若使烛之武见秦君，师必退。”公从之。辞曰：“臣之壮也，犹不如人；今老矣，无能为也已。”"},
    {"title": "行略定秦地。", "content": "函谷关有兵守关，不得入。又闻沛公已破咸阳，项羽大怒，使当阳君等击关。项羽遂入，至于戏西。沛公军霸上，未得与项羽相见。沛公左司马曹无伤，使人言于项羽曰：“沛公欲王关中，使"},
    {"title": "（外扮监斩官上，云）下官监斩官是也。", "content": "今日处决犯人，着做公的把住巷口，休放往来人闲走。（净扮公人鼓三通、锣三下科。刽子磨旗、提刀，押正旦带枷上）（刽子云）行动些，行动些，监斩官去法场"},
    {"title": "臣闻吏议逐客，窃以为过矣。", "content": "昔缪公求士，西取由余于戎，东得百里奚于宛，迎蹇叔于宋，来丕豹、公孙支于晋。此五子者，不产于秦，而缪公用之，并国二十，遂霸西戎。孝公用商鞅之法，移风易俗，民"},
    {"title": "意映卿卿如晤，吾今以此书与汝永别矣！吾作此书时，尚是世中一人；汝看此书时，吾已成为阴间一鬼。", "content": "吾作此书，泪珠和笔墨齐下，不能竟书而欲搁笔，又恐汝不察吾衷，谓吾忍舍汝而死，谓吾不知汝之"},
    {"title": "宣德间，宫中尚促织之戏，岁征民间。", "content": "此物故非西产；有华阴令欲媚上官，以一头进，试使斗而才，因责常供。令以责之里正。市中游侠儿得佳者笼养之，昂其直，居为奇货。里胥猾黠，假此科敛丁口，每"},
    {"title": "臣闻求木之长者，必固其根本；欲流之远者，必浚其泉源；思国之安者，必积其德义。", "content": "源不深而望流之远，根不固而求木之长，德不厚而思国之理，臣虽下愚，知其不可，而况于明哲乎！人君当神器之重，"},
    {"title": "某启：昨日蒙教，窃以为与君实游处相好之日久，而议事每不合，所操之术多异故也。", "content": "虽欲强聒，终必不蒙见察，故略上报，不复一一自辨。重念蒙君实视遇厚，于反覆不宜卤莽，故今具道所以，冀君实或"},
    {"title": "六王毕，四海一，蜀山兀，阿房出。", "content": "覆压三百余里，隔离天日。骊山北构而西折，直走咸阳。二川溶溶，流入宫墙。五步一楼，十步一阁；廊腰缦回，檐牙高啄；各抱地势，钩心斗角。盘盘焉，囷囷焉，蜂"},
    {"title": "六国破灭，非兵不利，战不善，弊在赂秦。", "content": "赂秦而力亏，破灭之道也。或曰：六国互丧，率赂秦耶？曰：不赂者以赂者丧。盖失强援，不能独完。故曰：弊在赂秦也。　　秦以攻取之外，小则获邑，大则得"},
    {"title": "昔闻洞庭水，今上岳阳楼。", "content": "吴楚东南坼，乾坤日夜浮。亲朋无一字，老病有孤舟。戎马关山北，凭轩涕泗流。"},
    {"title": "登临送目，正故国晚秋，天气初肃。", "content": "千里澄江似练，翠峰如簇。归帆去棹残阳里，背西风，酒旗斜矗。彩舟云淡，星河鹭起，画图难足。(归帆 一作：征帆)念往昔，繁华竞逐。叹门外楼头，悲恨相续。"},
    {"title": "洞庭青草，近中秋，更无一点风色。", "content": "玉鉴琼田三万顷，着我扁舟一叶。素月分辉，明河共影，表里俱澄澈。悠然心会，妙处难与君说。(着 同：著；玉鉴 一作：玉界；明河 一作 银河)应念岭海经年"},
    {"title": "原来姹紫嫣红开遍，似这般都付与断井颓垣。", "content": "良辰美景奈何天，赏心乐事谁家院！朝飞暮卷，云霞翠轩；雨丝风片，烟波画船，锦屏人忒看的这韶光贱！"},
    {"title": "子曰：“君子食无求饱，居无求安，敏于事而慎于言，就有道而正焉，可谓好学也已。", "content": "”(《学而》) 　　子曰：“人而不仁，如礼何？ 人而不仁，如乐何？”(《八佾》) 　　子曰：“朝闻道，夕"},
    {"title": "大学之道，在明明德，在亲民，在止于至善。", "content": "知止而后有定，定而后能静，静而后能安，安而后能虑，虑而后能得。 物有本末，事有终始。知所先后，则近道矣。　　古之欲明明德于天下者，先治其国。"},
    {"title": "孟子曰：“人皆有不忍人之心。", "content": "先王有不忍人之心，斯有不忍人之政矣；以不忍人之心，行不忍人之政，治天下可运之掌上。所以谓人皆有不忍人之心者：今人乍见孺子将入于井，皆有怵惕恻隐之心；非所"},
    {"title": "三十辐共一毂，当其无，有车之用。", "content": "埏埴以为器，当其无，有器之用。凿户牖以为室，当其无，有室之用。故有之以为利，无之以为用。(第十一章)　　企者不立，跨者不行，自见者不明，自是者不彰，"},
    {"title": "惠子谓庄子曰：“魏王贻我大瓠之种，我树之成而实五石。", "content": "以盛水浆，其坚不能自举也。剖之以为瓢，则瓠落无所容。非不呺然大也，吾为其无用而掊之。”庄子曰：“夫子固拙于用大矣。宋人有善为不龟"},
    {"title": "圣人以治天下为事者也，必知乱之所自起，焉能治之；不知乱之所自起，则不能治。", "content": "譬之如医之攻人之疾者然，必知疾之所自起，焉能攻之；不知疾之所自起，则弗能攻。治乱者何独不然？必知乱之所自起"},
    {"title": "岂曰无衣？与子同袍。", "content": "王于兴师，修我戈矛，与子同仇！岂曰无衣？与子同泽。王于兴师，修我矛戟，与子偕作！岂曰无衣？与子同裳。王于兴师，修我甲兵，与子偕行！"},
    {"title": "春江潮水连海平，海上明月共潮生。", "content": "滟滟随波千万里，何处春江无月明。江流宛转绕芳甸，月照花林皆似霰。空里流霜不觉飞，汀上白沙看不见。江天一色无纤尘，皎皎空中孤月轮。江畔何人初见月？江月"},
    {"title": "君不见黄河之水天上来，奔流到海不复回。", "content": "君不见高堂明镜悲白发，朝如青丝暮成雪。人生得意须尽欢，莫使金樽空对月。天生我材必有用，千金散尽还复来。烹羊宰牛且为乐，会须一饮三百杯。岑夫子，"},
    {"title": "十年生死两茫茫，不思量，自难忘。", "content": "千里孤坟，无处话凄凉。纵使相逢应不识，尘满面，鬓如霜。夜来幽梦忽还乡，小轩窗，正梳妆。相顾无言，惟有泪千行。料得年年肠断处，明月夜，短松冈。"},
    {"title": "屈原者，名平，楚之同姓也。", "content": "为楚怀王左徒。博闻强志，明于治乱，娴于辞令。入则与王图议国事，以出号令；出则接遇宾客，应对诸侯。王甚任之。　　上官大夫与之同列，争宠而心害其能。怀王使屈原"},
    {"title": "武字子卿，少以父任，兄弟并为郎。", "content": "稍迁至栘中厩监。时汉连伐胡，数通使相窥观。匈奴留汉使郭吉、路充国等，前后十余辈。匈奴使来，汉亦留之以相当。天汉元年，且鞮侯单于初立，恐汉袭之，乃曰："},
    {"title": "秦孝公据崤函之固，拥雍州之地，君臣固守以窥周室，有席卷天下，包举宇内，囊括四海之意，并吞八荒之心。", "content": "当是时也，商君佐之，内立法度，务耕织，修守战之具，外连衡而斗诸侯。于是秦人拱手而取"},
    {"title": "呜呼！盛衰之理，虽曰天命，岂非人事哉！原庄宗之所以得天下，与其所以失之者，可以知之矣。", "content": "　　世言晋王之将终也，以三矢赐庄宗而告之曰：“梁，吾仇也；燕王，吾所立；契丹与吾约为兄弟；而皆"},
    {"title": "开元二十六年，客有从元戎出塞而还者，作《燕歌行》以示，适感征戍之事，因而和焉。", "content": "汉家烟尘在东北，汉将辞家破残贼。男儿本自重横行，天子非常赐颜色。摐金伐鼓下榆关，旌旆逶迤碣石间。(摐"},
    {"title": "吴丝蜀桐张高秋，空山凝云颓不流。", "content": "江娥啼竹素女愁，李凭中国弹箜篌。昆山玉碎凤凰叫，芙蓉泣露香兰笑。十二门前融冷光，二十三丝动紫皇。女娲炼石补天处，石破天惊逗秋雨。梦入神山教神妪，老鱼"},
    {"title": "锦瑟无端五十弦，一弦一柱思华年。", "content": "庄生晓梦迷蝴蝶，望帝春心托杜鹃。沧海月明珠有泪，蓝田日暖玉生烟。此情可待成追忆，只是当时已惘然。"},
    {"title": "早岁那知世事艰，中原北望气如山。", "content": "楼船夜雪瓜洲渡，铁马秋风大散关。塞上长城空自许，镜中衰鬓已先斑。出师一表真名世，千载谁堪伯仲间！"},
    {"title": "氓之蚩蚩，抱布贸丝。", "content": "匪来贸丝，来即我谋。送子涉淇，至于顿丘。匪我愆期，子无良媒。将子无怒，秋以为期。乘彼垝垣，以望复关。不见复关，泣涕涟涟。既见复关，载笑载言。尔卜尔筮，体无咎言。"},
    {"title": "帝高阳之苗裔兮，朕皇考曰伯庸。", "content": "摄提贞于孟陬兮，惟庚寅吾以降。皇览揆余初度兮，肇锡余以嘉名：名余曰正则兮，字余曰灵均。纷吾既有此内美兮，又重之以修能。扈江离与辟芷兮，纫秋兰以为佩。汩"},
    {"title": "汉末建安中，庐江府小吏焦仲卿妻刘氏，为仲卿母所遣，自誓不嫁。", "content": "其家逼之，乃投水而死。仲卿闻之，亦自缢于庭树。时人伤之，为诗云尔。　　孔雀东南飞，五里一徘徊。　　“十三能织素，十四学裁"},
    {"title": "噫吁嚱，危乎高哉！蜀道之难，难于上青天！蚕丛及鱼凫，开国何茫然！尔来四万八千岁，不与秦塞通人烟。", "content": "西当太白有鸟道，可以横绝峨眉巅。地崩山摧壮士死，然后天梯石栈相钩连。上有六龙回日之高"},
    {"title": "丞相祠堂何处寻？锦官城外柏森森。", "content": "映阶碧草自春色，隔叶黄鹂空好音。三顾频烦天下计，两朝开济老臣心。出师未捷身先死，长使英雄泪满襟。"},
    {"title": "东南形胜，三吴都会，钱塘自古繁华。", "content": "烟柳画桥，风帘翠幕，参差十万人家。云树绕堤沙，怒涛卷霜雪，天堑无涯。市列珠玑，户盈罗绮，竞豪奢。(三吴 一作：江吴)重湖叠𪩘清嘉，有三秋桂子，十"},
    {"title": "淳熙丙申至日，予过维扬。", "content": "夜雪初霁，荠麦弥望。入其城，则四顾萧条，寒水自碧，暮色渐起，戍角悲吟。予怀怆然，感慨今昔，因自度此曲。千岩老人以为有《黍离》之悲也。淮左名都，竹西佳处，解鞍"},
    {"title": "臣密言：臣以险衅，夙遭闵凶。", "content": "生孩六月，慈父见背；行年四岁，舅夺母志。祖母刘愍臣孤弱，躬亲抚养。臣少多疾病，九岁不行，零丁孤苦，至于成立。既无伯叔，终鲜兄弟，门衰祚薄，晚有儿息。外无"},
    {"title": "项脊轩，旧南阁子也。", "content": "室仅方丈，可容一人居。百年老屋，尘泥渗漉，雨泽下注；每移案，顾视无可置者。又北向，不能得日，日过午已昏。余稍为修葺，使不上漏。前辟四窗，垣墙周庭，以当南日，日影"},
    {"title": "永和九年，岁在癸丑，暮春之初，会于会稽山阴之兰亭，修禊事也。", "content": "群贤毕至，少长咸集。此地有崇山峻岭，茂林修竹；又有清流激湍，映带左右，引以为流觞曲水，列坐其次。虽无丝竹管弦之盛，一觞一"},
    {"title": "余家贫，耕植不足以自给。", "content": "幼稚盈室，瓶无储粟，生生所资，未见其术。亲故多劝余为长吏，脱然有怀，求之靡途。会有四方之事，诸侯以惠爱为德，家叔以余贫苦，遂见用于小邑。于时风波未静，心惮远"},
    {"title": "郭橐驼，不知始何名。", "content": "病偻，隆然伏行，有类橐驼者，故乡人号之“驼”。驼闻之曰：“甚善。名我固当。”因舍其名，亦自谓“橐驼”云。　　其乡曰丰乐乡，在长安西。驼业种树，凡长安豪富人为观游"},
    {"title": "《水经》云：“彭蠡之口有石钟山焉。", "content": "”郦元以为下临深潭，微风鼓浪，水石相搏，声如洪钟。是说也，人常疑之。今以钟磬置水中，虽大风浪不能鸣也，而况石乎！至唐李渤始访其遗踪，得双石于潭上，"},
    {"title": "泻水置平地，各自东西南北流。", "content": "人生亦有命，安能行叹复坐愁？酌酒以自宽，举杯断绝歌路难。心非木石岂无感，吞声踯躅不敢言。"},
    {"title": "舍南舍北皆春水，但见群鸥日日来。", "content": "花径不曾缘客扫，蓬门今始为君开。盘飧市远无兼味，樽酒家贫只旧醅。肯与邻翁相对饮，隔篱呼取尽余杯。"},
    {"title": "痴儿了却公家事，快阁东西倚晚晴。", "content": "落木千山天远大，澄江一道月分明。朱弦已为佳人绝，青眼聊因美酒横。万里归船弄长笛，此心吾与白鸥盟。"},
    {"title": "世味年来薄似纱，谁令骑马客京华。", "content": "小楼一夜听春雨，深巷明朝卖杏花。矮纸斜行闲作草，晴窗细乳戏分茶。素衣莫起风尘叹，犹及清明可到家。"},
    {"title": "汉皇重色思倾国，御宇多年求不得。", "content": "杨家有女初长成，养在深闺人未识。天生丽质难自弃，一朝选在君王侧。回眸一笑百媚生，六宫粉黛无颜色。春寒赐浴华清池，温泉水滑洗凝脂。侍儿扶起娇无力，始是"},
    {"title": "帝子降兮北渚，目眇眇兮愁予。", "content": "袅袅兮秋风，洞庭波兮木叶下。(袅袅 一作：嫋嫋)登白薠兮骋望，与佳期兮夕张。鸟何萃兮蘋中，罾何为兮木上？沅有芷兮澧有兰，思公子兮未敢言。(芷兮 一作：茝"},
    {"title": "夜中不能寐，起坐弹鸣琴。", "content": "薄帷鉴明月，清风吹我襟。孤鸿号外野，翔鸟鸣北林。(翔鸟 一作：朔鸟)徘徊将何见？忧思独伤心。"},
    {"title": "白日沦西河，素月出东岭。", "content": "(西河 一作：西阿)遥遥万里晖，荡荡空中景。(晖 一作：辉)风来入房户，夜中枕席冷。气变悟时易，不眠知夕永。欲言无予和，挥杯劝孤影。日月掷人去，有志不获骋。"},
    {"title": "越王勾践破吴归，义士还家尽锦衣。", "content": "(义士 一作：战士)宫女如花满春殿，只今惟有鹧鸪飞。"},
    {"title": "红藕香残玉簟秋。", "content": "轻解罗裳，独上兰舟。云中谁寄锦书来？雁字回时，月满西楼。花自飘零水自流。一种相思，两处闲愁。此情无计可消除，才下眉头，却上心头。"},
    {"title": "别肠转如轮，一刻既万周。", "content": "眼见双轮驰，益增中心忧。古亦有山川，古亦有车舟。车舟载离别，行止犹自由。今日舟与车，并力生离愁。明知须臾景，不许稍绸缪。钟声一及时，顷刻不少留。虽有万钧柁，"},
    {"title": "山寺钟鸣昼已昏，渔梁渡头争渡喧。", "content": "人随沙岸向江村，余亦乘舟归鹿门。鹿门月照开烟树，忽到庞公栖隐处。岩扉松径长寂寥，惟有幽人自来去。"},
    {"title": "昔闻洞庭水，今上岳阳楼。", "content": "吴楚东南坼，乾坤日夜浮。亲朋无一字，老病有孤舟。戎马关山北，凭轩涕泗流。"},
    {"title": "人人尽说江南好，游人只合江南老。", "content": "春水碧于天，画船听雨眠。垆边人似月，皓腕凝霜雪。未老莫还乡，还乡须断肠。"},
    {"title": "积雨空林烟火迟，蒸藜炊黍饷东菑。", "content": "漠漠水田飞白鹭，阴阴夏木啭黄鹂。山中习静观朝槿，松下清斋折露葵。野老与人争席罢，海鸥何事更相疑。"},
    {"title": "细草微风岸，危樯独夜舟。", "content": "星垂平野阔，月涌大江流。名岂文章著，官应老病休。飘飘何所似，天地一沙鸥。"},
    {"title": "东风知我欲山行，吹断檐间积雨声。", "content": "岭上晴云披絮帽，树头初日挂铜钲。野桃含笑竹篱短，溪柳自摇沙水清。西崦人家应最乐，煮芹烧笋饷春耕。"},
    {"title": "岁暮阴阳催短景，天涯霜雪霁寒宵。", "content": "五更鼓角声悲壮，三峡星河影动摇。野哭千家闻战伐，夷歌数处起渔樵。(千家 一作：几家)卧龙跃马终黄土，人事音书漫寂寥。(音书 一作：依依)"},
    {"title": "燎沉香，消溽暑。", "content": "鸟雀呼晴，侵晓窥檐语。叶上初阳干宿雨，水面清圆，一一风荷举。故乡遥，何日去？家住吴门，久作长安旅。五月渔郎相忆否？小楫轻舟，梦入芙蓉浦。"},
    {"title": "操吴戈兮被犀甲，车错毂兮短兵接。", "content": "旌蔽日兮敌若云，矢交坠兮士争先。凌余阵兮躐余行，左骖殪兮右刃伤。霾两轮兮絷四马，援玉枹兮击鸣鼓。天时怼兮威灵怒，严杀尽兮弃原野。(怼 一作：坠；野"},
    {"title": "城上高楼接大荒，海天愁思正茫茫。", "content": "惊风乱飐芙蓉水，密雨斜侵薜荔墙。岭树重遮千里目，江流曲似九回肠。共来百越文身地，犹自音书滞一乡。"},
    {"title": "小山重叠金明灭，鬓云欲度香腮雪。", "content": "懒起画蛾眉，弄妆梳洗迟。照花前后镜，花面交相映。新帖绣罗襦，双双金鹧鸪。(帖 一作：贴)"},
    {"title": "【哨遍】社长排门告示，但有的差使无推故。", "content": "这差使不寻俗，一壁厢纳草也根，一边又要差夫，索应付。又是言车驾，都说是銮舆，今日还乡故。王乡老执定瓦台盘，赵忙郎抱着酒葫芦。新刷来的头巾，恰"},
    {"title": "八月一日，过烽火矶。", "content": "南朝自武昌至京口，列置烽燧，此山当是其一也。自舟中望山，突兀而已。及抛江过其下，嵌岩窦穴，怪奇万状，色泽莹润，亦与它石迥异。又有一石，不附山，杰然特起，高百余尺"},
    {"title": "项王军壁垓下，兵少食尽，汉军及诸侯兵围之数重。", "content": "夜闻汉军四面皆楚歌，项王乃大惊曰：“汉皆已得楚乎？是何楚人之多也！”项王则夜起，饮帐中。有美人名虞，常幸从；骏马名骓，常骑之。于是项王"},
    {"title": "方山子，光、黄间隐人也。", "content": "少时慕朱家、郭解为人，闾里之侠皆宗之。稍壮，折节读书，欲以此驰骋当世，然终不遇。晚乃遁于光、黄间，曰岐亭。庵居蔬食，不与世相闻；弃车马，毁冠服，徒步往来山中"},
    {"title": "庚戌十一月，予自广陵归，与陈子灿同舟。", "content": "子灿年二十八，好武事，予授以左氏兵谋兵法，因问：“数游南北，逢异人乎？”子灿为述大铁椎，作《大铁椎传》。　　大铁椎，不知何许人。北平陈子灿省兄"},
    {"title": "年、月、日，季父愈闻汝丧之七日，乃能衔哀致诚，使建中远具时羞之奠，告汝十二郎之灵：　　呜呼！吾少孤，及长，不省所怙，惟兄嫂是依。", "content": "中年兄殁南方，吾与汝俱幼，从嫂归葬河阳。既又与汝就食"},
    {"title": "康熙五十一年三月，余在刑部狱，见死而由窦出者，日四三人。", "content": "有洪洞令杜君者，作而言曰：“此疫作也。今天时顺正，死者尚稀，往岁多至日数十人。”余叩所以。杜君曰：“是疾易传染，遘者虽戚属不"},
    {"title": "陶庵国破家亡，无所归止。", "content": "披发入山，駴駴为野人。故旧见之，如毒药猛兽，愕窒不敢与接。作《自挽诗》，每欲引决，因《石匮书》未成，尚视息人世。然瓶粟屡罄，不能举火。始知首阳二老，直头饿死"},
    {"title": "夫天地者，万物之逆旅也；光阴者，百代之过客也。", "content": "而浮生若梦，为欢几何？古人秉烛夜游，良有以也。况阳春召我以烟景，大块假我以文章。会桃花之芳园，序天伦之乐事。群季俊秀，皆为惠连；吾人咏"},
    {"title": "黄州东南三十里为沙湖，亦曰螺师店。", "content": "予买田其间，因往相田，得疾。闻麻桥人庞安常善医而聋，遂往求疗。安常虽聋，而颖悟绝人，以纸画字，书不数字，辄深了人意。余戏之曰：“余以手为口，君以眼"},
    {"title": "苦斋者，章溢先生隐居之室也。", "content": "室十有二楹，覆之以茆，在匡山之巅。匡山在处之龙泉县西南二百里，剑溪之水出焉。山四面峭壁拔起，岩崿皆苍石，岸外而臼中。其下惟白云，其上多北风。风从北来者，"},
    {"title":"关关雎鸠，在河之洲。","content":"窈窕淑女，君子好逑。"},
    {"title":"参差荇菜，左右流之。","content":"窈窕淑女，寤寐求之。"},
    {"title":"求之不得，寤寐思服。","content":"悠哉悠哉，辗转反侧。"},
    {"title":"参差荇菜，左右采之。","content":"窈窕淑女，琴瑟友之。"},
    {"title":"参差荇菜，左右芼之。","content":"窈窕淑女，钟鼓乐之。"},
    {"title":"君子曰：学不可以已。","content":"青，取之于蓝，而青于蓝；冰，水为之，而寒于水。木直中绳，𫐓以为轮，其曲中规。虽有槁暴，不复挺者，𫐓使之然也。故木受绳则直，金就砺则利，君子博学而日参省乎己，则知明而行无过矣。"},
    {"title":"故不登高山，不知天之高也；","content":"不临深溪，不知地之厚也；不闻先王之遗言，不知学问之大也。干、越、夷、貉之子，生而同声，长而异俗，教使之然也。诗曰：“嗟尔君子，无恒安息。靖共尔位，好是正直。神之听之，介尔景福。”神莫大于化道，福莫长于无祸。"},
    {"title":"吾尝终日而思矣，不如须臾之所学也；","content":"吾尝跂而望矣，不如登高之博见也。登高而招，臂非加长也，而见者远；顺风而呼，声非加疾也，而闻者彰。假舆马者，非利足也，而致千里；假舟楫者，非能水也，而绝江河。君子生非异也，善假于物也。"},
    {"title":"蒹葭苍苍，白露为霜。","content":"所谓伊人，在水一方。溯洄从之，道阻且长。溯游从之，宛在水中央。"},
    {"title":"蒹葭萋萋，白露未晞。","content":"所谓伊人，在水之湄。溯洄从之，道阻且跻。溯游从之，宛在水中坻。"},
    {"title":"蒹葭采采，白露未已。","content":"所谓伊人，在水之涘。溯洄从之，道阻且右。溯游从之，宛在水中沚。"},
    {"title":"氓之蚩蚩，抱布贸丝。","content":"匪来贸丝，来即我谋。送子涉淇，至于顿丘。匪我愆期，子无良媒。将子无怒，秋以为期。"},
    {"title":"乘彼垝垣，以望复关。","content":"不见复关，泣涕涟涟。既见复关，载笑载言。尔卜尔筮，体无咎言。以尔车来，以我贿迁。"},
    {"title":"桑之未落，其叶沃若。","content":"于嗟鸠兮，无食桑葚！于嗟女兮，无与士耽！士之耽兮，犹可说也。女之耽兮，不可说也。"},
    {"title":"桑之落矣，其黄而陨。","content":"自我徂尔，三岁食贫。淇水汤汤，渐车帷裳。女也不爽，士贰其行。士也罔极，二三其德。"},
    {"title":"三岁为妇，靡室劳矣。","content":"夙兴夜寐，靡有朝矣。言既遂矣，至于暴矣。兄弟不知，咥其笑矣。静言思之，躬自悼矣。"},
    {"title":"及尔偕老，老使我怨。","content":"淇则有岸，隰则有泮。总角之宴，言笑晏晏。信誓旦旦，不思其反。反是不思，亦已焉哉！"},
    {"title":"帝高阳之苗裔兮，","content":"朕皇考曰伯庸。"},
    {"title":"摄提贞于孟陬兮，","content":"惟庚寅吾以降。"},
    {"title":"皇览揆余初度兮，","content":"肇锡余以嘉名。"},
    {"title":"名余曰正则兮，","content":"字余曰灵均。"},
    {"title":"纷吾既有此内美兮，","content":"又重之以修能。"},
    {"title":"扈江离与辟芷兮，","content":"纫秋兰以为佩。"},
    {"title":"汩余若将不及兮，","content":"恐年岁之不吾与。"},
    {"title":"朝搴阰之木兰兮，","content":"夕揽洲之宿莽。"},
    {"title":"日月忽其不淹兮，","content":"春与秋其代序。"},
    {"title":"惟草木之零落兮，","content":"恐美人之迟暮。"},
    {"title":"不抚壮而弃秽兮，","content":"何不改此度？"},
    {"title":"乘骐骥以驰骋兮，","content":"来吾道夫先路！"},
    {"title":"昔三后之纯粹兮，","content":"固众芳之所在。"},
    {"title":"杂申椒与菌桂兮，","content":"岂惟纫夫蕙茝！"},
    {"title":"彼尧舜之耿介兮，","content":"既遵道而得路。"},
    {"title":"何桀纣之猖披兮，","content":"夫唯捷径以窘步。"},
    {"title":"惟夫党人之偷乐兮，","content":"路幽昧以险隘。"},
    {"title":"岂余身之惮殃兮，","content":"恐皇舆之败绩！"},
    {"title":"忽奔走以先后兮，","content":"及前王之踵武。"},
    {"title":"荃不察余之中情兮，","content":"反信谗而齌怒。"},
    {"title":"余固知謇謇之为患兮，","content":"忍而不能舍也。"},
    {"title":"指九天以为正兮，","content":"夫唯灵修之故也。"},
    {"title":"曰黄昏以为期兮，","content":"羌中道而改路！"},
    {"title":"初既与余成言兮，","content":"后悔遁而有他。"},
    {"title":"余既不难夫离别兮，","content":"伤灵修之数化。"},
    {"title":"余既滋兰之九畹兮，","content":"又树蕙之百亩。"},
    {"title":"畦留夷与揭车兮，","content":"杂杜衡与芳芷。"},
    {"title":"冀枝叶之峻茂兮，","content":"愿俟时乎吾将刈。"},
    {"title":"虽萎绝其亦何伤兮，","content":"哀众芳之芜秽。"},
    {"title":"众皆竞进以贪婪兮，","content":"凭不厌乎求索。"},
    {"title":"羌内恕己以量人兮，","content":"各兴心而嫉妒。"},
    {"title":"忽驰骛以追逐兮，","content":"非余心之所急。"},
    {"title":"老冉冉其将至兮，","content":"恐修名之不立。"},
    {"title":"朝饮木兰之坠露兮，","content":"夕餐秋菊之落英。"},
    {"title":"苟余情其信姱以练要兮，","content":"长顑颔亦何伤。"},
    {"title":"掔木根以结茝兮，","content":"贯薜荔之落蕊。"},
    {"title":"矫菌桂以纫蕙兮，","content":"索胡绳之纚纚。"},
    {"title":"謇吾法夫前修兮，","content":"非世俗之所服。"},
    {"title":"虽不周于今之人兮，","content":"愿依彭咸之遗则。"},
    {"title":"长太息以掩涕兮，","content":"哀民生之多艰。"},
    {"title":"余虽好修姱以鞿羁兮，","content":"謇朝谇而夕替。"},
    {"title":"既替余以蕙纕兮，","content":"又申之以揽茝。"},
    {"title":"亦余心之所善兮，","content":"虽九死其犹未悔。"},
    {"title":"怨灵修之浩荡兮，","content":"终不察夫民心。"},
    {"title":"众女嫉余之蛾眉兮，","content":"谣诼谓余以善淫。"},
    {"title":"固时俗之工巧兮，","content":"偭规矩而改错。"},
    {"title":"背绳墨以追曲兮，","content":"竞周容以为度。"},
    {"title":"忳郁邑余侘傺兮，","content":"吾独穷困乎此时也。"},
    {"title":"宁溘死以流亡兮，","content":"余不忍为此态也。"},
    {"title":"鸷鸟之不群兮，","content":"自前世而固然。"},
    {"title":"何方圜之能周兮，","content":"夫孰异道而相安？"},
    {"title":"屈心而抑志兮，","content":"忍尤而攘诟。"},
    {"title":"伏清白以死直兮，","content":"固前圣之所厚。"},
    {"title":"悔相道之不察兮，","content":"延伫乎吾将反。"},
    {"title":"回朕车以复路兮，","content":"及行迷之未远。"},
    {"title":"步余马于兰皋兮，","content":"驰椒丘且焉止息。"},
    {"title":"进不入以离尤兮，","content":"退将复修吾初服。"},
    {"title":"制芰荷以为衣兮，","content":"集芙蓉以为裳。"},
    {"title":"不吾知其亦已兮，","content":"苟余情其信芳。"},
    {"title":"高余冠之岌岌兮，","content":"长余佩之陆离。"},
    {"title":"芳与泽其杂糅兮，","content":"唯昭质其犹未亏。"},
    {"title":"忽反顾以游目兮，","content":"将往观乎四荒。"},
    {"title":"佩缤纷其繁饰兮，","content":"芳菲菲其弥章。"},
    {"title":"民生各有所乐兮，","content":"余独好修以为常。"},
    {"title":"虽体解吾犹未变兮，","content":"岂余心之可惩。"},
    {"title":"女媭之婵媛兮，","content":"申申其詈予，曰："},
    {"title":"鲧婞直以亡身兮，","content":"终然夭乎羽之野。"},
    {"title":"汝何博謇而好修兮，","content":"纷独有此姱节？"},
    {"title":"薋菉葹以盈室兮，","content":"判独离而不服。"},
    {"title":"众不可户说兮，","content":"孰云察余之中情？"},
    {"title":"世并举而好朋兮，","content":"夫何茕独而不予听？"},
    {"title":"依前圣以节中兮，","content":"喟凭心而历兹。"},
    {"title":"济沅湘以南征兮，","content":"就重华而陈词："},
    {"title":"启《九辩》与《九歌》兮，","content":"夏康娱以自纵。"},
    {"title":"不顾难以图后兮，","content":"五子用失乎家衖。"},
    {"title":"羿淫游以佚畋兮，","content":"又好射夫封狐。"},
    {"title":"固乱流其鲜终兮，","content":"浞又贪夫厥家。"},
    {"title":"浇身被服强圉兮，","content":"纵欲而不忍。"},
    {"title":"日康娱而自忘兮，","content":"厥首用夫颠陨。"},
    {"title":"夏桀之常违兮，","content":"乃遂焉而逢殃。"},
    {"title":"后辛之菹醢兮，","content":"殷宗用而不长。"},
    {"title":"汤禹俨而祗敬兮，","content":"周论道而莫差。"},
    {"title":"举贤才而授能兮，","content":"循绳墨而不颇。"},
    {"title":"皇天无私阿兮，","content":"览民德焉错辅。"},
    {"title":"夫维圣哲以茂行兮，","content":"苟得用此下土。"},
    {"title":"瞻前而顾后兮，","content":"相观民之计极。"},
    {"title":"夫孰非义而可用兮？","content":"孰非善而可服？"},
    {"title":"阽余身而危死兮，","content":"览余初其犹未悔。"},
    {"title":"不量凿而正枘兮，","content":"固前修以菹醢。"},
    {"title":"曾歔欷余郁邑兮，","content":"哀朕时之不当。"},
    {"title":"揽茹蕙以掩涕兮，","content":"沾余襟之浪浪。"},
    {"title":"跪敷衽以陈辞兮，","content":"耿吾既得此中正。"},
    {"title":"驷玉虬以椉鹥兮，","content":"溘埃风余上征。"},
    {"title":"朝发轫于苍梧兮，","content":"夕余至乎县圃。"},
    {"title":"欲少留此灵琐兮，","content":"日忽忽其将暮。"},
    {"title":"吾令羲和弭节兮，","content":"望崦嵫而勿迫。"},
    {"title":"路曼曼其修远兮，","content":"吾将上下而求索。"},
    {"title":"饮余马于咸池兮，","content":"总余辔乎扶桑。"},
    {"title":"折若木以拂日兮，","content":"聊逍遥以相羊。"},
    {"title":"前望舒使先驱兮，","content":"后飞廉使奔属。"},
    {"title":"鸾皇为余先戒兮，","content":"雷师告余以未具。"},
    {"title":"吾令凤鸟飞腾兮，","content":"继之以日夜。"},
    {"title":"飘风屯其相离兮，","content":"帅云霓而来御。"},
    {"title":"纷总总其离合兮，","content":"斑陆离其上下。"},
    {"title":"吾令帝阍开关兮，","content":"倚阊阖而望予。"},
    {"title":"时暧暧其将罢兮，","content":"结幽兰而延伫。"},
    {"title":"世溷浊而不分兮，","content":"好蔽美而嫉妒。"},
    {"title":"朝吾将济于白水兮，","content":"登阆风而绁马。"},
    {"title":"忽反顾以流涕兮，","content":"哀高丘之无女。"},
    {"title":"溘吾游此春宫兮，","content":"折琼枝以继佩。"},
    {"title":"及荣华之未落兮，","content":"相下女之可诒。"},
    {"title":"吾令丰隆乘云兮，","content":"求宓妃之所在。"},
    {"title":"解佩纕以结言兮，","content":"吾令謇修以为理。"},
    {"title":"纷总总其离合兮，","content":"忽纬繣其难迁。"},
    {"title":"夕归次于穷石兮，","content":"朝濯发乎洧盘。"},
    {"title":"保厥美以骄傲兮，","content":"日康娱以淫游。"},
    {"title":"虽信美而无礼兮，","content":"来违弃而改求。"},
    {"title":"览相观于四极兮，","content":"周流乎天余乃下。"},
    {"title":"望瑶台之偃蹇兮，","content":"见有娀之佚女。"},
    {"title":"吾令鸩为媒兮，","content":"鸩告余以不好。"},
    {"title":"雄鸠之鸣逝兮，","content":"余犹恶其佻巧。"},
    {"title":"心犹豫而狐疑兮，","content":"欲自适而不可。"},
    {"title":"凤皇既受诒兮，","content":"恐高辛之先我。"},
    {"title":"欲远集而无所止兮，","content":"聊浮游以逍遥。"},
    {"title":"及少康之未家兮，","content":"留有虞之二姚。"},
    {"title":"理弱而媒拙兮，","content":"恐导言之不固。"},
    {"title":"世溷浊而嫉贤兮，","content":"好蔽美而称恶。"},
    {"title":"闺中既以邃远兮，","content":"哲王又不寤。"},
    {"title":"怀朕情而不发兮，","content":"余焉能忍而与此终古？"},
    {"title":"索琼茅以筳篿兮，","content":"命灵氛为余占之。"},
    {"title":"曰：两美其必合兮，","content":"孰信修而慕之？"},
    {"title":"思九州之博大兮，","content":"岂惟是其有女？"},
    {"title":"曰：勉远逝而无狐疑兮，","content":"孰求美而释女？"},
    {"title":"何所独无芳草兮，","content":"尔何怀乎故宇？"},
    {"title":"世幽昧以昡曜兮，","content":"孰云察余之善恶？"},
    {"title":"民好恶其不同兮，","content":"惟此党人其独异！"},
    {"title":"户服艾以盈要兮，","content":"谓幽兰其不可佩。"},
    {"title":"览察草木其犹未得兮，","content":"岂珵美之能当？"},
    {"title":"苏粪壤以充帏兮，","content":"谓申椒其不芳。"},
    {"title":"欲从灵氛之吉占兮，","content":"心犹豫而狐疑。"},
    {"title":"巫咸将夕降兮，","content":"怀椒糈而要之。"},
    {"title":"百神翳其备降兮，","content":"九疑缤其并迎。"},
    {"title":"皇剡剡其扬灵兮，","content":"告余以吉故。"},
    {"title":"曰：勉升降以上下兮，","content":"求矩矱之所同。"},
    {"title":"汤禹俨而求合兮，","content":"挚咎繇而能调。"},
    {"title":"苟中情其好修兮，","content":"又何必用夫行媒？"},
    {"title":"说操筑于傅岩兮，","content":"武丁用而不疑。"},
    {"title":"吕望之鼓刀兮，","content":"遭周文而得举。"},
    {"title":"宁戚之讴歌兮，","content":"齐桓闻以该辅。"},
    {"title":"及年岁之未晏兮，","content":"时亦犹其未央。"},
    {"title":"恐鹈鴂之先鸣兮，","content":"使夫百草为之不芳。"},
    {"title":"何琼佩之偃蹇兮，","content":"众薆然而蔽之。"},
    {"title":"惟此党人之不谅兮，","content":"恐嫉妒而折之。"},
    {"title":"时缤纷其变易兮，","content":"又何可以淹留？"},
    {"title":"兰芷变而不芳兮，","content":"荃蕙化而为茅。"},
    {"title":"何昔日之芳草兮，","content":"今直为此萧艾也？"},
    {"title":"岂其有他故兮，","content":"莫好修之害也！"},
    {"title":"余以兰为可恃兮，","content":"羌无实而容长。"},
    {"title":"委厥美以从俗兮，","content":"苟得列乎众芳。"},
    {"title":"椒专佞以慢慆兮，","content":"樧又欲充夫佩帏。"},
    {"title":"既干进而务入兮，","content":"又何芳之能祗？"},
    {"title":"固时俗之流从兮，","content":"又孰能无变化？"},
    {"title":"览椒兰其若兹兮，","content":"又况揭车与江离？"},
    {"title":"惟兹佩之可贵兮，","content":"委厥美而历兹。"},
    {"title":"芳菲菲而难亏兮，","content":"芬至今犹未沬。"},
    {"title":"和调度以自娱兮，","content":"聊浮游而求女。"},
    {"title":"及余饰之方壮兮，","content":"周流观乎上下。"},
    {"title":"灵氛既告余以吉占兮，","content":"历吉日乎吾将行。"},
    {"title":"折琼枝以为羞兮，","content":"精琼爢以为粻。"},
    {"title":"为余驾飞龙兮，","content":"杂瑶象以为车。"},
    {"title":"何离心之可同兮？","content":"吾将远逝以自疏。"},
    {"title":"邅吾道夫昆仑兮，","content":"路修远以周流。"},
    {"title":"扬云霓之晻蔼兮，","content":"鸣玉鸾之啾啾。"},
    {"title":"朝发轫于天津兮，","content":"夕余至乎西极。"},
    {"title":"凤皇翼其承旗兮，","content":"高翱翔之翼翼。"},
    {"title":"忽吾行此流沙兮，","content":"遵赤水而容与。"},
    {"title":"麾蛟龙使梁津兮，","content":"诏西皇使涉予。"},
    {"title":"路修远以多艰兮，","content":"腾众车使径待。"},
    {"title":"路不周以左转兮，","content":"指西海以为期。"},
    {"title":"屯余车其千乘兮，","content":"齐玉轪而并驰。"},
    {"title":"驾八龙之婉婉兮，","content":"载云旗之委蛇。"},
    {"title":"抑志而弭节兮，","content":"神高驰之邈邈。"},
    {"title":"奏《九歌》而舞《韶》兮，","content":"聊假日以媮乐。"},
    {"title":"陟升皇之赫戏兮，","content":"忽临睨夫旧乡。"},
    {"title":"仆夫悲余马怀兮，","content":"蜷局顾而不行。"},
    {"title":"乱曰：已矣哉！","content":"国无人莫我知兮，又何怀乎故都！"},
    {"title":"既莫足与为美政兮，","content":"吾将从彭咸之所居！"},
    {"title":"君子曰：学不可以已。","content":"青，取之于蓝，而青于蓝；冰，水为之，而寒于水。"},
    {"title":"木直中绳，𫐓以为轮，其曲中规。","content":"虽有槁暴，不复挺者，𫐓使之然也。"},
    {"title":"故木受绳则直，金就砺则利。","content":"君子博学而日参省乎己，则知明而行无过矣。"},
    {"title":"故不登高山，不知天之高也；","content":"不临深溪，不知地之厚也；不闻先王之遗言，不知学问之大也。"},
    {"title":"干、越、夷、貉之子，生而同声，","content":"长而异俗，教使之然也。诗曰：“嗟尔君子，无恒安息。靖共尔位，好是正直。神之听之，介尔景福。”神莫大于化道，福莫长于无祸。"},
    {"title":"吾尝终日而思矣，不如须臾之所学也；","content":"吾尝跂而望矣，不如登高之博见也。登高而招，臂非加长也，而见者远；顺风而呼，声非加疾也，而闻者彰。"},
    {"title":"假舆马者，非利足也，而致千里；","content":"假舟楫者，非能水也，而绝江河。君子生非异也，善假于物也。"},
    {"title":"南方有鸟焉，名曰蒙鸠，以羽为巢，","content":"而编之以发，系之苇苕，风至苕折，卵破子死。巢非不完也，所系者然也。"},
    {"title":"西方有木焉，名曰射干，茎长四寸，","content":"生于高山之上，而临百仞之渊，木茎非能长也，所立者然也。"},
    {"title":"蓬生麻中，不扶而直；白沙在涅，","content":"与之俱黑。兰槐之根是为芷，其渐之滫，君子不近，庶人不服。其质非不美也，所渐者然也。"},
    {"title":"故君子居必择乡，游必就士，","content":"所以防邪辟而近中正也。物类之起，必有所始。荣辱之来，必象其德。"},
    {"title":"肉腐出虫，鱼枯生蠹。怠慢忘身，","content":"祸灾乃作。强自取柱，柔自取束。邪秽在身，怨之所构。施薪若一，火就燥也，平地若一，水就湿也。"},
    {"title":"草木畴生，禽兽群焉，物各从其类也。","content":"是故质的张，而弓矢至焉；林木茂，而斧斤至焉；树成荫，而众鸟息焉。醯酸，而蜹聚焉。故言有招祸也，行有招辱也，君子慎其所立乎！"},
    {"title":"积土成山，风雨兴焉；积水成渊，","content":"蛟龙生焉；积善成德，而神明自得，圣心备焉。故不积跬步，无以至千里；不积小流，无以成江海。"},
    {"title":"骐骥一跃，不能十步；驽马十驾，","content":"功在不舍。锲而舍之，朽木不折；锲而不舍，金石可镂。蚓无爪牙之利，筋骨之强，上食埃土，下饮黄泉，用心一也。"},
    {"title":"蟹六跪而二螯，非蛇鳝之穴无可寄托者，","content":"用心躁也。是故无冥冥之志者，无昭昭之明；无惛惛之事者，无赫赫之功。行衢道者不至，事两君者不容。"},
    {"title":"目不能两视而明，耳不能两听而聪。","content":"螣蛇无足而飞，鼫鼠五技而穷。《诗》曰：“尸鸠在桑，其子七兮。淑人君子，其仪一兮。其仪一兮，心如结兮！”故君子结于一也。"},
    {"title":"昔者瓠巴鼓瑟，而流鱼出听；伯牙鼓琴，","content":"而六马仰秣。故声无小而不闻，行无隐而不形。玉在山而草木润，渊生珠而崖不枯。为善不积邪？安有不闻者乎？"},
    {"title":"学恶乎始？恶乎终？曰：其数则始乎诵经，","content":"终乎读礼；其义则始乎为士，终乎为圣人，真积力久则入，学至乎没而后止也。故学数有终，若其义则不可须臾舍也。为之，人也；舍之，禽兽也。"},
    {"title":"故书者，政事之纪也；诗者，中声之所止也；","content":"礼者，法之大分，类之纲纪也。故学至乎礼而止矣。夫是之谓道德之极。礼之敬文也，乐之中和也，诗书之博也，春秋之微也，在天地之间者毕矣。"},
    {"title":"君子之学也，入乎耳，箸乎心，布乎四体，","content":"形乎动静。端而言，蝡而动，一可以为法则。小人之学也，入乎耳，出乎口；口耳之间，则四寸耳，曷足以美七尺之躯哉！古之学者为己，今之学者为人。"},
    {"title":"君子之学也，以美其身；小人之学也，以为禽犊。","content":"故不问而告谓之傲，问一而告二谓之囋。傲非也，囋非也；君子如向矣。"},
    {"title":"学莫便乎近其人。礼乐法而不说，诗书故而不切，","content":"春秋约而不速。方其人之习君子之说，则尊以遍矣，周于世矣。故曰：学莫便乎近其人。"},
    {"title":"学之经莫速乎好其人，隆礼次之。","content":"上不能好其人，下不能隆礼，安特将学杂识志，顺诗书而已耳。则末世穷年，不免为陋儒而已。将原先王，本仁义，则礼正其经纬蹊径也。若挈裘领，诎五指而顿之，顺者不可胜数也。"},
    {"title":"不道礼宪，以诗书为之，譬之犹以指测河也，","content":"以戈舂黍也，以锥餐壶也，不可以得之矣。故隆礼，虽未明，法士也；不隆礼，虽察辩，散儒也。"},
    {"title":"问楛者，勿告也；告楛者，勿问也；说楛者，勿听也。","content":"有争气者，勿与辩也。故必由其道至，然后接之；非其道则避之。故礼恭，而后可与言道之方；辞顺，而后可与言道之理；色从而后可与言道之致。"},
    {"title":"故未可与言而言，谓之傲；可与言而不言，谓之隐；","content":"不观气色而言，谓瞽。故君子不傲、不隐、不瞽，谨顺其身。诗曰：“匪交匪舒，天子所予。”此之谓也。"},
    {"title":"百发失一，不足谓善射；千里蹞步不至，不足谓善御；","content":"伦类不通，仁义不一，不足谓善学。学也者，固学一之也。一出焉，一入焉，涂巷之人也；其善者少，不善者多，桀纣盗跖也；全之尽之，然后学者也。"},
    {"title":"君子知夫不全不粹之不足以为美也，","content":"故诵数以贯之，思索以通之，为其人以处之，除其害者以持养之。使目非是无欲见也，使耳非是无欲闻也，使口非是无欲言也，使心非是无欲虑也。"},
    {"title":"及至其致好之也，目好之五色，耳好之五声，口好之五味，","content":"心利之有天下。是故权利不能倾也，群众不能移也，天下不能荡也。生乎由是，死乎由是，夫是之谓德操。德操然后能定，能定然后能应。能定能应，夫是之谓成人。天见其明，地见其光，君子贵其全也。"},

]
